revoke all on function public.seed_default_categories(uuid, public.workspace_type) from public, anon, authenticated;

-- New users: profile first (members reference it), then the two workspaces.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  personal_id uuid;
  business_id uuid;
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(public.default_display_name(new.id), 'Member'))
  on conflict (id) do nothing;
  insert into public.workspaces (user_id, name, type) values (new.id, 'ផ្ទាល់ខ្លួន', 'PERSONAL')
    returning id into personal_id;
  insert into public.workspaces (user_id, name, type) values (new.id, 'អាជីវកម្ម', 'BUSINESS')
    returning id into business_id;
  perform public.seed_default_categories(personal_id, 'PERSONAL');
  perform public.seed_default_categories(business_id, 'BUSINESS');
  return new;
end;
$$;

create or replace function public.create_family_workspace(p_name text)
returns public.workspaces
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  result public.workspaces;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if exists (select 1 from public.workspaces where user_id = uid and type = 'FAMILY') then
    raise exception 'family_exists' using errcode = '23505';
  end if;
  insert into public.workspaces (user_id, name, type)
  values (uid, coalesce(nullif(left(trim(p_name), 60), ''), 'គ្រួសារ'), 'FAMILY')
  returning * into result;
  perform public.seed_default_categories(result.id, 'FAMILY');
  return result;
end;
$$;
revoke all on function public.create_family_workspace(text) from public, anon;
grant execute on function public.create_family_workspace(text) to authenticated;

-- Only the owner's family workspace can be deleted (Personal/Business always
-- exist). Everything in it goes, including members' personal wallets.
create or replace function public.delete_family_workspace(p_workspace_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.workspaces
    where id = p_workspace_id and user_id = (select auth.uid()) and type = 'FAMILY'
  ) then
    raise exception 'only the owner can delete the family workspace' using errcode = '42501';
  end if;
  perform set_config('luysmart.system', 'on', true);
  -- Ledger first (cascades repayments), then debts: wallets are referenced
  -- with NO ACTION, which a single cascading delete would trip over.
  delete from public.transactions where workspace_id = p_workspace_id;
  delete from public.debts where workspace_id = p_workspace_id;
  delete from public.workspaces where id = p_workspace_id;
  perform set_config('luysmart.system', '', true);
end;
$$;
revoke all on function public.delete_family_workspace(uuid) from public, anon;
grant execute on function public.delete_family_workspace(uuid) to authenticated;

-- Single-use codes: 6 characters without look-alikes (no I, O, 0, 1).
create table if not exists public.workspace_invites (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  code         text not null unique check (code ~ '^[A-HJ-NP-Z2-9]{6}$'),
  role         public.workspace_role not null default 'MEMBER' check (role in ('MEMBER', 'VIEWER')),
  created_by   uuid not null references auth.users (id) on delete cascade,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null default now() + interval '7 days',
  used_by      uuid references auth.users (id) on delete set null,
  used_at      timestamptz
);
create index if not exists workspace_invites_workspace_id_idx on public.workspace_invites (workspace_id);
alter table public.workspace_invites enable row level security;
drop policy if exists workspace_invites_select on public.workspace_invites;
create policy workspace_invites_select on public.workspace_invites
  for select to authenticated using (public.owns_workspace(workspace_id));
drop policy if exists workspace_invites_delete on public.workspace_invites;
create policy workspace_invites_delete on public.workspace_invites
  for delete to authenticated using (public.owns_workspace(workspace_id));

-- Failed code lookups, to slow down guessing (10 per hour per user).
create table if not exists public.invite_failures (
  user_id      uuid not null references auth.users (id) on delete cascade,
  attempted_at timestamptz not null default now()
);
create index if not exists invite_failures_user_idx on public.invite_failures (user_id, attempted_at);
alter table public.invite_failures enable row level security;

create or replace function public.create_workspace_invite(p_workspace_id uuid, p_role public.workspace_role default 'MEMBER')
returns public.workspace_invites
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  bytes bytea;
  new_code text;
  result public.workspace_invites;
begin
  if not public.owns_workspace(p_workspace_id) then
    raise exception 'only the owner can invite' using errcode = '42501';
  end if;
  if not exists (select 1 from public.workspaces where id = p_workspace_id and type = 'FAMILY') then
    raise exception 'only a family workspace can be shared' using errcode = '22023';
  end if;
  if p_role not in ('MEMBER', 'VIEWER') then
    raise exception 'invalid role' using errcode = '22023';
  end if;
  if (select count(*) from public.workspace_invites
      where workspace_id = p_workspace_id and used_at is null and expires_at > now()) >= 10 then
    raise exception 'too_many_invites' using errcode = '22023';
  end if;

  for attempt in 1..10 loop
    -- The first 6 bytes of a v4 UUID are random; 256 is a multiple of 32, so no bias.
    bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    new_code := '';
    for i in 0..5 loop
      new_code := new_code || substr(alphabet, get_byte(bytes, i) % 32 + 1, 1);
    end loop;
    begin
      insert into public.workspace_invites (workspace_id, code, role, created_by)
      values (p_workspace_id, new_code, p_role, uid)
      returning * into result;
      return result;
    exception when unique_violation then
      -- try another code
    end;
  end loop;
  raise exception 'could not generate a code' using errcode = 'P0001';
end;
$$;
revoke all on function public.create_workspace_invite(uuid, public.workspace_role) from public, anon;
grant execute on function public.create_workspace_invite(uuid, public.workspace_role) to authenticated;

-- Looks up a code. Returns {status: ok|invalid|expired|used|rate_limited, ...}.
-- Failures are counted (not raised) so they survive the transaction.
create or replace function public.lookup_workspace_invite(p_code text, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  normalized text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  inv public.workspace_invites;
  ws public.workspaces;
  inviter text;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if (select count(*) from public.invite_failures
      where user_id = uid and attempted_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('status', 'rate_limited');
  end if;

  select * into inv from public.workspace_invites where code = normalized for update;
  if not found then
    insert into public.invite_failures (user_id) values (uid);
    return jsonb_build_object('status', 'invalid');
  end if;
  select * into ws from public.workspaces where id = inv.workspace_id;

  if exists (select 1 from public.workspace_members where workspace_id = inv.workspace_id and user_id = uid) then
    return jsonb_build_object('status', 'already_member', 'workspace_id', ws.id, 'workspace_name', ws.name);
  end if;
  if inv.used_at is not null then
    return jsonb_build_object('status', 'used');
  end if;
  if inv.expires_at <= now() then
    return jsonb_build_object('status', 'expired');
  end if;

  select display_name into inviter from public.profiles where id = inv.created_by;
  if not p_accept then
    return jsonb_build_object(
      'status', 'ok', 'workspace_id', ws.id, 'workspace_name', ws.name,
      'inviter_name', coalesce(inviter, ''), 'role', inv.role
    );
  end if;

  insert into public.profiles (id, display_name)
  values (uid, coalesce(public.default_display_name(uid), 'Member'))
  on conflict (id) do nothing;
  insert into public.workspace_members (workspace_id, user_id, role) values (inv.workspace_id, uid, inv.role);
  update public.workspace_invites set used_by = uid, used_at = now() where id = inv.id;
  return jsonb_build_object('status', 'ok', 'workspace_id', ws.id, 'workspace_name', ws.name, 'role', inv.role);
end;
$$;
revoke all on function public.lookup_workspace_invite(text, boolean) from public, anon;
grant execute on function public.lookup_workspace_invite(text, boolean) to authenticated;

-- A member who leaves (or is removed) keeps nothing private behind: their
-- personal wallets become shared, and their own alerts there are removed.
create or replace function public.on_member_removed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform set_config('luysmart.system', 'on', true);
  update public.wallets_accounts set visibility = 'SHARED'
  where workspace_id = old.workspace_id and owner_id = old.user_id and visibility = 'PERSONAL';
  perform set_config('luysmart.system', '', true);
  delete from public.notifications where workspace_id = old.workspace_id and user_id = old.user_id;
  return null;
end;
$$;

create or replace trigger workspace_members_removed
  after delete on public.workspace_members
  for each row execute function public.on_member_removed();

-- ---------------------------------------------------------------------------
-- Activity alerts: when someone records income/expense/transfer in a family
-- workspace, every other member gets an in-app alert and, if they set up
-- Telegram, a message from their own bot.
-- ---------------------------------------------------------------------------
create or replace function public.notify_workspace_activity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  ws_type public.workspace_type;
  actor text := coalesce(new.created_by_name, 'Member');
  amount_text text := public.format_money_text(new.amount, new.currency);
  cat_name text;
  from_name text;
  to_name text;
  m record;
  lang text;
  title text;
  body text;
  esc_title text;
  esc_body text;
begin
  select type into ws_type from public.workspaces where id = new.workspace_id;
  if ws_type is distinct from 'FAMILY' or new.created_by is null then
    return null;
  end if;
  select name into cat_name from public.categories where id = new.category_id;
  select name into from_name from public.wallets_accounts where id = new.wallet_id;
  select name into to_name from public.wallets_accounts where id = new.to_wallet_id;

  for m in
    select wm.user_id, ts.bot_token, ts.chat_id, ts.enabled, ts.language
    from public.workspace_members wm
    left join public.telegram_settings ts on ts.user_id = wm.user_id
    where wm.workspace_id = new.workspace_id and wm.user_id <> new.created_by
  loop
    lang := coalesce(m.language, 'km');
    if lang = 'km' then
      title := actor || case new.type
        when 'EXPENSE' then ' បានកត់ចំណាយ ' || amount_text || coalesce(' លើ «' || cat_name || '»', '')
        when 'INCOME' then ' បានកត់ចំណូល ' || amount_text || coalesce(' ពី «' || cat_name || '»', '')
        else ' បានផ្ទេរ ' || amount_text || ' ពី «' || coalesce(from_name, '?') || '» ទៅ «' || coalesce(to_name, '?') || '»'
      end;
      body := case when new.type = 'TRANSFER' then '' else 'កាបូប: ' || coalesce(from_name, '?') end
        || coalesce(case when new.type = 'TRANSFER' then '' else E'\n' end || 'កំណត់ចំណាំ: ' || nullif(new.note, ''), '');
    else
      title := actor || case new.type
        when 'EXPENSE' then ' recorded an expense of ' || amount_text || coalesce(' on "' || cat_name || '"', '')
        when 'INCOME' then ' recorded income of ' || amount_text || coalesce(' from "' || cat_name || '"', '')
        else ' transferred ' || amount_text || ' from "' || coalesce(from_name, '?') || '" to "' || coalesce(to_name, '?') || '"'
      end;
      body := case when new.type = 'TRANSFER' then '' else 'Wallet: ' || coalesce(from_name, '?') end
        || coalesce(case when new.type = 'TRANSFER' then '' else E'\n' end || 'Note: ' || nullif(new.note, ''), '');
    end if;

    insert into public.notifications (workspace_id, user_id, transaction_id, actor_name, title, message, type, scheduled_at)
    values (new.workspace_id, m.user_id, new.id, left(actor, 40), left(title, 300), left(body, 2000), 'ACTIVITY', now());

    if m.bot_token is not null and m.enabled then
      esc_title := replace(replace(replace(title, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
      esc_body := replace(replace(replace(body, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || m.bot_token || '/sendMessage',
        body := jsonb_build_object(
          'chat_id', m.chat_id,
          'parse_mode', 'HTML',
          'text', '🔔 <b>' || esc_title || '</b>' || case when esc_body = '' then '' else E'\n' || esc_body end
            || E'\n\n— លុយឆ្លាត · LuyChlat'
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
    end if;
  end loop;
  return null;
end;
$$;

create or replace trigger transactions_notify_activity
  after insert on public.transactions
  for each row execute function public.notify_workspace_activity();

-- ---------------------------------------------------------------------------
-- Daily debt alerts: Telegram now goes to every member who set up a bot.
-- ---------------------------------------------------------------------------
create or replace function public.debt_alert_text(d public.debts, p_stage text, p_days integer, p_lang text, out title text, out body text)
language plpgsql
stable
set search_path = ''
as $$
declare
  safe_name text := replace(replace(replace(d.party_name, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
  left_amount numeric := d.total_amount - d.paid_amount;
begin
  if p_lang = 'km' then
    title := case p_stage
      when 'OVERDUE' then '🔴 បំណុលហួសកំណត់'
      when 'D0' then '🔴 ដល់ថ្ងៃកំណត់ថ្ងៃនេះ'
      else '🟠 ជិតដល់ថ្ងៃកំណត់ (' || p_days || ' ថ្ងៃទៀត)'
    end;
    body := case when d.type = 'PAYABLE' then '📤 ត្រូវសងគេ: ' else '📥 គេជំពាក់យើង: ' end || safe_name
      || E'\n💰 នៅខ្វះ: ' || public.format_money_text(left_amount, d.currency)
      || ' / ' || public.format_money_text(d.total_amount, d.currency)
      || E'\n📅 ថ្ងៃកំណត់: ' || to_char(d.due_date, 'DD/MM/YYYY');
  else
    title := case p_stage
      when 'OVERDUE' then '🔴 Debt overdue'
      when 'D0' then '🔴 Due today'
      else '🟠 Due soon (' || p_days || ' days left)'
    end;
    body := case when d.type = 'PAYABLE' then '📤 I owe: ' else '📥 Owed to me: ' end || safe_name
      || E'\n💰 Remaining: ' || public.format_money_text(left_amount, d.currency)
      || ' of ' || public.format_money_text(d.total_amount, d.currency)
      || E'\n📅 Due: ' || to_char(d.due_date, 'DD/MM/YYYY');
  end if;
end;
$$;

create or replace function public.run_debt_alerts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'Asia/Phnom_Penh')::date;
  d public.debts;
  m record;
  stage text;
  days integer;
  txt record;
  new_id uuid;
  sent integer := 0;
begin
  -- Keep stored statuses fresh (OVERDUE depends on the date).
  update public.debts set paid_amount = paid_amount
  where status in ('ACTIVE', 'PARTIALLY_PAID') and due_date < current_date;

  for d in select * from public.debts where status <> 'SETTLED' and due_date is not null loop
    stage := public.debt_alert_stage(d.due_date, today);
    continue when stage is null;
    days := d.due_date - today;

    -- In-app text is re-rendered in the viewer's language by the app.
    select * into txt from public.debt_alert_text(d, stage, days, 'km');
    new_id := null;
    insert into public.notifications (workspace_id, debt_id, title, message, type, alert_key, scheduled_at)
    values (d.workspace_id, d.id, txt.title, txt.body, 'DUE_DATE', stage, now())
    on conflict (debt_id, alert_key) do nothing
    returning id into new_id;
    continue when new_id is null;

    for m in
      select ts.bot_token, ts.chat_id, ts.language
      from public.workspace_members wm
      join public.telegram_settings ts on ts.user_id = wm.user_id
      where wm.workspace_id = d.workspace_id and ts.enabled
    loop
      select * into txt from public.debt_alert_text(d, stage, days, m.language);
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || m.bot_token || '/sendMessage',
        body := jsonb_build_object(
          'chat_id', m.chat_id,
          'parse_mode', 'HTML',
          'text', '<b>' || txt.title || E'</b>\n' || txt.body || E'\n\n— លុយឆ្លាត · LuyChlat'
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
      sent := sent + 1;
    end loop;
  end loop;
  return sent;
end;
$$;
revoke all on function public.run_debt_alerts() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Reset: only the caller's Personal and Business data. A shared family
-- ledger is removed by deleting the family workspace instead.
-- ---------------------------------------------------------------------------
create or replace function public.reset_my_data()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  ws record;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  create temporary table reset_ws on commit drop as
    select id, type from public.workspaces where user_id = uid and type <> 'FAMILY';

  delete from public.notifications where workspace_id in (select id from reset_ws);
  delete from public.transactions where workspace_id in (select id from reset_ws);
  delete from public.debts where workspace_id in (select id from reset_ws);
  delete from public.budgets where workspace_id in (select id from reset_ws);
  delete from public.wallets_accounts where workspace_id in (select id from reset_ws);
  delete from public.categories where workspace_id in (select id from reset_ws);
  delete from public.telegram_settings where user_id = uid;

  for ws in select id, type from reset_ws loop
    perform public.seed_default_categories(ws.id, ws.type);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- Category budgets: a monthly spending cap per expense category.
-- ---------------------------------------------------------------------------
create table if not exists public.budgets (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  category_id  uuid not null,
  amount       numeric(18, 2) not null check (amount > 0),
  currency     public.currency_code not null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (workspace_id, category_id),
  foreign key (category_id, workspace_id) references public.categories (id, workspace_id) on delete cascade
);
alter table public.budgets enable row level security;
drop policy if exists budgets_select on public.budgets;
create policy budgets_select on public.budgets
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists budgets_insert on public.budgets;
create policy budgets_insert on public.budgets
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists budgets_update on public.budgets;
create policy budgets_update on public.budgets
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists budgets_delete on public.budgets;
create policy budgets_delete on public.budgets
  for delete to authenticated using (public.can_write_workspace(workspace_id));

create or replace function public.guard_budget_category()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (select 1 from public.categories c where c.id = new.category_id and c.type = 'EXPENSE') then
    raise exception 'budgets apply to expense categories' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create or replace trigger budgets_guard
  before insert or update on public.budgets
  for each row execute function public.guard_budget_category();

-- ---------------------------------------------------------------------------
-- Receipts: members may view photos attached to their workspace's ledger.
-- ---------------------------------------------------------------------------
create index if not exists transactions_receipt_url_idx on public.transactions (receipt_url) where receipt_url is not null;
drop policy if exists receipts_select_shared on storage.objects;
create policy receipts_select_shared on storage.objects
  for select to authenticated
  using (
    bucket_id = 'receipts'
    and exists (
      select 1 from public.transactions t
      where t.receipt_url = objects.name and public.is_workspace_member(t.workspace_id)
    )
  );

-- ---------------------------------------------------------------------------
-- Realtime: changes reach the other members' devices (RLS still applies).
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    return;
  end if;
  foreach t in array array[
    'transactions', 'wallets_accounts', 'categories', 'debts', 'debt_repayments',
    'notifications', 'workspace_members', 'budgets'
  ]
  loop
    if not exists (
      select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end
$$;


-- ===========================================================================
-- 20261001080000_guest_import.sql
-- ===========================================================================

-- Guest Mode -> account: moves a guest's data into a signed-in account.
--
-- public.import_guest_data() imports one workspace's worth of guest data in a
-- single transaction (all or nothing). It runs as the caller, so RLS still
-- decides where they may write. Guest ids are kept, and every insert is
-- "on conflict do nothing", so importing the same data twice adds nothing.
-- Wallets arrive with their opening balance and the ledger is replayed in
-- creation order, so the balance triggers end on the guest's balances.

create or replace function public.adjust_wallet_balances(t public.transactions, direction integer)
returns void
language plpgsql
set search_path = ''
as $$
declare
  source_currency public.currency_code;
  target_currency public.currency_code;
  delta numeric;
begin
  select currency into source_currency from public.wallets_accounts where id = t.wallet_id;

  if t.type in ('INCOME', 'EXPENSE') then
    if t.currency <> source_currency and t.exchange_rate is null then
      raise exception 'exchange_rate is required when currency differs from the wallet' using errcode = '22023';
    end if;
    delta := public.amount_in_wallet_currency(t.amount, t.currency, t.exchange_rate, source_currency);
    if t.type = 'EXPENSE' then
      delta := -delta;
    end if;
    update public.wallets_accounts set balance = balance + direction * delta where id = t.wallet_id;
    return;
  end if;

  -- TRANSFER
  if direction > 0 then
    if source_currency is distinct from t.currency then
      raise exception 'transfer currency % does not match wallet currency %', t.currency, source_currency
        using errcode = '22023';
    end if;
    select currency into target_currency from public.wallets_accounts where id = t.to_wallet_id;
    if target_currency is distinct from t.currency and t.exchange_rate is null then
      raise exception 'cross-currency transfer requires exchange_rate' using errcode = '22023';
    end if;
  end if;
  update public.wallets_accounts set balance = balance - direction * t.amount where id = t.wallet_id;
  update public.wallets_accounts set balance = balance + direction * t.to_amount where id = t.to_wallet_id;
  -- A Guest Mode import replays history in creation order, which can dip
  -- below zero in between (e.g. after an edited income); skip the check then.
  if direction > 0 and coalesce(current_setting('luysmart.import', true), '') <> 'on' and exists (
    select 1 from public.wallets_accounts where id = t.wallet_id and balance < 0
  ) then
    raise exception 'insufficient_balance' using errcode = 'P0001';
  end if;
end;
$$;

create or replace function public.notify_workspace_activity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  ws_type public.workspace_type;
  actor text := coalesce(new.created_by_name, 'Member');
  amount_text text := public.format_money_text(new.amount, new.currency);
  cat_name text;
  from_name text;
  to_name text;
  m record;
  lang text;
  title text;
  body text;
  esc_title text;
  esc_body text;
begin
  -- Imported history isn't news for the other members.
  if coalesce(current_setting('luysmart.import', true), '') = 'on' then
    return null;
  end if;
  select type into ws_type from public.workspaces where id = new.workspace_id;
  if ws_type is distinct from 'FAMILY' or new.created_by is null then
    return null;
  end if;
  select name into cat_name from public.categories where id = new.category_id;
  select name into from_name from public.wallets_accounts where id = new.wallet_id;
  select name into to_name from public.wallets_accounts where id = new.to_wallet_id;

  for m in
    select wm.user_id, ts.bot_token, ts.chat_id, ts.enabled, ts.language
    from public.workspace_members wm
    left join public.telegram_settings ts on ts.user_id = wm.user_id
    where wm.workspace_id = new.workspace_id and wm.user_id <> new.created_by
  loop
    lang := coalesce(m.language, 'km');
    if lang = 'km' then
      title := actor || case new.type
        when 'EXPENSE' then ' បានកត់ចំណាយ ' || amount_text || coalesce(' លើ «' || cat_name || '»', '')
        when 'INCOME' then ' បានកត់ចំណូល ' || amount_text || coalesce(' ពី «' || cat_name || '»', '')
        else ' បានផ្ទេរ ' || amount_text || ' ពី «' || coalesce(from_name, '?') || '» ទៅ «' || coalesce(to_name, '?') || '»'
      end;
      body := case when new.type = 'TRANSFER' then '' else 'កាបូប: ' || coalesce(from_name, '?') end
        || coalesce(case when new.type = 'TRANSFER' then '' else E'\n' end || 'កំណត់ចំណាំ: ' || nullif(new.note, ''), '');
    else
      title := actor || case new.type
        when 'EXPENSE' then ' recorded an expense of ' || amount_text || coalesce(' on "' || cat_name || '"', '')
        when 'INCOME' then ' recorded income of ' || amount_text || coalesce(' from "' || cat_name || '"', '')
        else ' transferred ' || amount_text || ' from "' || coalesce(from_name, '?') || '" to "' || coalesce(to_name, '?') || '"'
      end;
      body := case when new.type = 'TRANSFER' then '' else 'Wallet: ' || coalesce(from_name, '?') end
        || coalesce(case when new.type = 'TRANSFER' then '' else E'\n' end || 'Note: ' || nullif(new.note, ''), '');
    end if;

    insert into public.notifications (workspace_id, user_id, transaction_id, actor_name, title, message, type, scheduled_at)
    values (new.workspace_id, m.user_id, new.id, left(actor, 40), left(title, 300), left(body, 2000), 'ACTIVITY', now());

    if m.bot_token is not null and m.enabled then
      esc_title := replace(replace(replace(title, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
      esc_body := replace(replace(replace(body, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || m.bot_token || '/sendMessage',
        body := jsonb_build_object(
          'chat_id', m.chat_id,
          'parse_mode', 'HTML',
          'text', '🔔 <b>' || esc_title || '</b>' || case when esc_body = '' then '' else E'\n' || esc_body end
            || E'\n\n— លុយឆ្លាត · LuyChlat'
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
    end if;
  end loop;
  return null;
end;
$$;

create or replace function public.import_guest_data(p_workspace_id uuid, p_data jsonb)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
  c jsonb;
  w jsonb;
  t jsonb;
  d jsonb;
  r jsonb;
  b jsonb;
  mapped uuid;
  added integer;
  next_sort integer;
  n_categories integer := 0;
  n_wallets integer := 0;
  n_transactions integer := 0;
  n_debts integer := 0;
  n_repayments integer := 0;
  n_budgets integer := 0;
begin
  if not public.can_write_workspace(p_workspace_id) then
    raise exception 'no write access to this workspace' using errcode = '42501';
  end if;
  perform set_config('luysmart.import', 'on', true);

  create temporary table if not exists import_category_map (old_id uuid primary key, new_id uuid not null) on commit drop;
  truncate import_category_map;

  -- Categories: reuse the account's preset or same-named category, else add it.
  for c in select value from jsonb_array_elements(coalesce(p_data -> 'categories', '[]'::jsonb)) loop
    mapped := null;
    if c ->> 'preset_key' is not null then
      select id into mapped from public.categories
      where workspace_id = p_workspace_id and preset_key = c ->> 'preset_key' limit 1;
    end if;
    if mapped is null then
      select id into mapped from public.categories
      where workspace_id = p_workspace_id and name = c ->> 'name' and type::text = c ->> 'type' limit 1;
    end if;
    if mapped is null then
      insert into public.categories (workspace_id, name, type, icon, color, preset_key)
      values (p_workspace_id, c ->> 'name', (c ->> 'type')::public.category_type, c ->> 'icon', c ->> 'color', c ->> 'preset_key')
      returning id into mapped;
      n_categories := n_categories + 1;
    end if;
    insert into import_category_map values ((c ->> 'id')::uuid, mapped) on conflict do nothing;
  end loop;

  -- Wallets after the account's own ones, starting from their opening balance.
  select coalesce(max(sort_order) + 1, 0) into next_sort from public.wallets_accounts where workspace_id = p_workspace_id;
  for w in select value from jsonb_array_elements(coalesce(p_data -> 'wallets', '[]'::jsonb)) loop
    insert into public.wallets_accounts (id, workspace_id, name, balance, currency, icon, color, sort_order, archived_at, visibility, created_at)
    values (
      (w ->> 'id')::uuid, p_workspace_id, w ->> 'name', (w ->> 'opening_balance')::numeric,
      (w ->> 'currency')::public.currency_code, w ->> 'icon', w ->> 'color',
      next_sort + coalesce((w ->> 'sort_order')::integer, 0), (w ->> 'archived_at')::timestamptz,
      coalesce(w ->> 'visibility', 'SHARED')::public.wallet_visibility, coalesce((w ->> 'created_at')::timestamptz, now())
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_wallets := n_wallets + added;
  end loop;

  -- Debts before the ledger (ledger rows point at them).
  for d in select value from jsonb_array_elements(coalesce(p_data -> 'debts', '[]'::jsonb)) loop
    insert into public.debts (
      id, workspace_id, type, party_name, contact_phone, total_amount, currency,
      interest_rate, interest_period, start_date, due_date, note, created_at
    ) values (
      (d ->> 'id')::uuid, p_workspace_id, (d ->> 'type')::public.debt_type, d ->> 'party_name', d ->> 'contact_phone',
      (d ->> 'total_amount')::numeric, (d ->> 'currency')::public.currency_code,
      coalesce((d ->> 'interest_rate')::numeric, 0), coalesce(d ->> 'interest_period', 'YEAR')::public.interest_period,
      coalesce((d ->> 'start_date')::date, current_date), (d ->> 'due_date')::date, d ->> 'note',
      coalesce((d ->> 'created_at')::timestamptz, now())
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_debts := n_debts + added;
  end loop;

  -- Ledger, already sorted by creation time by the app.
  for t in select value from jsonb_array_elements(coalesce(p_data -> 'transactions', '[]'::jsonb)) loop
    insert into public.transactions (
      id, workspace_id, wallet_id, to_wallet_id, category_id, amount, to_amount, currency, type,
      exchange_rate, note, receipt_url, transaction_date, created_at, debt_id
    ) values (
      (t ->> 'id')::uuid, p_workspace_id, (t ->> 'wallet_id')::uuid, (t ->> 'to_wallet_id')::uuid,
      (select m.new_id from import_category_map m where m.old_id = (t ->> 'category_id')::uuid),
      (t ->> 'amount')::numeric, (t ->> 'to_amount')::numeric, (t ->> 'currency')::public.currency_code,
      (t ->> 'type')::public.transaction_type, (t ->> 'exchange_rate')::numeric, t ->> 'note', t ->> 'receipt_url',
      (t ->> 'transaction_date')::timestamptz, coalesce((t ->> 'created_at')::timestamptz, now()), (t ->> 'debt_id')::uuid
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_transactions := n_transactions + added;
  end loop;

  for d in select value from jsonb_array_elements(coalesce(p_data -> 'debts', '[]'::jsonb)) loop
    if d ->> 'disbursement_transaction_id' is not null then
      update public.debts set disbursement_transaction_id = (d ->> 'disbursement_transaction_id')::uuid
      where id = (d ->> 'id')::uuid and workspace_id = p_workspace_id and disbursement_transaction_id is null
        and exists (select 1 from public.transactions x where x.id = (d ->> 'disbursement_transaction_id')::uuid);
    end if;
  end loop;

  for r in select value from jsonb_array_elements(coalesce(p_data -> 'repayments', '[]'::jsonb)) loop
    insert into public.debt_repayments (id, debt_id, wallet_id, amount_paid, payment_date, note, transaction_id, created_at)
    values (
      (r ->> 'id')::uuid, (r ->> 'debt_id')::uuid, (r ->> 'wallet_id')::uuid, (r ->> 'amount_paid')::numeric,
      (r ->> 'payment_date')::timestamptz, r ->> 'note', (r ->> 'transaction_id')::uuid,
      coalesce((r ->> 'created_at')::timestamptz, now())
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_repayments := n_repayments + added;
  end loop;

  for b in select value from jsonb_array_elements(coalesce(p_data -> 'budgets', '[]'::jsonb)) loop
    mapped := (select m.new_id from import_category_map m where m.old_id = (b ->> 'category_id')::uuid);
    continue when mapped is null;
    insert into public.budgets (workspace_id, category_id, amount, currency)
    values (p_workspace_id, mapped, (b ->> 'amount')::numeric, (b ->> 'currency')::public.currency_code)
    on conflict do nothing;
    get diagnostics added = row_count;
    n_budgets := n_budgets + added;
  end loop;

  perform set_config('luysmart.import', '', true);
  return jsonb_build_object(
    'categories', n_categories, 'wallets', n_wallets, 'transactions', n_transactions,
    'debts', n_debts, 'repayments', n_repayments, 'budgets', n_budgets
  );
end;
$$;
revoke all on function public.import_guest_data(uuid, jsonb) from public, anon;
grant execute on function public.import_guest_data(uuid, jsonb) to authenticated;


-- ===========================================================================
-- 20261001090000_security_hardening.sql
-- ===========================================================================

-- Security hardening (audit, October 2026). Re-runnable.
--
-- 1. Balances change only through the ledger: the balance trigger runs as the
--    table owner, clients can no longer UPDATE wallets_accounts.balance, and
--    the balance helper can't be called directly.
-- 2. Column-level UPDATE rights: ownership/derived columns (workspace_id,
--    created_by, status, type of a workspace, ...) are read-only for clients.
-- 3. Notifications are written by the database only (no forged alerts).
-- 4. Guest-data import is for workspace owners only.
-- 5. A record's receipt photo must be the caller's own upload.
-- 6. A debt's loan link must point at that debt's own ledger row.
-- 7. Anonymous visitors get no table or function access at all.

-- 1 -------------------------------------------------------------------------
create or replace function public.on_transaction_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.adjust_wallet_balances(old, -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform public.adjust_wallet_balances(new, 1);
  end if;
  return null;
end;
$$;

revoke all on function public.adjust_wallet_balances(public.transactions, integer) from public, anon, authenticated;

-- 2 -------------------------------------------------------------------------
revoke update on public.wallets_accounts from anon, authenticated;
grant update (name, icon, color, sort_order, archived_at, visibility, currency) on public.wallets_accounts to authenticated;

revoke update on public.workspaces from anon, authenticated;
grant update (name, currency_default) on public.workspaces to authenticated;

revoke update on public.transactions from anon, authenticated;
grant update (wallet_id, to_wallet_id, category_id, amount, to_amount, currency, type, exchange_rate, note, receipt_url, transaction_date, debt_id)
  on public.transactions to authenticated;

-- paid_amount stays updatable only because triggers "touch" it; its value is
-- always recomputed from the repayments (debts_derive), and so is status.
revoke update on public.debts from anon, authenticated;
grant update (type, party_name, contact_phone, total_amount, currency, interest_rate, interest_period, start_date, due_date, note, paid_amount, disbursement_transaction_id)
  on public.debts to authenticated;

revoke update on public.categories from anon, authenticated;
grant update (name, type, icon, color, preset_key) on public.categories to authenticated;

revoke update on public.budgets from anon, authenticated;
grant update (workspace_id, category_id, amount, currency) on public.budgets to authenticated;

revoke update on public.workspace_members from anon, authenticated;
grant update (role) on public.workspace_members to authenticated;

-- id is listed because the app saves the name with an upsert (the policy keeps it = auth.uid()).
revoke update on public.profiles from anon, authenticated;
grant update (id, display_name, updated_at) on public.profiles to authenticated;

-- 3 -------------------------------------------------------------------------
drop policy if exists notifications_insert on public.notifications;
drop policy if exists notifications_delete on public.notifications;
revoke insert, delete on public.notifications from anon, authenticated;
revoke update on public.notifications from anon, authenticated;
grant update (is_read) on public.notifications to authenticated;

-- 4 -------------------------------------------------------------------------
create or replace function public.import_guest_data(p_workspace_id uuid, p_data jsonb)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
  c jsonb;
  w jsonb;
  t jsonb;
  d jsonb;
  r jsonb;
  b jsonb;
  mapped uuid;
  added integer;
  next_sort integer;
  n_categories integer := 0;
  n_wallets integer := 0;
  n_transactions integer := 0;
  n_debts integer := 0;
  n_repayments integer := 0;
  n_budgets integer := 0;
begin
  -- Owners only: in a shared family workspace an import would add records
  -- without alerting the other members.
  if not public.owns_workspace(p_workspace_id) then
    raise exception 'no write access to this workspace' using errcode = '42501';
  end if;
  perform set_config('luysmart.import', 'on', true);

  create temporary table if not exists import_category_map (old_id uuid primary key, new_id uuid not null) on commit drop;
  truncate import_category_map;

  -- Categories: reuse the account's preset or same-named category, else add it.
  for c in select value from jsonb_array_elements(coalesce(p_data -> 'categories', '[]'::jsonb)) loop
    mapped := null;
    if c ->> 'preset_key' is not null then
      select id into mapped from public.categories
      where workspace_id = p_workspace_id and preset_key = c ->> 'preset_key' limit 1;
    end if;
    if mapped is null then
      select id into mapped from public.categories
      where workspace_id = p_workspace_id and name = c ->> 'name' and type::text = c ->> 'type' limit 1;
    end if;
    if mapped is null then
      insert into public.categories (workspace_id, name, type, icon, color, preset_key)
      values (p_workspace_id, c ->> 'name', (c ->> 'type')::public.category_type, c ->> 'icon', c ->> 'color', c ->> 'preset_key')
      returning id into mapped;
      n_categories := n_categories + 1;
    end if;
    insert into import_category_map values ((c ->> 'id')::uuid, mapped) on conflict do nothing;
  end loop;

  -- Wallets after the account's own ones, starting from their opening balance.
  select coalesce(max(sort_order) + 1, 0) into next_sort from public.wallets_accounts where workspace_id = p_workspace_id;
  for w in select value from jsonb_array_elements(coalesce(p_data -> 'wallets', '[]'::jsonb)) loop
    insert into public.wallets_accounts (id, workspace_id, name, balance, currency, icon, color, sort_order, archived_at, visibility, created_at)
    values (
      (w ->> 'id')::uuid, p_workspace_id, w ->> 'name', (w ->> 'opening_balance')::numeric,
      (w ->> 'currency')::public.currency_code, w ->> 'icon', w ->> 'color',
      next_sort + coalesce((w ->> 'sort_order')::integer, 0), (w ->> 'archived_at')::timestamptz,
      coalesce(w ->> 'visibility', 'SHARED')::public.wallet_visibility, coalesce((w ->> 'created_at')::timestamptz, now())
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_wallets := n_wallets + added;
  end loop;

  -- Debts before the ledger (ledger rows point at them).
  for d in select value from jsonb_array_elements(coalesce(p_data -> 'debts', '[]'::jsonb)) loop
    insert into public.debts (
      id, workspace_id, type, party_name, contact_phone, total_amount, currency,
      interest_rate, interest_period, start_date, due_date, note, created_at
    ) values (
      (d ->> 'id')::uuid, p_workspace_id, (d ->> 'type')::public.debt_type, d ->> 'party_name', d ->> 'contact_phone',
      (d ->> 'total_amount')::numeric, (d ->> 'currency')::public.currency_code,
      coalesce((d ->> 'interest_rate')::numeric, 0), coalesce(d ->> 'interest_period', 'YEAR')::public.interest_period,
      coalesce((d ->> 'start_date')::date, current_date), (d ->> 'due_date')::date, d ->> 'note',
      coalesce((d ->> 'created_at')::timestamptz, now())
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_debts := n_debts + added;
  end loop;

  -- Ledger, already sorted by creation time by the app.
  for t in select value from jsonb_array_elements(coalesce(p_data -> 'transactions', '[]'::jsonb)) loop
    insert into public.transactions (
      id, workspace_id, wallet_id, to_wallet_id, category_id, amount, to_amount, currency, type,
      exchange_rate, note, receipt_url, transaction_date, created_at, debt_id
    ) values (
      (t ->> 'id')::uuid, p_workspace_id, (t ->> 'wallet_id')::uuid, (t ->> 'to_wallet_id')::uuid,
      (select m.new_id from import_category_map m where m.old_id = (t ->> 'category_id')::uuid),
      (t ->> 'amount')::numeric, (t ->> 'to_amount')::numeric, (t ->> 'currency')::public.currency_code,
      (t ->> 'type')::public.transaction_type, (t ->> 'exchange_rate')::numeric, t ->> 'note', t ->> 'receipt_url',
      (t ->> 'transaction_date')::timestamptz, coalesce((t ->> 'created_at')::timestamptz, now()), (t ->> 'debt_id')::uuid
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_transactions := n_transactions + added;
  end loop;

  for d in select value from jsonb_array_elements(coalesce(p_data -> 'debts', '[]'::jsonb)) loop
    if d ->> 'disbursement_transaction_id' is not null then
      update public.debts set disbursement_transaction_id = (d ->> 'disbursement_transaction_id')::uuid
      where id = (d ->> 'id')::uuid and workspace_id = p_workspace_id and disbursement_transaction_id is null
        and exists (select 1 from public.transactions x where x.id = (d ->> 'disbursement_transaction_id')::uuid);
    end if;
  end loop;

  for r in select value from jsonb_array_elements(coalesce(p_data -> 'repayments', '[]'::jsonb)) loop
    insert into public.debt_repayments (id, debt_id, wallet_id, amount_paid, payment_date, note, transaction_id, created_at)
    values (
      (r ->> 'id')::uuid, (r ->> 'debt_id')::uuid, (r ->> 'wallet_id')::uuid, (r ->> 'amount_paid')::numeric,
      (r ->> 'payment_date')::timestamptz, r ->> 'note', (r ->> 'transaction_id')::uuid,
      coalesce((r ->> 'created_at')::timestamptz, now())
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n_repayments := n_repayments + added;
  end loop;

  for b in select value from jsonb_array_elements(coalesce(p_data -> 'budgets', '[]'::jsonb)) loop
    mapped := (select m.new_id from import_category_map m where m.old_id = (b ->> 'category_id')::uuid);
    continue when mapped is null;
    insert into public.budgets (workspace_id, category_id, amount, currency)
    values (p_workspace_id, mapped, (b ->> 'amount')::numeric, (b ->> 'currency')::public.currency_code)
    on conflict do nothing;
    get diagnostics added = row_count;
    n_budgets := n_budgets + added;
  end loop;

  perform set_config('luysmart.import', '', true);
  return jsonb_build_object(
    'categories', n_categories, 'wallets', n_wallets, 'transactions', n_transactions,
    'debts', n_debts, 'repayments', n_repayments, 'budgets', n_budgets
  );
end;
$$;
revoke all on function public.import_guest_data(uuid, jsonb) from public, anon;
grant execute on function public.import_guest_data(uuid, jsonb) to authenticated;

-- 5 -------------------------------------------------------------------------
create or replace function public.guard_receipt_owner()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.receipt_url is not null
    and (select auth.uid()) is not null
    and (tg_op = 'INSERT' or new.receipt_url is distinct from old.receipt_url)
    and split_part(new.receipt_url, '/', 1) <> (select auth.uid())::text then
    raise exception 'receipt must be your own upload' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace trigger transactions_receipt_guard
  before insert or update of receipt_url on public.transactions
  for each row execute function public.guard_receipt_owner();

-- 6 -------------------------------------------------------------------------
create or replace function public.guard_debt_disbursement()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.disbursement_transaction_id is not null
    and new.disbursement_transaction_id is distinct from old.disbursement_transaction_id
    and not exists (
      select 1 from public.transactions t
      where t.id = new.disbursement_transaction_id and t.debt_id = new.id
    ) then
    raise exception 'disbursement must be this debt''s own ledger row' using errcode = '22023';
  end if;
  return new;
end;
$$;

create or replace trigger debts_disbursement_guard
  before update of disbursement_transaction_id on public.debts
  for each row execute function public.guard_debt_disbursement();

-- 7 -------------------------------------------------------------------------
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;

-- Functions: nothing for anonymous visitors; signed-in users keep what the app
-- uses, minus internal helpers.
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
alter default privileges in schema public revoke execute on functions from public, anon;
revoke all on function public.adjust_wallet_balances(public.transactions, integer) from authenticated;
revoke all on function public.seed_default_categories(uuid, public.workspace_type) from authenticated;
revoke all on function public.default_display_name(uuid) from authenticated;
revoke all on function public.run_debt_alerts() from authenticated;


-- ===========================================================================
-- 20261001100000_subscriptions.sql
-- ===========================================================================

-- Subscriptions (Step A): plans, subscriptions, manual payment approval,
-- usage quotas, admin tools, and plan limits enforced in the database.
-- Re-runnable. Step B (KHQR / Bakong) adds automatic payment on top.
--
-- Plan of a user = their ACTIVE subscription while current_period_end is in
-- the future, otherwise FREE. Nothing has to run when a plan expires.
-- Clients can read only their own rows and can never write plans,
-- subscriptions or payments directly: paid upgrades go through an admin
-- (now) or the payment server (Step B).

-- ---------------------------------------------------------------------------
-- Plans
-- ---------------------------------------------------------------------------
create table if not exists public.plans (
  code                  text primary key,
  tier                  text not null check (tier in ('FREE', 'PRO')),
  name                  text not null,
  price_usd             numeric(10, 2) not null default 0,
  price_khr             numeric(12, 0) not null default 0,
  period_days           integer,
  -- null = unlimited
  max_wallets           integer,
  max_family_members    integer,
  ai_queries_per_month  integer not null default 0,
  can_export            boolean not null default false,
  can_credit_score      boolean not null default false,
  sort_order            integer not null default 0,
  active                boolean not null default true
);
alter table public.plans enable row level security;
drop policy if exists plans_select on public.plans;
create policy plans_select on public.plans for select to authenticated using (true);

insert into public.plans (code, tier, name, price_usd, price_khr, period_days, max_wallets, max_family_members, ai_queries_per_month, can_export, can_credit_score, sort_order)
values
  ('FREE',        'FREE', 'Free',        0,     0,      null, 2,    1,    0,   false, false, 0),
  ('PRO_MONTHLY', 'PRO',  'Pro Monthly', 2.99,  12000,  30,   null, null, 100, true,  true,  1),
  ('PRO_YEARLY',  'PRO',  'Pro Yearly',  24.99, 100000, 365,  null, null, 100, true,  true,  2)
on conflict (code) do nothing;

-- ---------------------------------------------------------------------------
-- Subscriptions, payments, history, usage, admins, settings
-- ---------------------------------------------------------------------------
create table if not exists public.subscriptions (
  user_id              uuid primary key references auth.users (id) on delete cascade,
  plan_code            text not null references public.plans (code),
  status               text not null default 'ACTIVE' check (status in ('ACTIVE', 'CANCELLED')),
  current_period_start timestamptz not null default now(),
  current_period_end   timestamptz not null,
  source               text not null default 'ADMIN' check (source in ('ADMIN', 'KHQR', 'TRIAL', 'REFERRAL')),
  note                 text check (note is null or char_length(note) <= 500),
  updated_at           timestamptz not null default now(),
  updated_by           uuid references auth.users (id) on delete set null
);
alter table public.subscriptions
  drop constraint if exists subscriptions_source_check,
  add constraint subscriptions_source_check check (source in ('ADMIN', 'KHQR', 'TRIAL', 'REFERRAL'));
alter table public.subscriptions enable row level security;
drop policy if exists subscriptions_select_own on public.subscriptions;
create policy subscriptions_select_own on public.subscriptions
  for select to authenticated using (user_id = (select auth.uid()));

create table if not exists public.payments (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users (id) on delete cascade,
  plan_code    text not null references public.plans (code),
  amount       numeric(12, 2) not null check (amount >= 0),
  currency     public.currency_code not null,
  method       text not null check (method in ('BANK_TRANSFER', 'KHQR', 'CASH', 'OTHER')),
  reference    text check (reference is null or char_length(reference) <= 120),
  status       text not null default 'PENDING' check (status in ('PENDING', 'PAID', 'REJECTED', 'EXPIRED')),
  note         text check (note is null or char_length(note) <= 500),
  bakong_md5   text,
  bakong_hash  text,
  created_at   timestamptz not null default now(),
  reviewed_at  timestamptz,
  reviewed_by  uuid references auth.users (id) on delete set null
);
create index if not exists payments_user_idx on public.payments (user_id, created_at desc);
create index if not exists payments_status_idx on public.payments (status, created_at desc);
alter table public.payments enable row level security;
drop policy if exists payments_select_own on public.payments;
create policy payments_select_own on public.payments
  for select to authenticated using (user_id = (select auth.uid()));

create table if not exists public.subscription_events (
  id         bigint generated always as identity primary key,
  user_id    uuid not null references auth.users (id) on delete cascade,
  kind       text not null,
  plan_code  text,
  period_end timestamptz,
  payment_id uuid references public.payments (id) on delete set null,
  actor      uuid references auth.users (id) on delete set null,
  note       text,
  created_at timestamptz not null default now()
);
create index if not exists subscription_events_user_idx on public.subscription_events (user_id, created_at desc);
alter table public.subscription_events enable row level security;
drop policy if exists subscription_events_select_own on public.subscription_events;
create policy subscription_events_select_own on public.subscription_events
  for select to authenticated using (user_id = (select auth.uid()));

create table if not exists public.usage_counters (
  user_id     uuid not null references auth.users (id) on delete cascade,
  month       date not null,
  ai_queries  integer not null default 0,
  primary key (user_id, month)
);
alter table public.usage_counters enable row level security;
drop policy if exists usage_counters_select_own on public.usage_counters;
create policy usage_counters_select_own on public.usage_counters
  for select to authenticated using (user_id = (select auth.uid()));

-- Admins are added by hand in the SQL editor (see docs/subscriptions.md).
create table if not exists public.app_admins (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.app_admins enable row level security;

-- App-wide settings readable by signed-in users (e.g. how to pay), written by admins.
create table if not exists public.app_settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.app_settings enable row level security;
drop policy if exists app_settings_select on public.app_settings;
create policy app_settings_select on public.app_settings for select to authenticated using (true);

-- ---------------------------------------------------------------------------
-- Activity (admin analytics): auth.users.last_sign_in_at only moves on a new
-- sign-in, so the app also stamps profiles.last_seen_at when it opens.
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists last_seen_at timestamptz;
create index if not exists transactions_created_by_idx on public.transactions (created_by, created_at desc);

create or replace function public.touch_last_seen()
returns void
language sql
security definer
set search_path = ''
as $$
  update public.profiles set last_seen_at = now()
  where id = (select auth.uid()) and (last_seen_at is null or last_seen_at < now() - interval '15 minutes');
$$;

-- Latest sign of life: sign-in, app open, or a recorded transaction.
create or replace function public.last_active_at(p_user_id uuid)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(
    (select u.last_sign_in_at from auth.users u where u.id = p_user_id),
    (select p.last_seen_at from public.profiles p where p.id = p_user_id),
    (select max(t.created_at) from public.transactions t where t.created_by = p_user_id)
  );
$$;

-- ---------------------------------------------------------------------------
-- Plan helpers
-- ---------------------------------------------------------------------------
create or replace function public.plan_code_of(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select s.plan_code from public.subscriptions s
     where s.user_id = p_user_id and s.status = 'ACTIVE' and s.current_period_end > now()),
    'FREE'
  );
$$;

create or replace function public.plan_of(p_user_id uuid)
returns public.plans
language sql
stable
security definer
set search_path = ''
as $$
  select p.* from public.plans p where p.code = public.plan_code_of(p_user_id);
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.app_admins a where a.user_id = (select auth.uid()));
$$;

create or replace function public.current_ai_month()
returns date
language sql
stable
set search_path = ''
as $$
  select date_trunc('month', now() at time zone 'Asia/Phnom_Penh')::date;
$$;

-- Everything the app needs to know about the caller's plan in one call.
create or replace function public.my_plan()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  s public.subscriptions;
  used integer;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select * into s from public.subscriptions where user_id = uid;
  select coalesce((select ai_queries from public.usage_counters where user_id = uid and month = public.current_ai_month()), 0) into used;
  return jsonb_build_object(
    'tier', p.tier,
    'plan_code', p.code,
    'period_end', case when p.tier = 'PRO' then s.current_period_end end,
    'last_plan_code', s.plan_code,
    'last_period_end', s.current_period_end,
    'max_wallets', p.max_wallets,
    'max_family_members', p.max_family_members,
    'ai_queries_per_month', p.ai_queries_per_month,
    'ai_queries_used', used,
    'can_export', p.can_export,
    'can_credit_score', p.can_credit_score,
    'is_admin', public.is_admin()
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- Limit: wallets (counted per workspace owner; a Pro owner's family gets Pro)
-- ---------------------------------------------------------------------------
create or replace function public.guard_wallet_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  owner uuid;
  max_wallets integer;
  used integer;
begin
  if (select auth.uid()) is null or coalesce(current_setting('luysmart.import', true), '') = 'on' then
    return new;
  end if;
  -- Only creating a wallet or bringing one back from the archive counts.
  if tg_op = 'UPDATE' and not (old.archived_at is not null and new.archived_at is null) then
    return new;
  end if;
  if new.archived_at is not null then
    return new;
  end if;
  select user_id into owner from public.workspaces where id = new.workspace_id;
  max_wallets := (public.plan_of(owner)).max_wallets;
  if max_wallets is null then
    return new;
  end if;
  select count(*) into used
  from public.wallets_accounts w join public.workspaces ws on ws.id = w.workspace_id
  where ws.user_id = owner and w.archived_at is null and w.id <> new.id;
  if used >= max_wallets then
    raise exception 'plan_limit:wallets' using errcode = 'P0001', hint = max_wallets::text;
  end if;
  return new;
end;
$$;

create or replace trigger wallets_accounts_plan_limit
  before insert or update of archived_at on public.wallets_accounts
  for each row execute function public.guard_wallet_limit();

-- ---------------------------------------------------------------------------
-- Limit: family members (owner's plan). Re-declares the two invite functions
-- from 20261001070100 with the limit check added.
-- ---------------------------------------------------------------------------
create or replace function public.family_member_limit_reached(p_workspace_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select count(*) >= (public.plan_of(ws.user_id)).max_family_members
    from public.workspace_members m join public.workspaces ws on ws.id = m.workspace_id
    where m.workspace_id = p_workspace_id and m.role <> 'OWNER'
    group by ws.user_id
  ), false);
$$;

create or replace function public.create_workspace_invite(p_workspace_id uuid, p_role public.workspace_role default 'MEMBER')
returns public.workspace_invites
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  bytes bytea;
  new_code text;
  result public.workspace_invites;
begin
  if not public.owns_workspace(p_workspace_id) then
    raise exception 'only the owner can invite' using errcode = '42501';
  end if;
  if not exists (select 1 from public.workspaces where id = p_workspace_id and type = 'FAMILY') then
    raise exception 'only a family workspace can be shared' using errcode = '22023';
  end if;
  if public.family_member_limit_reached(p_workspace_id) then
    raise exception 'plan_limit:family' using errcode = 'P0001';
  end if;
  if p_role not in ('MEMBER', 'VIEWER') then
    raise exception 'invalid role' using errcode = '22023';
  end if;
  if (select count(*) from public.workspace_invites
      where workspace_id = p_workspace_id and used_at is null and expires_at > now()) >= 10 then
    raise exception 'too_many_invites' using errcode = '22023';
  end if;

  for attempt in 1..10 loop
    -- The first 6 bytes of a v4 UUID are random; 256 is a multiple of 32, so no bias.
    bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    new_code := '';
    for i in 0..5 loop
      new_code := new_code || substr(alphabet, get_byte(bytes, i) % 32 + 1, 1);
    end loop;
    begin
      insert into public.workspace_invites (workspace_id, code, role, created_by)
      values (p_workspace_id, new_code, p_role, uid)
      returning * into result;
      return result;
    exception when unique_violation then
      -- try another code
    end;
  end loop;
  raise exception 'could not generate a code' using errcode = 'P0001';
end;
$$;

create or replace function public.lookup_workspace_invite(p_code text, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  normalized text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  inv public.workspace_invites;
  ws public.workspaces;
  inviter text;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if (select count(*) from public.invite_failures
      where user_id = uid and attempted_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('status', 'rate_limited');
  end if;

  select * into inv from public.workspace_invites where code = normalized for update;
  if not found then
    insert into public.invite_failures (user_id) values (uid);
    return jsonb_build_object('status', 'invalid');
  end if;
  select * into ws from public.workspaces where id = inv.workspace_id;

  if exists (select 1 from public.workspace_members where workspace_id = inv.workspace_id and user_id = uid) then
    return jsonb_build_object('status', 'already_member', 'workspace_id', ws.id, 'workspace_name', ws.name);
  end if;
  if inv.used_at is not null then
    return jsonb_build_object('status', 'used');
  end if;
  if inv.expires_at <= now() then
    return jsonb_build_object('status', 'expired');
  end if;

  -- The owner's plan caps how many people can join.
  if public.family_member_limit_reached(inv.workspace_id) then
    return jsonb_build_object('status', 'member_limit');
  end if;

  select display_name into inviter from public.profiles where id = inv.created_by;
  if not p_accept then
    return jsonb_build_object(
      'status', 'ok', 'workspace_id', ws.id, 'workspace_name', ws.name,
      'inviter_name', coalesce(inviter, ''), 'role', inv.role
    );
  end if;

  insert into public.profiles (id, display_name)
  values (uid, coalesce(public.default_display_name(uid), 'Member'))
  on conflict (id) do nothing;
  insert into public.workspace_members (workspace_id, user_id, role) values (inv.workspace_id, uid, inv.role);
  update public.workspace_invites set used_by = uid, used_at = now() where id = inv.id;
  return jsonb_build_object('status', 'ok', 'workspace_id', ws.id, 'workspace_name', ws.name, 'role', inv.role);
end;
$$;

-- ---------------------------------------------------------------------------
-- AI quota (Pro: server-provided AI). p_commit = false only checks.
-- ---------------------------------------------------------------------------
create or replace function public.use_ai_query(p_commit boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  lim integer;
  used integer;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  lim := (public.plan_of(uid)).ai_queries_per_month;
  select coalesce((select ai_queries from public.usage_counters where user_id = uid and month = public.current_ai_month()), 0)
    into used;
  if lim <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'plan_required', 'limit', 0, 'used', used);
  end if;
  if used >= lim then
    return jsonb_build_object('ok', false, 'reason', 'quota_exceeded', 'limit', lim, 'used', used);
  end if;
  if p_commit then
    insert into public.usage_counters (user_id, month, ai_queries) values (uid, public.current_ai_month(), 1)
    on conflict (user_id, month) do update set ai_queries = public.usage_counters.ai_queries + 1
    returning ai_queries into used;
  end if;
  return jsonb_build_object('ok', true, 'limit', lim, 'used', used);
end;
$$;

-- ---------------------------------------------------------------------------
-- Upgrade requests (manual payment, approved by an admin)
-- ---------------------------------------------------------------------------
create or replace function public.request_upgrade(p_plan_code text, p_method text, p_reference text, p_currency public.currency_code)
returns public.payments
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  result public.payments;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select * into p from public.plans where code = p_plan_code and tier = 'PRO' and active;
  if not found then
    raise exception 'unknown plan' using errcode = '22023';
  end if;
  if p_method not in ('BANK_TRANSFER', 'KHQR', 'CASH', 'OTHER') then
    raise exception 'unknown payment method' using errcode = '22023';
  end if;
  if (select count(*) from public.payments where user_id = uid and status = 'PENDING') >= 3 then
    raise exception 'too_many_pending' using errcode = 'P0001';
  end if;
  insert into public.payments (user_id, plan_code, amount, currency, method, reference)
  values (
    uid, p.code, case when p_currency = 'USD' then p.price_usd else p.price_khr end, p_currency, p_method,
    nullif(left(trim(coalesce(p_reference, '')), 120), '')
  )
  returning * into result;
  insert into public.subscription_events (user_id, kind, plan_code, payment_id, actor)
  values (uid, 'REQUESTED', p.code, result.id, uid);
  return result;
end;
$$;

create or replace function public.cancel_upgrade_request(p_payment_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.payments set status = 'EXPIRED', note = 'Cancelled by the user', reviewed_at = now()
  where id = p_payment_id and user_id = (select auth.uid()) and status = 'PENDING';
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin tools (every function checks is_admin())
-- ---------------------------------------------------------------------------
create or replace function public.require_admin()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
end;
$$;

-- Internal: extend from the later of now and the current end, record the event.
create or replace function public.extend_subscription(
  p_user_id uuid, p_plan_code text, p_days integer, p_source text, p_actor uuid, p_note text, p_payment_id uuid
)
returns public.subscriptions
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_end timestamptz;
  result public.subscriptions;
begin
  if p_days is null or p_days <= 0 or p_days > 3660 then
    raise exception 'invalid number of days' using errcode = '22023';
  end if;
  if not exists (select 1 from public.plans where code = p_plan_code and tier = 'PRO') then
    raise exception 'unknown plan' using errcode = '22023';
  end if;
  select current_period_end into current_end from public.subscriptions
  where user_id = p_user_id and status = 'ACTIVE' and current_period_end > now();
  -- A free reward on top of a paid plan keeps that plan.
  if p_source = 'REFERRAL' and current_end is not null then
    select plan_code into p_plan_code from public.subscriptions where user_id = p_user_id;
  end if;
  insert into public.subscriptions (user_id, plan_code, status, current_period_start, current_period_end, source, note, updated_at, updated_by)
  values (p_user_id, p_plan_code, 'ACTIVE', now(), greatest(now(), coalesce(current_end, now())) + make_interval(days => p_days), p_source, p_note, now(), p_actor)
  on conflict (user_id) do update set
    plan_code = excluded.plan_code,
    status = 'ACTIVE',
    current_period_start = case when current_end is null then now() else public.subscriptions.current_period_start end,
    current_period_end = excluded.current_period_end,
    source = excluded.source,
    note = excluded.note,
    updated_at = now(),
    updated_by = excluded.updated_by
  returning * into result;
  insert into public.subscription_events (user_id, kind, plan_code, period_end, payment_id, actor, note)
  values (p_user_id, 'EXTENDED', p_plan_code, result.current_period_end, p_payment_id, p_actor, p_note);
  return result;
end;
$$;

create or replace function public.admin_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  result jsonb;
begin
  perform public.require_admin();
  with activity as (
    select u.id, public.last_active_at(u.id) as last_active,
      exists (select 1 from public.subscriptions s where s.user_id = u.id and s.status = 'ACTIVE' and s.current_period_end > now()) as pro
    from auth.users u
  )
  select jsonb_build_object(
    'users', count(*),
    'dau', count(*) filter (where last_active > now() - interval '24 hours'),
    'mau', count(*) filter (where last_active > now() - interval '30 days'),
    'new_7d', (select count(*) from auth.users where created_at > now() - interval '7 days'),
    'pro_active', count(*) filter (where pro),
    'free_users', count(*) filter (where not pro),
    'expiring_7d', (select count(*) from public.subscriptions where status = 'ACTIVE' and current_period_end > now() and current_period_end <= now() + interval '7 days'),
    'pending_payments', (select count(*) from public.payments where status = 'PENDING'),
    'paid_30d_usd', (select coalesce(sum(amount), 0) from public.payments where status = 'PAID' and currency = 'USD' and reviewed_at > now() - interval '30 days'),
    'paid_30d_khr', (select coalesce(sum(amount), 0) from public.payments where status = 'PAID' and currency = 'KHR' and reviewed_at > now() - interval '30 days')
  )
  into result
  from activity;
  return result;
end;
$$;

create or replace function public.admin_list_subscribers(p_search text, p_filter text, p_limit integer, p_offset integer)
returns table (
  user_id uuid, email text, display_name text, joined_at timestamptz, plan_code text, tier text, status text,
  period_end timestamptz, pending_payments integer, last_paid_at timestamptz, last_active_at timestamptz, total bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return query
  with rows as (
    select
      u.id as user_id, u.email::text as email, pr.display_name, u.created_at as joined_at,
      s.plan_code, case when s.status = 'ACTIVE' and s.current_period_end > now() then 'PRO' else 'FREE' end as tier,
      s.status, s.current_period_end as period_end,
      (select count(*)::integer from public.payments p where p.user_id = u.id and p.status = 'PENDING') as pending_payments,
      (select max(p.reviewed_at) from public.payments p where p.user_id = u.id and p.status = 'PAID') as last_paid_at,
      public.last_active_at(u.id) as last_active_at
    from auth.users u
    left join public.subscriptions s on s.user_id = u.id
    left join public.profiles pr on pr.id = u.id
    where coalesce(p_search, '') = ''
      or u.email ilike '%' || p_search || '%'
      or pr.display_name ilike '%' || p_search || '%'
      or u.id::text = p_search
  ), filtered as (
    select * from rows r
    where case coalesce(p_filter, 'all')
      when 'pro' then r.tier = 'PRO'
      when 'free' then r.tier = 'FREE'
      when 'expiring' then r.tier = 'PRO' and r.period_end <= now() + interval '7 days'
      when 'expired' then r.tier = 'FREE' and r.period_end is not null
      when 'pending' then r.pending_payments > 0
      else true
    end
  )
  select f.*, count(*) over () as total from filtered f
  order by f.pending_payments desc, f.period_end asc nulls last, f.joined_at desc
  limit least(coalesce(p_limit, 50), 200) offset greatest(coalesce(p_offset, 0), 0);
end;
$$;

create or replace function public.admin_extend_subscription(p_user_id uuid, p_plan_code text, p_days integer, p_note text)
returns public.subscriptions
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return public.extend_subscription(p_user_id, p_plan_code, p_days, 'ADMIN', (select auth.uid()), nullif(left(p_note, 500), ''), null);
end;
$$;

-- Set an exact end date (e.g. correct a mistake); a past date ends Pro now.
create or replace function public.admin_set_subscription_end(p_user_id uuid, p_plan_code text, p_period_end timestamptz, p_note text)
returns public.subscriptions
language plpgsql
security definer
set search_path = ''
as $$
declare
  result public.subscriptions;
begin
  perform public.require_admin();
  if not exists (select 1 from public.plans where code = p_plan_code and tier = 'PRO') then
    raise exception 'unknown plan' using errcode = '22023';
  end if;
  insert into public.subscriptions (user_id, plan_code, status, current_period_end, source, note, updated_at, updated_by)
  values (p_user_id, p_plan_code, 'ACTIVE', p_period_end, 'ADMIN', nullif(left(p_note, 500), ''), now(), (select auth.uid()))
  on conflict (user_id) do update set
    plan_code = excluded.plan_code, status = 'ACTIVE', current_period_end = excluded.current_period_end,
    source = 'ADMIN', note = excluded.note, updated_at = now(), updated_by = excluded.updated_by
  returning * into result;
  insert into public.subscription_events (user_id, kind, plan_code, period_end, actor, note)
  values (p_user_id, 'SET_END', p_plan_code, p_period_end, (select auth.uid()), nullif(left(p_note, 500), ''));
  return result;
end;
$$;

create or replace function public.admin_cancel_subscription(p_user_id uuid, p_note text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  update public.subscriptions set status = 'CANCELLED', current_period_end = least(current_period_end, now()),
    note = nullif(left(p_note, 500), ''), updated_at = now(), updated_by = (select auth.uid())
  where user_id = p_user_id;
  insert into public.subscription_events (user_id, kind, actor, note)
  values (p_user_id, 'CANCELLED', (select auth.uid()), nullif(left(p_note, 500), ''));
end;
$$;

create or replace function public.admin_list_payments(p_status text, p_limit integer)
returns table (
  id uuid, user_id uuid, email text, display_name text, plan_code text, amount numeric, currency public.currency_code,
  method text, reference text, status text, note text, created_at timestamptz, reviewed_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return query
  select p.id, p.user_id, u.email::text, pr.display_name, p.plan_code, p.amount, p.currency, p.method, p.reference,
         p.status, p.note, p.created_at, p.reviewed_at
  from public.payments p
  join auth.users u on u.id = p.user_id
  left join public.profiles pr on pr.id = p.user_id
  where coalesce(p_status, 'ALL') = 'ALL' or p.status = p_status
  order by (p.status = 'PENDING') desc, p.created_at desc
  limit least(coalesce(p_limit, 100), 500);
end;
$$;

-- Approving marks the payment PAID and extends Pro by the plan's period.
create or replace function public.admin_review_payment(p_payment_id uuid, p_approve boolean, p_note text)
returns public.payments
language plpgsql
security definer
set search_path = ''
as $$
declare
  pay public.payments;
  days integer;
begin
  perform public.require_admin();
  select * into pay from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment not found' using errcode = 'P0002';
  end if;
  if pay.status <> 'PENDING' then
    raise exception 'payment already reviewed' using errcode = '22023';
  end if;
  update public.payments set
    status = case when p_approve then 'PAID' else 'REJECTED' end,
    note = nullif(left(p_note, 500), ''), reviewed_at = now(), reviewed_by = (select auth.uid())
  where id = pay.id
  returning * into pay;
  if p_approve then
    select period_days into days from public.plans where code = pay.plan_code;
    perform public.extend_subscription(pay.user_id, pay.plan_code, days, 'ADMIN', (select auth.uid()), pay.note, pay.id);
  else
    insert into public.subscription_events (user_id, kind, plan_code, payment_id, actor, note)
    values (pay.user_id, 'REJECTED', pay.plan_code, pay.id, (select auth.uid()), pay.note);
  end if;
  return pay;
end;
$$;

create or replace function public.admin_user_events(p_user_id uuid)
returns setof public.subscription_events
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return query select * from public.subscription_events where user_id = p_user_id order by created_at desc limit 50;
end;
$$;

-- How to pay (shown in the upgrade screen); admins edit it in /admin.
create or replace function public.admin_set_payment_instructions(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  if jsonb_typeof(p_value) <> 'object' or length(p_value::text) > 4000 then
    raise exception 'invalid settings' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at) values ('payment_instructions', p_value, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;

insert into public.app_settings (key, value)
values ('payment_instructions', '{"bank": "", "account_name": "", "account_number": "", "note_km": "", "note_en": ""}'::jsonb)
on conflict (key) do nothing;


-- ---------------------------------------------------------------------------
-- Referrals: both people get 7 days of Pro when a new account uses a code.
-- Only accounts younger than 7 days can redeem, once, never their own code;
-- a referrer earns at most 20 rewards per calendar month (the friend still
-- gets theirs).
-- ---------------------------------------------------------------------------
create table if not exists public.referral_codes (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  code       text not null unique check (code ~ '^[A-HJ-NP-Z2-9]{8}$'),
  created_at timestamptz not null default now()
);
alter table public.referral_codes enable row level security;
drop policy if exists referral_codes_select_own on public.referral_codes;
create policy referral_codes_select_own on public.referral_codes
  for select to authenticated using (user_id = (select auth.uid()));

create table if not exists public.referrals (
  id               uuid primary key default gen_random_uuid(),
  referrer_id      uuid not null references auth.users (id) on delete cascade,
  referred_id      uuid not null unique references auth.users (id) on delete cascade,
  code             text not null,
  referrer_rewarded boolean not null default false,
  referred_rewarded boolean not null default false,
  reward_days      integer not null default 7,
  created_at       timestamptz not null default now()
);
create index if not exists referrals_referrer_idx on public.referrals (referrer_id, created_at desc);
alter table public.referrals enable row level security;
drop policy if exists referrals_select_own on public.referrals;
create policy referrals_select_own on public.referrals
  for select to authenticated using (referrer_id = (select auth.uid()) or referred_id = (select auth.uid()));

-- The caller's code (created on first use) and their referral numbers.
create or replace function public.my_referral()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  bytes bytea;
  new_code text;
  my_code text;
  account_age interval;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select code into my_code from public.referral_codes where user_id = uid;
  while my_code is null loop
    bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    new_code := '';
    for i in 0..7 loop
      new_code := new_code || substr(alphabet, get_byte(bytes, i) % 32 + 1, 1);
    end loop;
    insert into public.referral_codes (user_id, code) values (uid, new_code)
    on conflict do nothing
    returning code into my_code;
    if my_code is null then
      select code into my_code from public.referral_codes where user_id = uid;
    end if;
  end loop;
  select now() - created_at into account_age from auth.users where id = uid;
  return jsonb_build_object(
    'code', my_code,
    'invited', (select count(*) from public.referrals where referrer_id = uid),
    'days_earned', (select coalesce(sum(reward_days), 0) from public.referrals where referrer_id = uid and referrer_rewarded),
    'referred_by', (select r.code from public.referrals r where r.referred_id = uid),
    'can_redeem', account_age < interval '7 days' and not exists (select 1 from public.referrals where referred_id = uid)
  );
end;
$$;

-- Called by the new user (from the link, or by typing the code).
create or replace function public.redeem_referral(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  normalized text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  referrer uuid;
  this_month integer;
  ref public.referrals;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Shares the invite-code guessing limit.
  if (select count(*) from public.invite_failures where user_id = uid and attempted_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('status', 'rate_limited');
  end if;
  select user_id into referrer from public.referral_codes where code = normalized;
  if referrer is null then
    insert into public.invite_failures (user_id) values (uid);
    return jsonb_build_object('status', 'invalid');
  end if;
  if referrer = uid then
    return jsonb_build_object('status', 'own_code');
  end if;
  if exists (select 1 from public.referrals where referred_id = uid) then
    return jsonb_build_object('status', 'already_redeemed');
  end if;
  if (select now() - created_at from auth.users where id = uid) >= interval '7 days' then
    return jsonb_build_object('status', 'too_late');
  end if;

  select count(*) into this_month from public.referrals
  where referrer_id = referrer and referrer_rewarded
    and created_at >= date_trunc('month', now() at time zone 'Asia/Phnom_Penh') at time zone 'Asia/Phnom_Penh';

  insert into public.referrals (referrer_id, referred_id, code, referrer_rewarded, referred_rewarded)
  values (referrer, uid, normalized, this_month < 20, true)
  returning * into ref;

  perform public.extend_subscription(uid, 'PRO_MONTHLY', ref.reward_days, 'REFERRAL', uid, 'Referral welcome bonus', null);
  if ref.referrer_rewarded then
    perform public.extend_subscription(referrer, 'PRO_MONTHLY', ref.reward_days, 'REFERRAL', uid, 'Referral reward', null);
  end if;
  return jsonb_build_object('status', 'ok', 'days', ref.reward_days);
end;
$$;

create or replace function public.admin_referral_stats()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return jsonb_build_object(
    'total', (select count(*) from public.referrals),
    'last_30d', (select count(*) from public.referrals where created_at > now() - interval '30 days'),
    'days_granted', (select coalesce(sum(reward_days * ((referrer_rewarded)::int + (referred_rewarded)::int)), 0) from public.referrals),
    'top', coalesce((
      select jsonb_agg(t order by t.invited desc)
      from (
        select r.referrer_id as user_id, u.email::text as email, pr.display_name, count(*) as invited,
               count(*) filter (where r.referrer_rewarded) * 7 as days_earned
        from public.referrals r
        join auth.users u on u.id = r.referrer_id
        left join public.profiles pr on pr.id = r.referrer_id
        group by r.referrer_id, u.email, pr.display_name
        order by count(*) desc
        limit 10
      ) t
    ), '[]'::jsonb)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- Access: clients call only these functions; everything else is internal.
-- ---------------------------------------------------------------------------
revoke all on function public.plan_code_of(uuid) from public, anon, authenticated;
revoke all on function public.plan_of(uuid) from public, anon, authenticated;
revoke all on function public.extend_subscription(uuid, text, integer, text, uuid, text, uuid) from public, anon, authenticated;
revoke all on function public.require_admin() from public, anon, authenticated;
revoke all on function public.guard_wallet_limit() from public, anon, authenticated;
revoke all on function public.family_member_limit_reached(uuid) from public, anon, authenticated;
revoke all on function public.last_active_at(uuid) from public, anon, authenticated;
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.my_plan()', 'public.is_admin()', 'public.touch_last_seen()', 'public.current_ai_month()', 'public.use_ai_query(boolean)',
    'public.request_upgrade(text, text, text, public.currency_code)', 'public.cancel_upgrade_request(uuid)',
    'public.admin_overview()', 'public.admin_list_subscribers(text, text, integer, integer)',
    'public.admin_extend_subscription(uuid, text, integer, text)', 'public.admin_set_subscription_end(uuid, text, timestamptz, text)',
    'public.admin_cancel_subscription(uuid, text)', 'public.admin_list_payments(text, integer)',
    'public.admin_review_payment(uuid, boolean, text)', 'public.admin_user_events(uuid)',
    'public.admin_set_payment_instructions(jsonb)',
    'public.my_referral()', 'public.redeem_referral(text)', 'public.admin_referral_stats()',
    'public.create_workspace_invite(uuid, public.workspace_role)', 'public.lookup_workspace_invite(text, boolean)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end
$$;

-- Live plan updates on the user's devices after an admin approves.
do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    return;
  end if;
  foreach t in array array['subscriptions', 'payments'] loop
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end
$$;


-- ===========================================================================
-- 20261002000000_bank_reconciliation.sql
-- ===========================================================================

-- ===========================================================================
-- Bank reconciliation (PRO): import a bank statement into a wallet, match its
-- lines to the ledger, add what's missing and align the balance.
--
-- The statement file never reaches the server: the app parses it on the
-- device and sends only normalized lines (date, signed amount, description,
-- bank reference, running balance) plus a SHA-256 of the file.
-- import_statement() validates every decision and applies them atomically.
-- Idempotent: safe to re-run.
-- ===========================================================================

alter table public.transactions
  add column if not exists reconciled_at timestamptz,
  add column if not exists bank_ref text;
alter table public.transactions
  drop constraint if exists transactions_bank_ref_length,
  add constraint transactions_bank_ref_length check (bank_ref is null or char_length(bank_ref) <= 80);

alter table public.wallets_accounts
  add column if not exists last_reconciled_on date,
  add column if not exists last_reconciled_balance numeric(18, 2);

create table if not exists public.statement_imports (
  id              uuid primary key default gen_random_uuid(),
  workspace_id    uuid not null references public.workspaces (id) on delete cascade,
  wallet_id       uuid not null,
  created_by      uuid references auth.users (id) on delete set null,
  bank            text not null check (bank ~ '^[A-Z_]{2,20}$'),
  source_format   text not null check (source_format in ('CSV', 'XLSX', 'PDF')),
  file_sha256     text not null check (file_sha256 ~ '^[0-9a-f]{64}$'),
  currency        public.currency_code not null,
  period_start    date not null,
  period_end      date not null,
  opening_balance numeric(18, 2),
  closing_balance numeric(18, 2),
  line_count      integer not null default 0,
  created_at      timestamptz not null default now(),
  check (period_end >= period_start),
  foreign key (wallet_id, workspace_id) references public.wallets_accounts (id, workspace_id) on delete cascade,
  unique (wallet_id, file_sha256)
);
create index if not exists statement_imports_wallet_idx on public.statement_imports (wallet_id, created_at desc);

create table if not exists public.statement_lines (
  id              uuid primary key default gen_random_uuid(),
  import_id       uuid not null references public.statement_imports (id) on delete cascade,
  workspace_id    uuid not null references public.workspaces (id) on delete cascade,
  wallet_id       uuid not null,
  line_no         integer not null check (line_no > 0),
  posted_on       date not null,
  amount          numeric(18, 2) not null check (amount <> 0),
  description     text check (description is null or char_length(description) <= 300),
  bank_ref        text check (bank_ref is null or char_length(bank_ref) <= 80),
  running_balance numeric(18, 2),
  fingerprint     text not null check (fingerprint ~ '^[0-9a-f]{64}$'),
  status          text not null default 'UNMATCHED' check (status in ('UNMATCHED', 'MATCHED', 'CREATED', 'IGNORED')),
  transaction_id  uuid unique references public.transactions (id) on delete set null,
  match_score     smallint check (match_score is null or match_score between 0 and 100),
  foreign key (wallet_id, workspace_id) references public.wallets_accounts (id, workspace_id) on delete cascade,
  -- A line already imported from an overlapping statement is skipped.
  unique (wallet_id, fingerprint)
);
create index if not exists statement_lines_import_idx on public.statement_lines (import_id, line_no);

-- Read-only for members; every write goes through the functions below.
alter table public.statement_imports enable row level security;
alter table public.statement_lines enable row level security;
drop policy if exists statement_imports_select on public.statement_imports;
create policy statement_imports_select on public.statement_imports
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists statement_lines_select on public.statement_lines;
create policy statement_lines_select on public.statement_lines
  for select to authenticated using (public.is_workspace_member(workspace_id));

-- ---------------------------------------------------------------------------
-- How much a ledger row moves one wallet, in that wallet's currency
-- (the same arithmetic as adjust_wallet_balances).
-- ---------------------------------------------------------------------------
create or replace function public.wallet_effect(t public.transactions, p_wallet_id uuid, p_wallet_currency public.currency_code)
returns numeric
language sql
immutable
set search_path = ''
as $$
  select case
    when t.type = 'TRANSFER' and t.wallet_id = p_wallet_id then -t.amount
    when t.type = 'TRANSFER' and t.to_wallet_id = p_wallet_id then t.to_amount
    when t.wallet_id <> p_wallet_id then 0
    when t.type = 'INCOME' then public.amount_in_wallet_currency(t.amount, t.currency, t.exchange_rate, p_wallet_currency)
    else -public.amount_in_wallet_currency(t.amount, t.currency, t.exchange_rate, p_wallet_currency)
  end;
$$;

-- ---------------------------------------------------------------------------
-- A ✓ never goes stale: changing the money of a reconciled row (or deleting
-- it) puts its statement line back to "unmatched".
-- ---------------------------------------------------------------------------
create or replace function public.unreconcile_changed_transaction()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    update public.statement_lines set status = 'UNMATCHED', transaction_id = null, match_score = null
    where transaction_id = old.id;
    return old;
  end if;
  if old.reconciled_at is not null and (
    new.amount is distinct from old.amount or new.currency is distinct from old.currency
    or new.exchange_rate is distinct from old.exchange_rate or new.type is distinct from old.type
    or new.wallet_id is distinct from old.wallet_id or new.to_wallet_id is distinct from old.to_wallet_id
    or new.to_amount is distinct from old.to_amount
  ) then
    new.reconciled_at := null;
    update public.statement_lines set status = 'UNMATCHED', transaction_id = null, match_score = null
    where transaction_id = old.id;
  end if;
  return new;
end;
$$;
create or replace trigger transactions_unreconcile_on_change
  before update on public.transactions
  for each row execute function public.unreconcile_changed_transaction();
create or replace trigger transactions_unreconcile_on_delete
  before delete on public.transactions
  for each row execute function public.unreconcile_changed_transaction();

-- Caller may write to the wallet (member/owner; personal wallets: owner only).
create or replace function public.require_wallet_writer(p_wallet_id uuid)
returns public.wallets_accounts
language plpgsql
security definer
set search_path = ''
as $$
declare
  w public.wallets_accounts;
begin
  select * into w from public.wallets_accounts where id = p_wallet_id;
  if not found or not public.can_write_workspace(w.workspace_id)
     or (w.visibility = 'PERSONAL' and w.owner_id is distinct from (select auth.uid())) then
    raise exception 'wallet not found' using errcode = '42501';
  end if;
  return w;
end;
$$;

-- Lines of these fingerprints that this wallet already has (preview only).
create or replace function public.statement_known_fingerprints(p_wallet_id uuid, p_fingerprints text[])
returns text[]
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_wallet_writer(p_wallet_id);
  if coalesce(array_length(p_fingerprints, 1), 0) > 5000 then
    raise exception 'too many lines' using errcode = '22023';
  end if;
  return coalesce((
    select array_agg(l.fingerprint) from public.statement_lines l
    where l.wallet_id = p_wallet_id and l.fingerprint = any (p_fingerprints)
  ), '{}');
end;
$$;

-- ---------------------------------------------------------------------------
-- import_statement(wallet, meta, lines, align)
--   meta:  {bank, source_format, file_sha256, period_start, period_end,
--           opening_balance?, closing_balance?}
--   lines: [{line_no, posted_on, amount (signed), description?, bank_ref?,
--            running_balance?, fingerprint, action, transaction_id?,
--            category_id?, note?, fee?, score?}]
--   action: match (link transaction_id) | create (add to the ledger) |
--           ignore | none (leave for later)
--   align: add one adjustment so the wallet equals closing_balance as of
--          period_end (Phnom Penh time).
-- ---------------------------------------------------------------------------
create or replace function public.import_statement(p_wallet_id uuid, p_meta jsonb, p_lines jsonb, p_align boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  w public.wallets_accounts;
  imp public.statement_imports;
  l jsonb;
  line_id uuid;
  t public.transactions;
  action text;
  amount numeric;
  category uuid;
  inserted integer := 0;
  skipped integer := 0;
  matched integer := 0;
  created integer := 0;
  as_of timestamptz;
  balance_as_of numeric;
  diff numeric := 0;
  adjusted numeric := 0;
  adj_category uuid;
  scale integer;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if public.plan_code_of(uid) = 'FREE' then
    raise exception 'plan_required' using errcode = 'P0001';
  end if;
  perform public.require_wallet_writer(p_wallet_id);
  select * into w from public.wallets_accounts where id = p_wallet_id for update;
  scale := case when w.currency = 'KHR' then 0 else 2 end;

  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 3000 then
    raise exception 'statement must have 1 to 3000 lines' using errcode = '22023';
  end if;

  begin
    insert into public.statement_imports (
      workspace_id, wallet_id, created_by, bank, source_format, file_sha256, currency,
      period_start, period_end, opening_balance, closing_balance
    ) values (
      w.workspace_id, w.id, uid, upper(p_meta ->> 'bank'), upper(p_meta ->> 'source_format'), lower(p_meta ->> 'file_sha256'),
      w.currency, (p_meta ->> 'period_start')::date, (p_meta ->> 'period_end')::date,
      round((p_meta ->> 'opening_balance')::numeric, scale), round((p_meta ->> 'closing_balance')::numeric, scale)
    ) returning * into imp;
  exception when unique_violation then
    raise exception 'already_imported' using errcode = 'P0001';
  end;

  for l in select value from jsonb_array_elements(p_lines) loop
    amount := round((l ->> 'amount')::numeric, scale);
    if (l ->> 'posted_on')::date not between imp.period_start and imp.period_end then
      raise exception 'line % is outside the statement period', l ->> 'line_no' using errcode = '22023';
    end if;

    insert into public.statement_lines (
      import_id, workspace_id, wallet_id, line_no, posted_on, amount, description, bank_ref, running_balance, fingerprint
    ) values (
      imp.id, w.workspace_id, w.id, (l ->> 'line_no')::integer, (l ->> 'posted_on')::date, amount,
      left(nullif(btrim(l ->> 'description'), ''), 300), left(nullif(btrim(l ->> 'bank_ref'), ''), 80),
      round((l ->> 'running_balance')::numeric, scale), lower(l ->> 'fingerprint')
    )
    on conflict (wallet_id, fingerprint) do nothing
    returning id into line_id;
    if line_id is null then
      skipped := skipped + 1;
      continue;
    end if;
    inserted := inserted + 1;
    action := coalesce(l ->> 'action', 'none');

    if action = 'match' then
      select * into t from public.transactions
      where id = (l ->> 'transaction_id')::uuid and workspace_id = w.workspace_id
        and (wallet_id = w.id or to_wallet_id = w.id)
      for update;
      if not found or t.reconciled_at is not null then
        raise exception 'match_invalid: line %', l ->> 'line_no' using errcode = 'P0001';
      end if;
      if public.wallet_effect(t, w.id, w.currency) <> amount then
        raise exception 'match_amount: line %', l ->> 'line_no' using errcode = 'P0001';
      end if;
      begin
        update public.statement_lines
        set status = 'MATCHED', transaction_id = t.id, match_score = least(greatest((l ->> 'score')::integer, 0), 100)
        where id = line_id;
      exception when unique_violation then
        raise exception 'match_invalid: line %', l ->> 'line_no' using errcode = 'P0001';
      end;
      update public.transactions
      set reconciled_at = now(), bank_ref = coalesce(bank_ref, left(nullif(btrim(l ->> 'bank_ref'), ''), 80))
      where id = t.id;
      matched := matched + 1;

    elsif action = 'create' then
      category := nullif(l ->> 'category_id', '')::uuid;
      if category is not null and not exists (
        select 1 from public.categories c
        where c.id = category and c.workspace_id = w.workspace_id
          and c.type = case when amount > 0 then 'INCOME'::public.category_type else 'EXPENSE'::public.category_type end
      ) then
        category := null;
      end if;
      if category is null and amount < 0 and coalesce((l ->> 'fee')::boolean, false) then
        category := public.ensure_preset_category(w.workspace_id, 'bank_fee', 'EXPENSE', 'landmark', '#64748b', 'កម្រៃធនាគារ');
      end if;
      insert into public.transactions (
        workspace_id, wallet_id, category_id, amount, currency, type, note, transaction_date, reconciled_at, bank_ref
      ) values (
        w.workspace_id, w.id, category, abs(amount), w.currency,
        case when amount > 0 then 'INCOME'::public.transaction_type else 'EXPENSE'::public.transaction_type end,
        left(coalesce(nullif(btrim(l ->> 'note'), ''), nullif(btrim(l ->> 'description'), '')), 500),
        ((l ->> 'posted_on')::date + time '12:00') at time zone 'Asia/Phnom_Penh',
        now(), left(nullif(btrim(l ->> 'bank_ref'), ''), 80)
      ) returning * into t;
      update public.statement_lines set status = 'CREATED', transaction_id = t.id where id = line_id;
      created := created + 1;

    elsif action = 'ignore' then
      update public.statement_lines set status = 'IGNORED' where id = line_id;
    elsif action <> 'none' then
      raise exception 'unknown action %', action using errcode = '22023';
    end if;
  end loop;

  update public.statement_imports set line_count = inserted where id = imp.id;

  -- Balance as of the end of the statement day = now minus everything after it.
  if imp.closing_balance is not null then
    as_of := ((imp.period_end + 1)::timestamp) at time zone 'Asia/Phnom_Penh';
    select w2.balance into balance_as_of from public.wallets_accounts w2 where w2.id = w.id;
    balance_as_of := balance_as_of - coalesce((
      select sum(public.wallet_effect(x, w.id, w.currency)) from public.transactions x
      where (x.wallet_id = w.id or x.to_wallet_id = w.id) and x.transaction_date >= as_of
    ), 0);
    diff := round(imp.closing_balance - balance_as_of, scale);

    if p_align and diff <> 0 then
      if diff > 0 then
        adj_category := public.ensure_preset_category(w.workspace_id, 'adjustment_in', 'INCOME', 'scale', '#64748b', 'កែតម្រូវសមតុល្យ (+)');
      else
        adj_category := public.ensure_preset_category(w.workspace_id, 'adjustment_out', 'EXPENSE', 'scale', '#64748b', 'កែតម្រូវសមតុល្យ (−)');
      end if;
      insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, note, transaction_date, reconciled_at)
      values (
        w.workspace_id, w.id, adj_category, abs(diff), w.currency,
        case when diff > 0 then 'INCOME'::public.transaction_type else 'EXPENSE'::public.transaction_type end,
        left(coalesce(nullif(btrim(p_meta ->> 'adjust_note'), ''), 'Bank statement ' || to_char(imp.period_end, 'DD/MM/YYYY')), 500),
        as_of - interval '1 second', now()
      );
      adjusted := diff;
      diff := 0;
    end if;

    if diff = 0 then
      update public.wallets_accounts
      set last_reconciled_on = greatest(coalesce(last_reconciled_on, imp.period_end), imp.period_end),
          last_reconciled_balance = case when last_reconciled_on > imp.period_end then last_reconciled_balance else imp.closing_balance end
      where id = w.id;
    end if;
  end if;

  return jsonb_build_object(
    'import_id', imp.id, 'inserted', inserted, 'skipped', skipped, 'matched', matched, 'created', created,
    'balance_as_of', balance_as_of, 'difference', diff, 'adjusted', adjusted, 'aligned', p_align and imp.closing_balance is not null
  );
end;
$$;

-- Undo an import: its lines go away and matched rows lose their ✓. Rows that
-- were added from it (and any adjustment) stay in the ledger as normal rows.
create or replace function public.delete_statement_import(p_import_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  imp public.statement_imports;
begin
  select * into imp from public.statement_imports where id = p_import_id;
  if not found then
    raise exception 'import not found' using errcode = 'P0002';
  end if;
  perform public.require_wallet_writer(imp.wallet_id);
  update public.transactions set reconciled_at = null
  where id in (select transaction_id from public.statement_lines where import_id = imp.id and transaction_id is not null);
  delete from public.statement_imports where id = imp.id;
end;
$$;

revoke all on function public.wallet_effect(public.transactions, uuid, public.currency_code) from public, anon, authenticated;
revoke all on function public.unreconcile_changed_transaction() from public, anon, authenticated;
revoke all on function public.require_wallet_writer(uuid) from public, anon, authenticated;
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.statement_known_fingerprints(uuid, text[])',
    'public.import_statement(uuid, jsonb, jsonb, boolean)',
    'public.delete_statement_import(uuid)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end
$$;


-- ===========================================================================
-- 20261002010000_support.sql
-- ===========================================================================

-- ===========================================================================
-- Help & Support: contact channels (set by the admin) and in-app tickets.
-- Users only create tickets through submit_support_ticket() (rate limited)
-- and read their own; admins read and answer them through admin_* functions.
-- New tickets are sent to admins' Telegram (their own Settings › Telegram
-- bot); a reply is sent to the user's Telegram the same way.
-- Idempotent: safe to re-run.
-- ===========================================================================

create table if not exists public.support_tickets (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  category    text not null check (category in ('PAYMENT', 'BUG', 'FEATURE', 'OTHER')),
  message     text not null check (char_length(btrim(message)) between 5 and 2000),
  contact     text check (contact is null or char_length(contact) <= 80),
  -- App screen, language, plan, app version: helps reproduce a problem.
  context     jsonb not null default '{}'::jsonb check (pg_column_size(context) <= 2000),
  status      text not null default 'OPEN' check (status in ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')),
  admin_reply text check (admin_reply is null or char_length(admin_reply) <= 2000),
  replied_at  timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists support_tickets_user_idx on public.support_tickets (user_id, created_at desc);
create index if not exists support_tickets_status_idx on public.support_tickets (status, created_at desc);

alter table public.support_tickets enable row level security;
drop policy if exists support_tickets_select_own on public.support_tickets;
create policy support_tickets_select_own on public.support_tickets
  for select to authenticated using (user_id = (select auth.uid()));

-- Contact channels; readable without signing in (Guest Mode needs help too).
create or replace function public.support_contacts()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select value from public.app_settings where key = 'support_contacts'), '{}'::jsonb);
$$;

create or replace function public.admin_set_support_contacts(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  telegram text := nullif(btrim(p_value ->> 'telegram_url'), '');
  community text := nullif(btrim(p_value ->> 'community_url'), '');
  phone text := nullif(btrim(p_value ->> 'phone'), '');
  hours text := left(nullif(btrim(p_value ->> 'hours'), ''), 80);
begin
  perform public.require_admin();
  if telegram is not null and telegram !~ '^https://t\.me/[A-Za-z0-9_]{5,32}/?$' then
    raise exception 'invalid telegram link' using errcode = '22023';
  end if;
  if community is not null and community !~ '^https://t\.me/(\+[A-Za-z0-9_-]{8,40}|[A-Za-z0-9_]{5,32})/?$' then
    raise exception 'invalid community link' using errcode = '22023';
  end if;
  if phone is not null and phone !~ '^\+?[0-9][0-9 ]{5,18}$' then
    raise exception 'invalid phone' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at)
  values ('support_contacts', jsonb_strip_nulls(jsonb_build_object(
    'telegram_url', telegram, 'community_url', community, 'phone', phone, 'hours', hours)), now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;

create or replace function public.html_escape(p text)
returns text
language sql
immutable
set search_path = ''
as $$
  select replace(replace(replace(coalesce(p, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
$$;

-- At most 5 tickets a day and 10 open at a time per user.
create or replace function public.submit_support_ticket(p_category text, p_message text, p_contact text, p_context jsonb)
returns public.support_tickets
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  ticket public.support_tickets;
  who text;
  a record;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if (select count(*) from public.support_tickets where user_id = uid and created_at > now() - interval '1 day') >= 5
     or (select count(*) from public.support_tickets where user_id = uid and status in ('OPEN', 'IN_PROGRESS')) >= 10 then
    raise exception 'too_many_tickets' using errcode = 'P0001';
  end if;
  insert into public.support_tickets (user_id, category, message, contact, context)
  values (
    uid, upper(p_category), btrim(p_message), left(nullif(btrim(p_contact), ''), 80),
    case when jsonb_typeof(p_context) = 'object' then p_context else '{}'::jsonb end
  )
  returning * into ticket;

  select coalesce(nullif(p.display_name, ''), u.email::text, 'User') into who
  from auth.users u left join public.profiles p on p.id = u.id where u.id = uid;

  for a in
    select t.bot_token, t.chat_id from public.app_admins ad
    join public.telegram_settings t on t.user_id = ad.user_id and t.enabled
  loop
    perform net.http_post(
      url := 'https://api.telegram.org/bot' || a.bot_token || '/sendMessage',
      body := jsonb_build_object(
        'chat_id', a.chat_id,
        'parse_mode', 'HTML',
        'text', '🆘 <b>Support · ' || ticket.category || '</b>' || E'\n'
          || public.html_escape(who) || coalesce(' · ' || public.html_escape(ticket.contact), '') || E'\n\n'
          || public.html_escape(left(ticket.message, 1000)) || E'\n\n— LuyChlat /admin'
      ),
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  end loop;
  return ticket;
end;
$$;

create or replace function public.admin_list_tickets(p_status text, p_limit integer)
returns table (
  id uuid, user_id uuid, email text, display_name text, plan_code text, category text, message text, contact text,
  context jsonb, status text, admin_reply text, replied_at timestamptz, created_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return query
  select t.id, t.user_id, u.email::text, p.display_name, public.plan_code_of(t.user_id), t.category, t.message, t.contact,
         t.context, t.status, t.admin_reply, t.replied_at, t.created_at
  from public.support_tickets t
  join auth.users u on u.id = t.user_id
  left join public.profiles p on p.id = t.user_id
  where case coalesce(p_status, 'active')
    when 'active' then t.status in ('OPEN', 'IN_PROGRESS')
    when 'all' then true
    else t.status = p_status
  end
  order by (t.status = 'OPEN') desc, t.created_at desc
  limit least(coalesce(p_limit, 50), 200);
end;
$$;

create or replace function public.admin_update_ticket(p_ticket_id uuid, p_status text, p_reply text)
returns public.support_tickets
language plpgsql
security definer
set search_path = ''
as $$
declare
  ticket public.support_tickets;
  reply text := left(nullif(btrim(p_reply), ''), 2000);
  tg record;
begin
  perform public.require_admin();
  if p_status not in ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED') then
    raise exception 'invalid status' using errcode = '22023';
  end if;
  update public.support_tickets
  set status = p_status,
      admin_reply = coalesce(reply, admin_reply),
      replied_at = case when reply is not null then now() else replied_at end,
      updated_at = now()
  where id = p_ticket_id
  returning * into ticket;
  if not found then
    raise exception 'ticket not found' using errcode = 'P0002';
  end if;

  if reply is not null then
    select t.bot_token, t.chat_id, t.language into tg from public.telegram_settings t where t.user_id = ticket.user_id and t.enabled;
    if found then
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || tg.bot_token || '/sendMessage',
        body := jsonb_build_object(
          'chat_id', tg.chat_id,
          'parse_mode', 'HTML',
          'text', case when tg.language = 'en' then '💬 <b>LuyChlat Support replied</b>' else '💬 <b>ក្រុមជំនួយ លុយឆ្លាត បានឆ្លើយតប</b>' end
            || E'\n\n' || public.html_escape(reply)
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
    end if;
  end if;
  return ticket;
end;
$$;

-- Users may close their own ticket.
create or replace function public.close_my_ticket(p_ticket_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.support_tickets set status = 'CLOSED', updated_at = now()
  where id = p_ticket_id and user_id = (select auth.uid()) and status <> 'CLOSED';
end;
$$;

revoke all on function public.html_escape(text) from public, anon, authenticated;
revoke all on function public.support_contacts() from public;
grant execute on function public.support_contacts() to anon, authenticated;
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.admin_set_support_contacts(jsonb)',
    'public.submit_support_ticket(text, text, text, jsonb)',
    'public.admin_list_tickets(text, integer)',
    'public.admin_update_ticket(uuid, text, text)',
    'public.close_my_ticket(uuid)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end
$$;


-- ===========================================================================
-- 20261002020000_tontine.sql
-- ===========================================================================

-- ===========================================================================
-- តុងទីន (Tontine / ROSCA) tracker, from the player's side.
--
-- One row in `tontines` per hand (ក្បាល) the user plays. Each round they pay a
-- share; a live member (កូនរស់, hasn't won yet) usually pays the share minus
-- that round's winning bid, a dead member (កូនងាប់, already won) pays the full
-- share. The round they win the bid (ដេញបាន) they collect the pot instead.
--
-- pay_tontine_round() / collect_tontine() record the round and, when a wallet
-- is chosen, the ledger row (expense "បង់តុងទីន" / income "ដេញតុងទីនបាន") in
-- one transaction. Deleting that ledger row undoes the round (or the win).
-- Idempotent: safe to re-run.
-- ===========================================================================

create table if not exists public.tontines (
  id                 uuid primary key default gen_random_uuid(),
  workspace_id       uuid not null references public.workspaces (id) on delete cascade,
  name               text not null check (char_length(btrim(name)) between 1 and 60),
  leader_name        text check (leader_name is null or char_length(leader_name) <= 60),
  leader_phone       text check (leader_phone is null or char_length(leader_phone) <= 30),
  currency           public.currency_code not null,
  share_amount       numeric(18, 2) not null check (share_amount > 0),
  frequency          text not null check (frequency in ('WEEKLY', 'MONTHLY')),
  total_rounds       integer not null check (total_rounds between 2 and 100),
  start_date         date not null,
  -- Wallet suggested for payments (optional).
  wallet_id          uuid,
  won_round          integer,
  won_amount         numeric(18, 2) check (won_amount is null or won_amount > 0),
  won_bid            numeric(18, 2) check (won_bid is null or won_bid >= 0),
  won_on             date,
  won_transaction_id uuid references public.transactions (id) on delete set null,
  note               text check (note is null or char_length(note) <= 500),
  closed_at          timestamptz,
  created_by         uuid default auth.uid() references auth.users (id) on delete set null,
  created_at         timestamptz not null default now(),
  unique (id, workspace_id),
  foreign key (wallet_id, workspace_id) references public.wallets_accounts (id, workspace_id) on delete set null (wallet_id),
  check (won_round is null or won_round between 1 and total_rounds),
  check ((won_round is null) = (won_amount is null))
);
create index if not exists tontines_workspace_idx on public.tontines (workspace_id, created_at desc);

create table if not exists public.tontine_payments (
  id             uuid primary key default gen_random_uuid(),
  tontine_id     uuid not null,
  workspace_id   uuid not null,
  round_no       integer not null check (round_no > 0),
  amount         numeric(18, 2) not null check (amount > 0),
  -- Live members: how much less than the share they paid (the round's bid).
  discount       numeric(18, 2) not null default 0 check (discount >= 0),
  paid_on        date not null,
  transaction_id uuid unique references public.transactions (id) on delete cascade,
  created_at     timestamptz not null default now(),
  foreign key (tontine_id, workspace_id) references public.tontines (id, workspace_id) on delete cascade,
  unique (tontine_id, round_no)
);
create index if not exists tontine_payments_workspace_idx on public.tontine_payments (workspace_id);

alter table public.tontines enable row level security;
alter table public.tontine_payments enable row level security;
do $$
declare
  t text;
begin
  foreach t in array array['tontines', 'tontine_payments'] loop
    execute format('drop policy if exists %1$s_select on public.%1$I', t);
    execute format('drop policy if exists %1$s_insert on public.%1$I', t);
    execute format('drop policy if exists %1$s_update on public.%1$I', t);
    execute format('drop policy if exists %1$s_delete on public.%1$I', t);
    execute format('create policy %1$s_select on public.%1$I for select to authenticated using (public.is_workspace_member(workspace_id))', t);
    execute format('create policy %1$s_insert on public.%1$I for insert to authenticated with check (public.can_write_workspace(workspace_id))', t);
    execute format('create policy %1$s_update on public.%1$I for update to authenticated using (public.can_write_workspace(workspace_id)) with check (public.can_write_workspace(workspace_id))', t);
    execute format('create policy %1$s_delete on public.%1$I for delete to authenticated using (public.can_write_workspace(workspace_id))', t);
  end loop;
end
$$;

-- Rounds stay inside the cycle, and the won round is never also a paid one.
create or replace function public.guard_tontine_payment()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  t public.tontines;
begin
  select * into t from public.tontines where id = new.tontine_id;
  if new.round_no > t.total_rounds then
    raise exception 'round_out_of_range' using errcode = '22023';
  end if;
  if new.round_no = t.won_round then
    raise exception 'round_is_won' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create or replace trigger tontine_payments_guard
  before insert or update on public.tontine_payments
  for each row execute function public.guard_tontine_payment();

create or replace function public.guard_tontine()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.won_round is not null and exists (
    select 1 from public.tontine_payments p where p.tontine_id = new.id and p.round_no = new.won_round
  ) then
    raise exception 'round_paid' using errcode = 'P0001';
  end if;
  if tg_op = 'UPDATE' and new.total_rounds < coalesce((select max(round_no) from public.tontine_payments p where p.tontine_id = new.id), 0) then
    raise exception 'round_out_of_range' using errcode = '22023';
  end if;
  return new;
end;
$$;
create or replace trigger tontines_guard
  before insert or update on public.tontines
  for each row execute function public.guard_tontine();

-- Deleting the pot's ledger row undoes the win (back to កូនរស់).
create or replace function public.clear_tontine_win()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.tontines
  set won_round = null, won_amount = null, won_bid = null, won_on = null, won_transaction_id = null
  where won_transaction_id = old.id;
  return old;
end;
$$;
create or replace trigger transactions_clear_tontine_win
  before delete on public.transactions
  for each row execute function public.clear_tontine_win();

-- ---------------------------------------------------------------------------
-- Pay one round. With a wallet, also records the expense (in the tontine's
-- currency; exchange_rate when the wallet uses the other one).
-- ---------------------------------------------------------------------------
create or replace function public.pay_tontine_round(
  p_tontine_id uuid, p_round_no integer, p_amount numeric, p_discount numeric, p_paid_on date,
  p_wallet_id uuid, p_exchange_rate numeric, p_note text
)
returns public.tontine_payments
language plpgsql
set search_path = ''
as $$
declare
  t public.tontines;
  w public.wallets_accounts;
  tx_id uuid;
  result public.tontine_payments;
begin
  select * into t from public.tontines where id = p_tontine_id for update;
  if not found then
    raise exception 'tontine not found' using errcode = 'P0002';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;

  if p_wallet_id is not null then
    select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = t.workspace_id;
    if not found then
      raise exception 'wallet not found in this workspace' using errcode = 'P0002';
    end if;
    insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date)
    values (
      t.workspace_id, w.id,
      public.ensure_preset_category(t.workspace_id, 'tontine_payment', 'EXPENSE', 'piggy-bank', '#f59e0b', 'បង់តុងទីន'),
      p_amount, t.currency, 'EXPENSE',
      case when w.currency = t.currency then null else p_exchange_rate end,
      left(coalesce(nullif(btrim(p_note), ''), t.name || ' · #' || p_round_no), 500),
      (coalesce(p_paid_on, current_date) + time '12:00') at time zone 'Asia/Phnom_Penh'
    )
    returning id into tx_id;
  end if;

  insert into public.tontine_payments (tontine_id, workspace_id, round_no, amount, discount, paid_on, transaction_id)
  values (t.id, t.workspace_id, p_round_no, p_amount, greatest(coalesce(p_discount, 0), 0), coalesce(p_paid_on, current_date), tx_id)
  returning * into result;
  return result;
exception when unique_violation then
  raise exception 'round_paid' using errcode = 'P0001';
end;
$$;

-- Won the bid: collect the pot (income into the wallet) and become កូនងាប់.
create or replace function public.collect_tontine(
  p_tontine_id uuid, p_round_no integer, p_amount numeric, p_bid numeric, p_received_on date,
  p_wallet_id uuid, p_exchange_rate numeric, p_note text
)
returns public.tontines
language plpgsql
set search_path = ''
as $$
declare
  t public.tontines;
  w public.wallets_accounts;
  tx_id uuid;
begin
  select * into t from public.tontines where id = p_tontine_id for update;
  if not found then
    raise exception 'tontine not found' using errcode = 'P0002';
  end if;
  if t.won_round is not null then
    raise exception 'already_won' using errcode = 'P0001';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;

  if p_wallet_id is not null then
    select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = t.workspace_id;
    if not found then
      raise exception 'wallet not found in this workspace' using errcode = 'P0002';
    end if;
    insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date)
    values (
      t.workspace_id, w.id,
      public.ensure_preset_category(t.workspace_id, 'tontine_payout', 'INCOME', 'coins', '#10b981', 'ដេញតុងទីនបាន'),
      p_amount, t.currency, 'INCOME',
      case when w.currency = t.currency then null else p_exchange_rate end,
      left(coalesce(nullif(btrim(p_note), ''), t.name || ' · #' || p_round_no), 500),
      (coalesce(p_received_on, current_date) + time '12:00') at time zone 'Asia/Phnom_Penh'
    )
    returning id into tx_id;
  end if;

  update public.tontines
  set won_round = p_round_no, won_amount = p_amount, won_bid = nullif(greatest(coalesce(p_bid, 0), 0), 0),
      won_on = coalesce(p_received_on, current_date), won_transaction_id = tx_id
  where id = t.id
  returning * into t;
  return t;
end;
$$;

-- Undo a win recorded without a ledger row (with one, deleting the row undoes it).
create or replace function public.undo_tontine_win(p_tontine_id uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  t public.tontines;
begin
  select * into t from public.tontines where id = p_tontine_id for update;
  if not found then
    raise exception 'tontine not found' using errcode = 'P0002';
  end if;
  if t.won_transaction_id is not null then
    delete from public.transactions where id = t.won_transaction_id;
  else
    update public.tontines set won_round = null, won_amount = null, won_bid = null, won_on = null where id = t.id;
  end if;
end;
$$;

-- Guest Mode → account: tontines and their rounds (ids kept, like the ledger).
create or replace function public.import_guest_tontines(p_workspace_id uuid, p_data jsonb)
returns integer
language plpgsql
set search_path = ''
as $$
declare
  t jsonb;
  p jsonb;
  added integer;
  n integer := 0;
begin
  if not public.can_write_workspace(p_workspace_id) then
    raise exception 'no write access to this workspace' using errcode = '42501';
  end if;
  for t in select value from jsonb_array_elements(coalesce(p_data -> 'tontines', '[]'::jsonb)) loop
    insert into public.tontines (
      id, workspace_id, name, leader_name, leader_phone, currency, share_amount, frequency, total_rounds, start_date,
      wallet_id, won_round, won_amount, won_bid, won_on, won_transaction_id, note, closed_at, created_at
    ) values (
      (t ->> 'id')::uuid, p_workspace_id, t ->> 'name', t ->> 'leader_name', t ->> 'leader_phone',
      (t ->> 'currency')::public.currency_code, (t ->> 'share_amount')::numeric, t ->> 'frequency',
      (t ->> 'total_rounds')::integer, (t ->> 'start_date')::date,
      (select w.id from public.wallets_accounts w where w.id = (t ->> 'wallet_id')::uuid and w.workspace_id = p_workspace_id),
      (t ->> 'won_round')::integer, (t ->> 'won_amount')::numeric, (t ->> 'won_bid')::numeric, (t ->> 'won_on')::date,
      (select x.id from public.transactions x where x.id = (t ->> 'won_transaction_id')::uuid and x.workspace_id = p_workspace_id),
      t ->> 'note', (t ->> 'closed_at')::timestamptz, coalesce((t ->> 'created_at')::timestamptz, now())
    )
    on conflict do nothing;
    get diagnostics added = row_count;
    n := n + added;
  end loop;
  for p in select value from jsonb_array_elements(coalesce(p_data -> 'payments', '[]'::jsonb)) loop
    insert into public.tontine_payments (id, tontine_id, workspace_id, round_no, amount, discount, paid_on, transaction_id, created_at)
    select (p ->> 'id')::uuid, tn.id, p_workspace_id, (p ->> 'round_no')::integer, (p ->> 'amount')::numeric,
           coalesce((p ->> 'discount')::numeric, 0), (p ->> 'paid_on')::date,
           (select x.id from public.transactions x where x.id = (p ->> 'transaction_id')::uuid and x.workspace_id = p_workspace_id),
           coalesce((p ->> 'created_at')::timestamptz, now())
    from public.tontines tn where tn.id = (p ->> 'tontine_id')::uuid and tn.workspace_id = p_workspace_id
    on conflict do nothing;
  end loop;
  return n;
end;
$$;

-- ---------------------------------------------------------------------------
-- Default categories: "បង់តុងទីន" (expense) and "ដេញតុងទីនបាន" (income) in
-- every workspace, new and existing. Supersedes the definition in
-- 20261001070100_family_sharing.sql (same presets + the two tontine ones).
-- ---------------------------------------------------------------------------
create or replace function public.seed_default_categories(p_workspace_id uuid, p_type public.workspace_type)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_type in ('PERSONAL', 'FAMILY') then
    insert into public.categories (workspace_id, preset_key, type, icon, color, name) values
      (p_workspace_id, 'food',          'EXPENSE', 'utensils',       '#f97316', 'ម្ហូបអាហារ'),
      (p_workspace_id, 'transport',     'EXPENSE', 'bus',            '#0ea5e9', 'ការធ្វើដំណើរ'),
      (p_workspace_id, 'housing',       'EXPENSE', 'house',          '#8b5cf6', 'ផ្ទះ/ទឹកភ្លើង'),
      (p_workspace_id, 'shopping',      'EXPENSE', 'shopping-bag',   '#ec4899', 'ទិញឥវ៉ាន់'),
      (p_workspace_id, 'phone',         'EXPENSE', 'smartphone',     '#6366f1', 'ទូរស័ព្ទ/អ៊ីនធឺណិត'),
      (p_workspace_id, 'health',        'EXPENSE', 'heart-pulse',    '#ef4444', 'សុខភាព'),
      (p_workspace_id, 'education',     'EXPENSE', 'graduation-cap', '#14b8a6', 'ការសិក្សា'),
      (p_workspace_id, 'family',        'EXPENSE', 'gift',           '#d946ef', 'គ្រួសារ/អំណោយ'),
      (p_workspace_id, 'entertainment', 'EXPENSE', 'film',           '#f59e0b', 'កម្សាន្ត'),
      (p_workspace_id, 'other_expense', 'EXPENSE', 'ellipsis',       '#64748b', 'ចំណាយផ្សេងៗ'),
      (p_workspace_id, 'salary',        'INCOME',  'banknote',       '#16a34a', 'ប្រាក់ខែ'),
      (p_workspace_id, 'bonus',         'INCOME',  'award',          '#22c55e', 'ប្រាក់រង្វាន់'),
      (p_workspace_id, 'side_income',   'INCOME',  'trending-up',    '#10b981', 'ចំណូលបន្ថែម'),
      (p_workspace_id, 'gift_received', 'INCOME',  'hand-heart',     '#84cc16', 'ទទួលអំណោយ'),
      (p_workspace_id, 'other_income',  'INCOME',  'coins',          '#64748b', 'ចំណូលផ្សេងៗ');
  else
    insert into public.categories (workspace_id, preset_key, type, icon, color, name) values
      (p_workspace_id, 'inventory',     'EXPENSE', 'package',        '#f97316', 'ថ្លៃទំនិញ/ស្តុក'),
      (p_workspace_id, 'rent',          'EXPENSE', 'store',          '#8b5cf6', 'ជួលទីតាំង'),
      (p_workspace_id, 'payroll',       'EXPENSE', 'users',          '#0ea5e9', 'ប្រាក់បៀវត្សបុគ្គលិក'),
      (p_workspace_id, 'utilities',     'EXPENSE', 'zap',            '#eab308', 'ទឹកភ្លើង'),
      (p_workspace_id, 'marketing',     'EXPENSE', 'megaphone',      '#ec4899', 'ផ្សព្វផ្សាយ'),
      (p_workspace_id, 'delivery',      'EXPENSE', 'truck',          '#14b8a6', 'ដឹកជញ្ជូន'),
      (p_workspace_id, 'equipment',     'EXPENSE', 'wrench',         '#6366f1', 'សម្ភារៈ/ជួសជុល'),
      (p_workspace_id, 'tax',           'EXPENSE', 'landmark',       '#ef4444', 'ពន្ធ/សេវា'),
      (p_workspace_id, 'other_expense', 'EXPENSE', 'ellipsis',       '#64748b', 'ចំណាយផ្សេងៗ'),
      (p_workspace_id, 'sales',         'INCOME',  'shopping-cart',  '#16a34a', 'ចំណូលពីការលក់'),
      (p_workspace_id, 'services',      'INCOME',  'briefcase',      '#10b981', 'ចំណូលពីសេវាកម្ម'),
      (p_workspace_id, 'investment',    'INCOME',  'piggy-bank',     '#84cc16', 'ដើមទុនវិនិយោគ'),
      (p_workspace_id, 'other_income',  'INCOME',  'coins',          '#64748b', 'ចំណូលផ្សេងៗ');
  end if;
  perform public.ensure_preset_category(p_workspace_id, 'tontine_payment', 'EXPENSE', 'piggy-bank', '#f59e0b', 'បង់តុងទីន');
  perform public.ensure_preset_category(p_workspace_id, 'tontine_payout', 'INCOME', 'coins', '#10b981', 'ដេញតុងទីនបាន');
end;
$$;
revoke all on function public.seed_default_categories(uuid, public.workspace_type) from public, anon, authenticated;

do $$
declare
  ws record;
begin
  for ws in select id from public.workspaces loop
    perform public.ensure_preset_category(ws.id, 'tontine_payment', 'EXPENSE', 'piggy-bank', '#f59e0b', 'បង់តុងទីន');
    perform public.ensure_preset_category(ws.id, 'tontine_payout', 'INCOME', 'coins', '#10b981', 'ដេញតុងទីនបាន');
  end loop;
end
$$;

-- "Reset my data" also clears tontines. Supersedes 20261001070100.
create or replace function public.reset_my_data()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  ws record;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  create temporary table reset_ws on commit drop as
    select id, type from public.workspaces where user_id = uid and type <> 'FAMILY';

  delete from public.notifications where workspace_id in (select id from reset_ws);
  delete from public.tontines where workspace_id in (select id from reset_ws);
  delete from public.transactions where workspace_id in (select id from reset_ws);
  delete from public.debts where workspace_id in (select id from reset_ws);
  delete from public.budgets where workspace_id in (select id from reset_ws);
  delete from public.wallets_accounts where workspace_id in (select id from reset_ws);
  delete from public.categories where workspace_id in (select id from reset_ws);
  delete from public.telegram_settings where user_id = uid;

  for ws in select id, type from reset_ws loop
    perform public.seed_default_categories(ws.id, ws.type);
  end loop;
end;
$$;
revoke all on function public.reset_my_data() from public, anon;
grant execute on function public.reset_my_data() to authenticated;

-- Family members see each other's rounds live.
do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    return;
  end if;
  foreach t in array array['tontines', 'tontine_payments'] loop
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end
$$;

revoke all on function public.guard_tontine_payment() from public, anon, authenticated;
revoke all on function public.guard_tontine() from public, anon, authenticated;
revoke all on function public.clear_tontine_win() from public, anon, authenticated;
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.pay_tontine_round(uuid, integer, numeric, numeric, date, uuid, numeric, text)',
    'public.collect_tontine(uuid, integer, numeric, numeric, date, uuid, numeric, text)',
    'public.undo_tontine_win(uuid)',
    'public.import_guest_tontines(uuid, jsonb)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end
$$;


-- ===========================================================================
-- 20261003000000_static_khqr.sql
-- ===========================================================================

-- ===========================================================================
-- Static KHQR payment (replaces the dynamic Bakong Open API checkout).
--
-- The admin uploads the shop's static KHQR image (e.g. from the ABA app).
-- Get PRO shows it with the exact amount to enter; the user pays, taps
-- "I have paid" (a PENDING payment via request_upgrade), sends the slip on
-- Telegram, and the admin approves in /admin. No external API.
--
-- Also removes what the short-lived dynamic version (same date) created, in
-- case it was applied. Idempotent: safe to re-run.
-- ===========================================================================

drop function if exists public.khqr_create_payment(uuid, text, public.currency_code, text, text, text, timestamptz, boolean);
