-- ===========================================================================
-- 20261003010000_about_info.sql
-- ===========================================================================

-- ===========================================================================
-- Settings › About LuyChlat: developer credits, mission and official links,
-- editable by admins (app_settings "about_info"; readable by signed-in users
-- through the existing app_settings select policy). Idempotent.
-- ===========================================================================
create or replace function public.admin_set_about_info(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
  link text;
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 4000 then
    raise exception 'invalid settings' using errcode = '22023';
  end if;
  if char_length(coalesce(v ->> 'developer', '')) > 80
     or char_length(coalesce(v ->> 'credits', '')) > 1000
     or char_length(coalesce(v ->> 'mission_km', '')) > 500
     or char_length(coalesce(v ->> 'mission_en', '')) > 500 then
    raise exception 'text too long' using errcode = '22023';
  end if;
  foreach link in array array[v ->> 'website', v ->> 'facebook'] loop
    if nullif(btrim(link), '') is not null and (link !~ '^https://[^\s"<>]+$' or char_length(link) > 200) then
      raise exception 'links must start with https://' using errcode = '22023';
    end if;
  end loop;
  if nullif(btrim(v ->> 'email'), '') is not null and (v ->> 'email') !~ '^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$' then
    raise exception 'invalid email' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at) values ('about_info', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_about_info(jsonb) from public, anon;
grant execute on function public.admin_set_about_info(jsonb) to authenticated;


-- ===========================================================================
-- 20261003020000_brand_luychlat.sql
-- ===========================================================================

-- ===========================================================================
-- Brand: the English name is now "LuyChlat" (Khmer stays លុយឆ្លាត).
-- Several functions sign their Telegram messages "— លុយឆ្លាត · LuySmart";
-- rewrite them in place (same definition, grants and owner) instead of
-- copying their bodies here. Idempotent: once renamed, nothing matches.
-- Internal identifiers (table names, the "luysmart" AI provider value,
-- browser storage keys) are unchanged on purpose.
-- ===========================================================================
do $$
declare
  f record;
begin
  for f in
    select p.oid
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prokind = 'f' and p.prosrc like '%LuySmart%'
  loop
    execute replace(pg_get_functiondef(f.oid), 'LuySmart', 'LuyChlat');
  end loop;
end
$$;


-- ===========================================================================
-- 20261003030000_exchange_rate.sql
-- ===========================================================================

-- ===========================================================================
-- Exchange rate (KHR per 1 USD) saved in the database, per workspace, so it
-- is the same on every device and survives clearing the browser. Before, it
-- lived only in each browser's local storage (and showed the 4,100 default
-- on any device where it was never set).
--
-- null = not set yet: the app uses the default (4,000). set_exchange_rate()
-- applies the user's rate to every workspace they own (Personal, Business,
-- their Family); family members see the owner's rate there.
-- Idempotent: safe to re-run.
-- ===========================================================================
alter table public.workspaces
  add column if not exists khr_per_usd numeric(8, 2);
alter table public.workspaces
  drop constraint if exists workspaces_khr_per_usd_range,
  add constraint workspaces_khr_per_usd_range check (khr_per_usd is null or khr_per_usd between 1000 and 10000);

create or replace function public.set_exchange_rate(p_rate numeric)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  changed integer;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_rate is null or p_rate < 1000 or p_rate > 10000 then
    raise exception 'rate must be between 1000 and 10000' using errcode = '22023';
  end if;
  update public.workspaces set khr_per_usd = round(p_rate) where user_id = uid;
  get diagnostics changed = row_count;
  return changed;
end;
$$;
revoke all on function public.set_exchange_rate(numeric) from public, anon;
grant execute on function public.set_exchange_rate(numeric) to authenticated;


-- ===========================================================================
-- 20261004000000_islamic_finance.sql
-- ===========================================================================

-- ===========================================================================
-- Islamic Finance tools (optional, off by default).
--
-- Settings live in their own table, readable only by the user: whether
-- someone uses these tools is religious information, so it is NOT stored on
-- profiles (family members can read each other's profiles). The flag syncs
-- across the user's devices.
--
-- Turning the tools on adds five categories to the user's own workspaces:
-- Zakat, Sadaqah, Waqf (spending), Bank interest / Riba (income kept out of
-- totals) and Riba purification (its donation, also out of totals). Turning
-- them off keeps all data; the app just hides the tools again.
-- Idempotent: safe to re-run.
-- ===========================================================================

create table if not exists public.islamic_settings (
  user_id         uuid primary key references auth.users (id) on delete cascade,
  enabled         boolean not null default false,
  nisab_basis     text not null default 'GOLD' check (nisab_basis in ('GOLD', 'SILVER')),
  -- Price per gram in USD; null = use the admin default.
  gold_price      numeric(12, 4) check (gold_price is null or gold_price > 0),
  silver_price    numeric(12, 4) check (silver_price is null or silver_price > 0),
  -- Gold the user holds as savings (grams), counted as zakatable wealth.
  gold_grams      numeric(12, 3) not null default 0 check (gold_grams >= 0),
  -- Start of the current lunar year (hawl) for Zakat; due 354 days later.
  hawl_start      date,
  include_receivables boolean not null default false,
  include_business    boolean not null default true,
  updated_at      timestamptz not null default now()
);
alter table public.islamic_settings enable row level security;
drop policy if exists islamic_settings_own on public.islamic_settings;
create policy islamic_settings_own on public.islamic_settings
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Turns the tools on/off for the caller; on also adds the categories to the
-- workspaces the caller owns (Personal, Business, their Family).
create or replace function public.set_islamic_tools(p_enabled boolean)
returns public.islamic_settings
language plpgsql
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  ws record;
  result public.islamic_settings;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  insert into public.islamic_settings (user_id, enabled, updated_at)
  values (uid, coalesce(p_enabled, false), now())
  on conflict (user_id) do update set enabled = excluded.enabled, updated_at = now()
  returning * into result;

  if result.enabled then
    for ws in select id from public.workspaces where user_id = uid loop
      perform public.ensure_preset_category(ws.id, 'zakat', 'EXPENSE', 'hand-heart', '#059669', 'ហ្សាកាត់');
      perform public.ensure_preset_category(ws.id, 'sadaqah', 'EXPENSE', 'hand-heart', '#0d9488', 'ទាន សាដាកះ');
      perform public.ensure_preset_category(ws.id, 'waqf', 'EXPENSE', 'landmark', '#0891b2', 'វ៉ាក់ហ្វ');
      perform public.ensure_preset_category(ws.id, 'riba_purification', 'EXPENSE', 'scale', '#64748b', 'សម្អាតការប្រាក់');
      perform public.ensure_preset_category(ws.id, 'bank_interest', 'INCOME', 'landmark', '#64748b', 'ការប្រាក់ធនាគារ');
    end loop;
  end if;
  return result;
end;
$$;
revoke all on function public.set_islamic_tools(boolean) from public, anon;
grant execute on function public.set_islamic_tools(boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- Admin defaults (app_settings "islamic_defaults"): gold / silver price per
-- gram in USD, and a ±2-day Hijri offset to follow the local moon-sighting
-- announcement (Ramadan / Eid dates).
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_islamic_defaults(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 1000 then
    raise exception 'invalid settings' using errcode = '22023';
  end if;
  if (v ? 'gold_price' and v ->> 'gold_price' is not null and not ((v ->> 'gold_price') ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> 'gold_price')::numeric between 0.01 and 100000))
     or (v ? 'silver_price' and v ->> 'silver_price' is not null and not ((v ->> 'silver_price') ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> 'silver_price')::numeric between 0.001 and 10000))
     or (v ? 'hijri_offset' and v ->> 'hijri_offset' is not null and not ((v ->> 'hijri_offset') ~ '^-?[0-2]$')) then
    raise exception 'invalid value' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at) values ('islamic_defaults', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_islamic_defaults(jsonb) from public, anon;
grant execute on function public.admin_set_islamic_defaults(jsonb) to authenticated;


-- ===========================================================================
-- 20261005000000_profiles_business_places.sql
-- ===========================================================================

-- Profile photo / phone / bio, the business profile of a BUSINESS workspace,
-- a private bucket for those images, and a directory of mosques, surau and
-- halal food places (admin-approved). Idempotent.

-- ---------------------------------------------------------------------------
-- Personal profile: photo (storage path), phone and a short bio. Visible to
-- the user and to people they share a workspace with (existing profiles_select).
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists avatar_path text;
alter table public.profiles add column if not exists phone text;
alter table public.profiles add column if not exists bio text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_avatar_path_check') then
    alter table public.profiles add constraint profiles_avatar_path_check
      check (avatar_path is null or avatar_path like 'user/' || id::text || '/%');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_phone_check') then
    alter table public.profiles add constraint profiles_phone_check
      check (phone is null or char_length(phone) <= 30);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_bio_check') then
    alter table public.profiles add constraint profiles_bio_check
      check (bio is null or char_length(bio) <= 200);
  end if;
end $$;

grant update (avatar_path, phone, bio) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- Business profile on the workspace row (the owner edits it; members read it).
-- The business name is the workspace name.
-- ---------------------------------------------------------------------------
alter table public.workspaces add column if not exists logo_path text;
alter table public.workspaces add column if not exists business_phone text;
alter table public.workspaces add column if not exists business_address text;
alter table public.workspaces add column if not exists business_industry text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'workspaces_logo_path_check') then
    alter table public.workspaces add constraint workspaces_logo_path_check
      check (logo_path is null or logo_path like 'ws/' || id::text || '/%');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'workspaces_business_fields_check') then
    alter table public.workspaces add constraint workspaces_business_fields_check
      check (
        (business_phone is null or char_length(business_phone) <= 30)
        and (business_address is null or char_length(business_address) <= 200)
        and (business_industry is null or char_length(business_industry) <= 60)
      );
  end if;
end $$;

grant update (logo_path, business_phone, business_address, business_industry) on public.workspaces to authenticated;

-- ---------------------------------------------------------------------------
-- Images: private bucket, shown through short-lived signed URLs.
--   user/<user id>/<file>      personal photo: the user writes; people who
--                              share a workspace with them may view
--   ws/<workspace id>/<file>   business logo: the owner writes; members view
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('profile-images', 'profile-images', false, 1048576, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create or replace function public.profile_image_access(p_name text, p_write boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  parts text[] := string_to_array(p_name, '/');
  uid uuid := auth.uid();
  target uuid;
begin
  if uid is null or array_length(parts, 1) <> 3 or parts[2] !~ '^[0-9a-f-]{36}$' then
    return false;
  end if;
  target := parts[2]::uuid;
  if parts[1] = 'user' then
    return target = uid or (not p_write and public.shares_workspace_with(target));
  elsif parts[1] = 'ws' then
    if p_write then
      return exists (select 1 from public.workspaces w where w.id = target and w.user_id = uid and w.type = 'BUSINESS');
    end if;
    return public.is_workspace_member(target);
  end if;
  return false;
end;
$$;
revoke all on function public.profile_image_access(text, boolean) from public, anon;
grant execute on function public.profile_image_access(text, boolean) to authenticated;

drop policy if exists profile_images_select on storage.objects;
create policy profile_images_select on storage.objects
  for select to authenticated using (bucket_id = 'profile-images' and public.profile_image_access(name, false));
drop policy if exists profile_images_insert on storage.objects;
create policy profile_images_insert on storage.objects
  for insert to authenticated with check (bucket_id = 'profile-images' and public.profile_image_access(name, true));
drop policy if exists profile_images_update on storage.objects;
create policy profile_images_update on storage.objects
  for update to authenticated
  using (bucket_id = 'profile-images' and public.profile_image_access(name, true))
  with check (bucket_id = 'profile-images' and public.profile_image_access(name, true));
drop policy if exists profile_images_delete on storage.objects;
create policy profile_images_delete on storage.objects
  for delete to authenticated using (bucket_id = 'profile-images' and public.profile_image_access(name, true));

-- ---------------------------------------------------------------------------
-- Mosques, surau and halal food places. Signed-in users may suggest a place;
-- it is listed for everyone only after an admin approves it. Only admins can
-- mark a place as halal-certified.
-- ---------------------------------------------------------------------------
create table if not exists public.islamic_places (
  id              uuid primary key default gen_random_uuid(),
  kind            text not null check (kind in ('MOSQUE', 'SURAU', 'HALAL')),
  name            text not null check (char_length(btrim(name)) between 1 and 120),
  province        text check (province is null or char_length(province) <= 40),
  address         text check (address is null or char_length(address) <= 300),
  lat             double precision check (lat is null or lat between -90 and 90),
  lng             double precision check (lng is null or lng between -180 and 180),
  phone           text check (phone is null or char_length(phone) <= 30),
  note            text check (note is null or char_length(note) <= 300),
  halal_certified boolean not null default false,
  approved        boolean not null default false,
  created_by      uuid default auth.uid() references auth.users (id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists islamic_places_approved_idx on public.islamic_places (approved, kind);
alter table public.islamic_places enable row level security;

drop policy if exists islamic_places_select on public.islamic_places;
create policy islamic_places_select on public.islamic_places
  for select to authenticated
  using (approved or created_by = (select auth.uid()) or public.is_admin());
drop policy if exists islamic_places_insert on public.islamic_places;
create policy islamic_places_insert on public.islamic_places
  for insert to authenticated
  with check (
    public.is_admin()
    or (created_by = (select auth.uid()) and not approved and not halal_certified)
  );
drop policy if exists islamic_places_update on public.islamic_places;
create policy islamic_places_update on public.islamic_places
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists islamic_places_delete on public.islamic_places;
create policy islamic_places_delete on public.islamic_places
  for delete to authenticated
  using (public.is_admin() or (created_by = (select auth.uid()) and not approved));

grant select, insert, update, delete on public.islamic_places to authenticated;

-- At most 10 suggestions waiting for review per person (keeps the queue clean).
create or replace function public.limit_place_suggestions()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not new.approved and not public.is_admin()
     and (select count(*) from public.islamic_places p where p.created_by = new.created_by and not p.approved) >= 10 then
    raise exception 'too many pending suggestions' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
drop trigger if exists islamic_places_limit on public.islamic_places;
create trigger islamic_places_limit
  before insert on public.islamic_places
  for each row execute function public.limit_place_suggestions();


-- ===========================================================================
-- 20261006000000_debt_insurance_savings_goals.sql
-- ===========================================================================

-- Loan insurance on debts, and savings goals. Idempotent.

-- ---------------------------------------------------------------------------
-- Debts: optional loan insurance (e.g. credit life required by the bank).
-- ---------------------------------------------------------------------------
alter table public.debts add column if not exists insured boolean not null default false;
alter table public.debts add column if not exists insurer text;
alter table public.debts add column if not exists insurance_policy_no text;
alter table public.debts add column if not exists insurance_premium numeric(18, 2);
alter table public.debts add column if not exists insurance_currency public.currency_code;
alter table public.debts add column if not exists insurance_renewal_date date;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'debts_insurance_check') then
    alter table public.debts add constraint debts_insurance_check
      check (
        (insurer is null or char_length(insurer) <= 60)
        and (insurance_policy_no is null or char_length(insurance_policy_no) <= 60)
        and (insurance_premium is null or insurance_premium >= 0)
      );
  end if;
end $$;

grant update (insured, insurer, insurance_policy_no, insurance_premium, insurance_currency, insurance_renewal_date)
  on public.debts to authenticated;

-- ---------------------------------------------------------------------------
-- Savings goals: a goal is a savings pot (a wallet with a target). Money gets
-- in and out only by transfers from/to the user's other wallets, so net worth
-- never changes when saving; a goal starts empty.
-- ---------------------------------------------------------------------------
alter table public.wallets_accounts add column if not exists goal_target numeric(18, 2);
alter table public.wallets_accounts add column if not exists goal_date date;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'wallets_goal_target_check') then
    alter table public.wallets_accounts add constraint wallets_goal_target_check
      check (goal_target is null or goal_target > 0);
  end if;
end $$;

create index if not exists wallets_accounts_goals_idx on public.wallets_accounts (workspace_id) where goal_target is not null;

grant update (goal_target, goal_date) on public.wallets_accounts to authenticated;

create or replace function public.guard_goal_wallet()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(current_setting('luysmart.import', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.goal_target is not null and new.balance <> 0 then
      raise exception 'goal_starts_empty' using errcode = 'P0001';
    end if;
  elsif (old.goal_target is null) <> (new.goal_target is null) then
    -- A wallet can't become a goal (or back): its history would stop adding up.
    raise exception 'goal_kind_locked' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists wallets_accounts_goal_guard on public.wallets_accounts;
create trigger wallets_accounts_goal_guard
  before insert or update of goal_target on public.wallets_accounts
  for each row execute function public.guard_goal_wallet();

-- Income and expenses can't be booked on a goal: only transfers move money in or out.
create or replace function public.guard_goal_transactions()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.type <> 'TRANSFER'
     and exists (select 1 from public.wallets_accounts w where w.id = new.wallet_id and w.goal_target is not null) then
    raise exception 'goal_transfers_only' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists transactions_goal_guard on public.transactions;
create trigger transactions_goal_guard
  before insert or update of type, wallet_id on public.transactions
  for each row execute function public.guard_goal_transactions();

-- The plan's wallet limit doesn't count savings goals.
create or replace function public.guard_wallet_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  owner uuid;
  max_wallets integer;
  used integer;
begin
  if (select auth.uid()) is null or coalesce(current_setting('luysmart.import', true), '') = 'on' then
    return new;
  end if;
  -- Only creating a wallet or bringing one back from the archive counts.
  if tg_op = 'UPDATE' and not (old.archived_at is not null and new.archived_at is null) then
    return new;
  end if;
  if new.archived_at is not null or new.goal_target is not null then
    return new;
  end if;
  select user_id into owner from public.workspaces where id = new.workspace_id;
  max_wallets := (public.plan_of(owner)).max_wallets;
  if max_wallets is null then
    return new;
  end if;
  select count(*) into used
  from public.wallets_accounts w join public.workspaces ws on ws.id = w.workspace_id
  where ws.user_id = owner and w.archived_at is null and w.goal_target is null and w.id <> new.id;
  if used >= max_wallets then
    raise exception 'plan_limit:wallets' using errcode = 'P0001', hint = max_wallets::text;
  end if;
  return new;
end;
$$;


-- ===========================================================================
-- 20261007000000_ultra_business_trial.sql
-- ===========================================================================

-- Free / Pro / Ultra. Idempotent.
--   Free  : Personal + one Business workspace on a 90-day trial (read-only after)
--   Pro   : Personal + one Business workspace
--   Ultra : Personal + any number of Business workspaces
-- A Business workspace beyond the plan's allowance, or a Free one after its
-- trial, stays readable (and exportable) but can't be changed. Nothing is
-- deleted when a plan ends.

-- ---------------------------------------------------------------------------
-- Plans
-- ---------------------------------------------------------------------------
alter table public.plans drop constraint if exists plans_tier_check;
alter table public.plans add constraint plans_tier_check check (tier in ('FREE', 'PRO', 'ULTRA'));
-- null = unlimited
alter table public.plans add column if not exists max_business_workspaces integer;
alter table public.plans add column if not exists business_trial_days integer not null default 0;

update public.plans set max_business_workspaces = 1, business_trial_days = 90 where code = 'FREE';
update public.plans set max_business_workspaces = 1, business_trial_days = 0, price_usd = 2.99, price_khr = 12000 where code = 'PRO_MONTHLY';
update public.plans set max_business_workspaces = 1, business_trial_days = 0, price_usd = 24.99, price_khr = 100000 where code = 'PRO_YEARLY';

insert into public.plans (code, tier, name, price_usd, price_khr, period_days, max_wallets, max_family_members, ai_queries_per_month, can_export, can_credit_score, sort_order, max_business_workspaces, business_trial_days)
values
  ('ULTRA_MONTHLY', 'ULTRA', 'Ultra Monthly', 6.99,  28000,  30,  null, null, 100, true, true, 3, null, 0),
  ('ULTRA_YEARLY',  'ULTRA', 'Ultra Yearly',  59.99, 240000, 365, null, null, 100, true, true, 4, null, 0)
on conflict (code) do nothing;

-- ---------------------------------------------------------------------------
-- Paid = PRO or ULTRA. Rewrites the current definitions of every function that
-- still treats 'PRO' as the only paid tier (request, grant, admin list, …).
-- ---------------------------------------------------------------------------
do $$
declare
  f record;
  def text;
begin
  for f in
    select p.oid
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and (p.prosrc like '%tier = ''PRO''%' or p.prosrc like '%then ''PRO'' else ''FREE''%')
  loop
    def := pg_get_functiondef(f.oid);
    def := replace(def, 'tier = ''PRO''', 'tier in (''PRO'', ''ULTRA'')');
    -- Admin user list: show the real tier of an active plan.
    def := replace(def, 'then ''PRO'' else ''FREE''', 'then (select pl.tier from public.plans pl where pl.code = s.plan_code) else ''FREE''');
    execute def;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Business trial: counted from the business workspace's trial start. Existing
-- workspaces start their 90 days now, so nobody's trial is already over.
-- ---------------------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'workspaces' and column_name = 'trial_started_at'
  ) then
    alter table public.workspaces add column trial_started_at timestamptz not null default now();
  end if;
end $$;

-- Whether the owner's plan lets this workspace be changed, and why not.
--   reason: null (allowed) | 'TRIAL_ENDED' | 'PLAN_LIMIT'
create or replace function public.workspace_plan_access(p_workspace_id uuid, out writable boolean, out reason text, out trial_ends_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  w public.workspaces;
  p public.plans;
  business_rank integer;
begin
  writable := true;
  select * into w from public.workspaces where id = p_workspace_id;
  if not found or w.type <> 'BUSINESS' then
    return;
  end if;
  p := public.plan_of(w.user_id);
  -- 1 = the owner's first business workspace.
  select count(*) + 1 into business_rank
  from public.workspaces o
  where o.user_id = w.user_id and o.type = 'BUSINESS' and (o.created_at, o.id) < (w.created_at, w.id);
  if p.max_business_workspaces is not null and business_rank > p.max_business_workspaces then
    writable := false;
    reason := 'PLAN_LIMIT';
    return;
  end if;
  if p.tier = 'FREE' then
    trial_ends_at := w.trial_started_at + make_interval(days => p.business_trial_days);
    if now() >= trial_ends_at then
      writable := false;
      reason := 'TRIAL_ENDED';
    end if;
  end if;
end;
$$;
revoke all on function public.workspace_plan_access(uuid) from public, anon;
grant execute on function public.workspace_plan_access(uuid) to authenticated;

-- Every write check (RLS and RPCs) goes through here: role AND plan.
create or replace function public.can_write_workspace(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid()) and m.role in ('OWNER', 'MEMBER')
  ) and (public.workspace_plan_access(ws_id)).writable;
$$;

-- Plan access of each workspace the caller belongs to (for the app's notices).
create or replace function public.my_workspace_access()
returns table (workspace_id uuid, writable boolean, reason text, trial_ends_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select m.workspace_id, a.writable, a.reason, a.trial_ends_at
  from public.workspace_members m
  cross join lateral public.workspace_plan_access(m.workspace_id) a
  where m.user_id = (select auth.uid());
$$;
revoke all on function public.my_workspace_access() from public, anon;
grant execute on function public.my_workspace_access() to authenticated;

-- ---------------------------------------------------------------------------
-- One Personal workspace per user (one owned Family is enforced by
-- create_family_workspace); Business workspaces are limited by the plan
-- instead (create_business_workspace).
-- ---------------------------------------------------------------------------
alter table public.workspaces drop constraint if exists workspaces_user_id_type_key;
create unique index if not exists workspaces_one_personal_idx on public.workspaces (user_id) where type = 'PERSONAL';

-- ---------------------------------------------------------------------------
-- Ultra: add more business workspaces.
-- ---------------------------------------------------------------------------
create or replace function public.create_business_workspace(p_name text)
returns public.workspaces
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  owned integer;
  result public.workspaces;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select count(*) into owned from public.workspaces where user_id = uid and type = 'BUSINESS';
  if p.max_business_workspaces is not null and owned >= p.max_business_workspaces then
    raise exception 'plan_limit:business' using errcode = 'P0001', hint = p.max_business_workspaces::text;
  end if;
  insert into public.workspaces (user_id, name, type)
  values (uid, coalesce(nullif(left(btrim(p_name), 60), ''), 'អាជីវកម្ម'), 'BUSINESS')
  returning * into result;
  perform public.seed_default_categories(result.id, 'BUSINESS');
  return result;
end;
$$;
revoke all on function public.create_business_workspace(text) from public, anon;
grant execute on function public.create_business_workspace(text) to authenticated;

-- ---------------------------------------------------------------------------
-- my_plan: business allowance and the trial end of the first business.
-- ---------------------------------------------------------------------------
create or replace function public.my_plan()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  s public.subscriptions;
  used integer;
  first_business uuid;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select * into s from public.subscriptions where user_id = uid;
  select coalesce((select ai_queries from public.usage_counters where user_id = uid and month = public.current_ai_month()), 0) into used;
  select id into first_business from public.workspaces where user_id = uid and type = 'BUSINESS' order by created_at, id limit 1;
  return jsonb_build_object(
    'tier', p.tier,
    'plan_code', p.code,
    'period_end', case when p.tier <> 'FREE' then s.current_period_end end,
    'last_plan_code', s.plan_code,
    'last_period_end', s.current_period_end,
    'max_wallets', p.max_wallets,
    'max_family_members', p.max_family_members,
    'max_business_workspaces', p.max_business_workspaces,
    'business_trial_ends_at', case when p.tier = 'FREE' and first_business is not null then (public.workspace_plan_access(first_business)).trial_ends_at end,
    'ai_queries_per_month', p.ai_queries_per_month,
    'ai_queries_used', used,
    'can_export', p.can_export,
    'can_credit_score', p.can_credit_score,
    'is_admin', public.is_admin()
  );
end;
$$;


-- ===========================================================================
-- 20261008000000_assets_gold.sql
-- ===========================================================================

-- Assets: gold & platinum holdings (Cambodian weight units, daily market
-- rates set by admins) and physical assets (land, house, vehicles…). Idempotent.
--
-- Weight is stored in ហ៊ុន (hun), the smallest everyday unit:
--   1 តម្លឹង (damlung) = 10 ជី (chi) = 100 ហ៊ុន = 37.5 g;  1 ហ៊ុន = 0.375 g.

create table if not exists public.gold_holdings (
  id                uuid primary key default gen_random_uuid(),
  workspace_id      uuid not null references public.workspaces (id) on delete cascade,
  name              text not null check (char_length(btrim(name)) between 1 and 80),
  -- GOLD_BAR = មាសគីឡូ (99.99%), GOLD_24K = មាសទឹក១០, GOLD_18K = មាសទឹក៨, PLATINUM = ប្លាទីន
  kind              text not null check (kind in ('GOLD_BAR', 'GOLD_24K', 'GOLD_18K', 'PLATINUM')),
  weight_hun        numeric(12, 2) not null check (weight_hun > 0 and weight_hun <= 1000000),
  purchase_date     date,
  purchase_price    numeric(18, 2) check (purchase_price is null or purchase_price >= 0),
  purchase_currency public.currency_code,
  note              text check (note is null or char_length(note) <= 300),
  created_by        uuid default auth.uid() references auth.users (id) on delete set null,
  created_at        timestamptz not null default now(),
  check ((purchase_price is null) = (purchase_currency is null))
);
create index if not exists gold_holdings_workspace_idx on public.gold_holdings (workspace_id);
alter table public.gold_holdings enable row level security;

-- Same rules as the rest of a workspace: members read; owners/members write
-- (which also respects the plan's read-only business workspaces).
drop policy if exists gold_holdings_select on public.gold_holdings;
create policy gold_holdings_select on public.gold_holdings
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists gold_holdings_insert on public.gold_holdings;
create policy gold_holdings_insert on public.gold_holdings
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists gold_holdings_update on public.gold_holdings;
create policy gold_holdings_update on public.gold_holdings
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists gold_holdings_delete on public.gold_holdings;
create policy gold_holdings_delete on public.gold_holdings
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.gold_holdings to authenticated;
grant update (name, kind, weight_hun, purchase_date, purchase_price, purchase_currency, note) on public.gold_holdings to authenticated;

-- ---------------------------------------------------------------------------
-- Market rates (app_settings "gold_rates"): USD per damlung for each kind,
-- e.g. {"GOLD_BAR": "2850", "GOLD_24K": "2800", "GOLD_18K": "2050", "PLATINUM": "1150"}.
-- Readable by every signed-in user (existing app_settings policy).
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_gold_rates(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
  k text;
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 500 then
    raise exception 'invalid rates' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(v) loop
    if k not in ('GOLD_BAR', 'GOLD_24K', 'GOLD_18K', 'PLATINUM') then
      raise exception 'unknown kind %', k using errcode = '22023';
    end if;
    if v ->> k is not null and not ((v ->> k) ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> k)::numeric between 1 and 1000000) then
      raise exception 'invalid rate for %', k using errcode = '22023';
    end if;
  end loop;
  insert into public.app_settings (key, value, updated_at) values ('gold_rates', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_gold_rates(jsonb) from public, anon;
grant execute on function public.admin_set_gold_rates(jsonb) to authenticated;

-- "Reset all data" also removes gold holdings (in place, keeping the rest of
-- the latest reset_my_data definition).
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('gold_holdings' in def) = 0 then
    def := replace(
      def,
      'delete from public.wallets_accounts where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.wallets_accounts where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Real estate, vehicles, machinery and other physical assets: an estimated
-- market value, optionally linked to the bank loan that financed it (net
-- equity = value − what is still owed on that loan).
-- ---------------------------------------------------------------------------
create table if not exists public.physical_assets (
  id              uuid primary key default gen_random_uuid(),
  workspace_id    uuid not null references public.workspaces (id) on delete cascade,
  kind            text not null check (kind in ('LAND', 'HOUSE', 'VEHICLE', 'MACHINERY', 'OTHER')),
  name            text not null check (char_length(btrim(name)) between 1 and 80),
  estimated_value numeric(18, 2) not null check (estimated_value >= 0),
  currency        public.currency_code not null,
  purchase_date   date,
  purchase_price  numeric(18, 2) check (purchase_price is null or purchase_price >= 0),
  debt_id         uuid,
  note            text check (note is null or char_length(note) <= 300),
  created_by      uuid default auth.uid() references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  -- The loan must be in the same workspace; deleting it just removes the link.
  foreign key (debt_id, workspace_id) references public.debts (id, workspace_id) on delete set null (debt_id)
);
create index if not exists physical_assets_workspace_idx on public.physical_assets (workspace_id);
alter table public.physical_assets enable row level security;

drop policy if exists physical_assets_select on public.physical_assets;
create policy physical_assets_select on public.physical_assets
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists physical_assets_insert on public.physical_assets;
create policy physical_assets_insert on public.physical_assets
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists physical_assets_update on public.physical_assets;
create policy physical_assets_update on public.physical_assets
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists physical_assets_delete on public.physical_assets;
create policy physical_assets_delete on public.physical_assets
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.physical_assets to authenticated;
grant update (kind, name, estimated_value, currency, purchase_date, purchase_price, debt_id, note) on public.physical_assets to authenticated;

do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('physical_assets' in def) = 0 then
    def := replace(
      def,
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.physical_assets where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;


-- ===========================================================================
-- 20261009000000_business_archive.sql
-- ===========================================================================

-- Closed businesses: archive (hidden, read-only, restorable) or delete
-- permanently. At least one active Business workspace always remains, and
-- archived ones don't count toward the plan's business allowance. Idempotent.

alter table public.workspaces add column if not exists archived_at timestamptz;

create or replace function public.workspace_plan_access(p_workspace_id uuid, out writable boolean, out reason text, out trial_ends_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  w public.workspaces;
  p public.plans;
  business_rank integer;
begin
  writable := true;
  select * into w from public.workspaces where id = p_workspace_id;
  if not found or w.type <> 'BUSINESS' then
    return;
  end if;
  if w.archived_at is not null then
    writable := false;
    reason := 'ARCHIVED';
    return;
  end if;
  p := public.plan_of(w.user_id);
  -- 1 = the owner's first active business workspace.
  select count(*) + 1 into business_rank
  from public.workspaces o
  where o.user_id = w.user_id and o.type = 'BUSINESS' and o.archived_at is null and (o.created_at, o.id) < (w.created_at, w.id);
  if p.max_business_workspaces is not null and business_rank > p.max_business_workspaces then
    writable := false;
    reason := 'PLAN_LIMIT';
    return;
  end if;
  if p.tier = 'FREE' then
    trial_ends_at := w.trial_started_at + make_interval(days => p.business_trial_days);
    if now() >= trial_ends_at then
      writable := false;
      reason := 'TRIAL_ENDED';
    end if;
  end if;
end;
$$;

create or replace function public.create_business_workspace(p_name text)
returns public.workspaces
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  owned integer;
  result public.workspaces;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select count(*) into owned from public.workspaces where user_id = uid and type = 'BUSINESS' and archived_at is null;
  if p.max_business_workspaces is not null and owned >= p.max_business_workspaces then
    raise exception 'plan_limit:business' using errcode = 'P0001', hint = p.max_business_workspaces::text;
  end if;
  insert into public.workspaces (user_id, name, type)
  values (uid, coalesce(nullif(left(btrim(p_name), 60), ''), 'អាជីវកម្ម'), 'BUSINESS')
  returning * into result;
  perform public.seed_default_categories(result.id, 'BUSINESS');
  return result;
end;
$$;

-- Owner only; never the last active business.
create or replace function public.set_business_archived(p_workspace_id uuid, p_archived boolean)
returns public.workspaces
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  result public.workspaces;
begin
  if not exists (select 1 from public.workspaces where id = p_workspace_id and user_id = uid and type = 'BUSINESS') then
    raise exception 'only the owner can archive this business' using errcode = '42501';
  end if;
  if p_archived and not exists (
    select 1 from public.workspaces
    where user_id = uid and type = 'BUSINESS' and archived_at is null and id <> p_workspace_id
  ) then
    raise exception 'last_business' using errcode = 'P0001';
  end if;
  update public.workspaces set archived_at = case when p_archived then coalesce(archived_at, now()) end
  where id = p_workspace_id
  returning * into result;
  return result;
end;
$$;
revoke all on function public.set_business_archived(uuid, boolean) from public, anon;
grant execute on function public.set_business_archived(uuid, boolean) to authenticated;

-- Deletes a business and everything in it. Owner only; never the last active business.
create or replace function public.delete_business_workspace(p_workspace_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
begin
  if not exists (select 1 from public.workspaces where id = p_workspace_id and user_id = uid and type = 'BUSINESS') then
    raise exception 'only the owner can delete this business' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.workspaces
    where user_id = uid and type = 'BUSINESS' and archived_at is null and id <> p_workspace_id
  ) then
    raise exception 'last_business' using errcode = 'P0001';
  end if;
  perform set_config('luysmart.system', 'on', true);
  -- Ledger first (cascades repayments), then debts: wallets are referenced
  -- with NO ACTION, which a single cascading delete would trip over.
  delete from public.transactions where workspace_id = p_workspace_id;
  delete from public.debts where workspace_id = p_workspace_id;
  delete from public.workspaces where id = p_workspace_id;
  perform set_config('luysmart.system', '', true);
end;
$$;
revoke all on function public.delete_business_workspace(uuid) from public, anon;
grant execute on function public.delete_business_workspace(uuid) to authenticated;


-- ===========================================================================
-- 20261010000000_investments.sql
-- ===========================================================================

-- Stocks (CSX and international) and crypto holdings, and daily market
-- prices set by admins. Idempotent.
--
-- A holding stores the quantity, the average buy price per unit and, when the
-- admin hasn't priced its symbol, the user's own latest price.

create table if not exists public.investment_holdings (
  id               uuid primary key default gen_random_uuid(),
  workspace_id     uuid not null references public.workspaces (id) on delete cascade,
  -- STOCK_CSX (Cambodia Securities Exchange), STOCK_INTL (e.g. AAPL), CRYPTO (e.g. BTC)
  market           text not null check (market in ('STOCK_CSX', 'STOCK_INTL', 'CRYPTO')),
  symbol           text not null check (symbol ~ '^[A-Z0-9.\-]{1,15}$'),
  name             text check (name is null or char_length(name) <= 80),
  quantity         numeric(28, 8) not null check (quantity > 0),
  avg_cost         numeric(24, 8) not null check (avg_cost >= 0),
  currency         public.currency_code not null,
  current_price    numeric(24, 8) check (current_price is null or current_price >= 0),
  price_updated_at timestamptz,
  created_by       uuid default auth.uid() references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  -- Crypto is quoted in US dollars.
  check (market <> 'CRYPTO' or currency = 'USD')
);
create index if not exists investment_holdings_workspace_idx on public.investment_holdings (workspace_id);
alter table public.investment_holdings enable row level security;

drop policy if exists investment_holdings_select on public.investment_holdings;
create policy investment_holdings_select on public.investment_holdings
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists investment_holdings_insert on public.investment_holdings;
create policy investment_holdings_insert on public.investment_holdings
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists investment_holdings_update on public.investment_holdings;
create policy investment_holdings_update on public.investment_holdings
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists investment_holdings_delete on public.investment_holdings;
create policy investment_holdings_delete on public.investment_holdings
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.investment_holdings to authenticated;
grant update (market, symbol, name, quantity, avg_cost, currency, current_price, price_updated_at) on public.investment_holdings to authenticated;

-- ---------------------------------------------------------------------------
-- Market prices (app_settings "market_prices"), keyed "<market>:<symbol>":
--   {"STOCK_CSX:ABC": "7020", "CRYPTO:BTC": "65000", "STOCK_INTL:AAPL": "190.5"}
-- CSX prices are in riel, the others in US dollars. Admin prices win over a
-- user's own price for the same symbol.
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_market_prices(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
  k text;
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 20000 then
    raise exception 'invalid prices' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(v) loop
    if k !~ '^(STOCK_CSX|STOCK_INTL|CRYPTO):[A-Z0-9.\-]{1,15}$' then
      raise exception 'invalid symbol %', k using errcode = '22023';
    end if;
    if v ->> k is null or not ((v ->> k) ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> k)::numeric between 0 and 1000000000) then
      raise exception 'invalid price for %', k using errcode = '22023';
    end if;
  end loop;
  insert into public.app_settings (key, value, updated_at) values ('market_prices', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_market_prices(jsonb) from public, anon;
grant execute on function public.admin_set_market_prices(jsonb) to authenticated;

-- "Reset all data" also removes investment holdings.
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('investment_holdings' in def) = 0 then
    def := replace(
      def,
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.investment_holdings where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;


-- ===========================================================================
-- 20261011000000_diamonds.sql
-- ===========================================================================

-- Diamonds (ពេជ្រ) in the jewelry section: Cambodian and GIA grading,
-- certificate, and the shop's buy-back deduction, from which the app works
-- out the liquid resale value used in net worth. Idempotent.

create table if not exists public.diamond_holdings (
  id              uuid primary key default gen_random_uuid(),
  workspace_id    uuid not null references public.workspaces (id) on delete cascade,
  name            text not null check (char_length(btrim(name)) between 1 and 80),
  form            text not null check (form in ('RING', 'NECKLACE', 'EARRINGS', 'BRACELET', 'LOOSE')),
  -- Size in លី = millimetres (diameter of a round stone), e.g. 5.4.
  size_li         numeric(5, 2) check (size_li is null or size_li between 0.5 and 50),
  carat           numeric(7, 3) check (carat is null or carat between 0.001 and 500),
  -- KH = Cambodian water scale (ទឹក 97–100), GIA = D…M
  color_scale     text check (color_scale in ('KH', 'GIA')),
  color           text check (color is null or color in ('97', '98', '99', '100', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M')),
  clarity         text check (clarity is null or clarity in ('FL', 'IF', 'VVS1', 'VVS2', 'VS1', 'VS2', 'SI1', 'SI2', 'I1')),
  cert_type       text not null default 'NONE' check (cert_type in ('GIA', 'HRD', 'IGI', 'STORE', 'NONE')),
  cert_number     text check (cert_number is null or char_length(cert_number) <= 60),
  store           text check (store is null or char_length(store) <= 80),
  purchase_date   date,
  purchase_price  numeric(18, 2) not null check (purchase_price >= 0),
  currency        public.currency_code not null default 'USD',
  -- Shop buy-back: % taken off the purchase price when selling back for cash (and when trading in).
  buyback_pct     numeric(5, 2) not null default 15 check (buyback_pct between 0 and 100),
  tradein_pct     numeric(5, 2) check (tradein_pct is null or tradein_pct between 0 and 100),
  note            text check (note is null or char_length(note) <= 300),
  created_by      uuid default auth.uid() references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  check ((color is null) or (color_scale = 'KH' and color in ('97', '98', '99', '100')) or (color_scale = 'GIA' and color !~ '^[0-9]'))
);
create index if not exists diamond_holdings_workspace_idx on public.diamond_holdings (workspace_id);
alter table public.diamond_holdings enable row level security;

drop policy if exists diamond_holdings_select on public.diamond_holdings;
create policy diamond_holdings_select on public.diamond_holdings
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists diamond_holdings_insert on public.diamond_holdings;
create policy diamond_holdings_insert on public.diamond_holdings
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists diamond_holdings_update on public.diamond_holdings;
create policy diamond_holdings_update on public.diamond_holdings
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists diamond_holdings_delete on public.diamond_holdings;
create policy diamond_holdings_delete on public.diamond_holdings
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.diamond_holdings to authenticated;
grant update (name, form, size_li, carat, color_scale, color, clarity, cert_type, cert_number, store, purchase_date, purchase_price, currency, buyback_pct, tradein_pct, note)
  on public.diamond_holdings to authenticated;

do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('diamond_holdings' in def) = 0 then
    def := replace(
      def,
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.diamond_holdings where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;


-- ===========================================================================
-- 20261012000000_platinum_grades.sql
-- ===========================================================================

-- Platinum / white gold (ប្លាទីន) grades and the jewelry type of gold items.
-- Idempotent.
--   grade (PLATINUM only): P75 = ទឹក 75 (18K / 750), P70 = ទឹក 70,
--   P585 = ទឹក 58.5 (14K / 585), PT950, PT900
--   jewelry_type: ring, necklace, bracelet, earrings, pendant, bar, other

alter table public.gold_holdings add column if not exists grade text;
alter table public.gold_holdings add column if not exists jewelry_type text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'gold_holdings_grade_check') then
    alter table public.gold_holdings add constraint gold_holdings_grade_check
      check (grade is null or (kind = 'PLATINUM' and grade in ('P75', 'P70', 'P585', 'PT950', 'PT900')));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'gold_holdings_jewelry_type_check') then
    alter table public.gold_holdings add constraint gold_holdings_jewelry_type_check
      check (jewelry_type is null or jewelry_type in ('RING', 'NECKLACE', 'BRACELET', 'EARRINGS', 'PENDANT', 'BAR', 'OTHER'));
  end if;
end $$;

grant update (grade, jewelry_type) on public.gold_holdings to authenticated;

-- Rates may now also be set per platinum grade (USD per damlung).
create or replace function public.admin_set_gold_rates(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
  k text;
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 1000 then
    raise exception 'invalid rates' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(v) loop
    if k not in ('GOLD_BAR', 'GOLD_24K', 'GOLD_18K', 'PLATINUM',
                 'PLATINUM_P75', 'PLATINUM_P70', 'PLATINUM_P585', 'PLATINUM_PT950', 'PLATINUM_PT900') then
      raise exception 'unknown kind %', k using errcode = '22023';
    end if;
    if v ->> k is not null and not ((v ->> k) ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> k)::numeric between 1 and 1000000) then
      raise exception 'invalid rate for %', k using errcode = '22023';
    end if;
  end loop;
  insert into public.app_settings (key, value, updated_at) values ('gold_rates', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;


-- ===========================================================================
-- 20261013000000_active_sessions.sql
-- ===========================================================================

-- Active devices: list the caller's sign-in sessions (auth.sessions) and sign
-- them out remotely. A revoked session can't refresh its token, and it loses
-- access to workspace data at once (the membership checks below require the
-- caller's session to still exist). Idempotent.

-- True while the caller's session exists. Tokens without a session id (and
-- the service role) are not affected. If this database role can't read
-- auth.sessions, the check is a no-op rather than breaking every query.
do $$
begin
  if has_table_privilege('auth.sessions', 'select') then
    execute $f$
      create or replace function public.session_alive()
      returns boolean
      language sql
      stable
      security definer
      set search_path = ''
      as $body$
        select coalesce(auth.jwt() ->> 'session_id', '') = ''
            or exists (select 1 from auth.sessions s where s.id = (auth.jwt() ->> 'session_id')::uuid);
      $body$
    $f$;
  else
    raise warning 'auth.sessions is not readable: revoked sessions keep access until their token expires';
    execute $f$
      create or replace function public.session_alive()
      returns boolean
      language sql
      stable
      set search_path = ''
      as $body$ select true $body$
    $f$;
  end if;
end $$;
revoke all on function public.session_alive() from public, anon;
grant execute on function public.session_alive() to authenticated;

-- Workspace access (every financial table's RLS) also requires a live session.
create or replace function public.is_workspace_member(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.session_alive() and exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid())
  );
$$;

create or replace function public.can_write_workspace(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.session_alive() and exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid()) and m.role in ('OWNER', 'MEMBER')
  ) and (public.workspace_plan_access(ws_id)).writable;
$$;

-- The caller's sessions, current first, then by last activity.
create or replace function public.my_sessions()
returns table (id uuid, created_at timestamptz, last_active_at timestamptz, user_agent text, ip text, aal text, is_current boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select s.id,
         s.created_at,
         greatest(s.created_at, s.updated_at, s.refreshed_at at time zone 'UTC') as last_active_at,
         s.user_agent,
         host(s.ip) as ip,
         s.aal::text,
         s.id::text = coalesce(auth.jwt() ->> 'session_id', '') as is_current
  from auth.sessions s
  where s.user_id = (select auth.uid())
    and (s.not_after is null or s.not_after > now())
  order by (s.id::text = coalesce(auth.jwt() ->> 'session_id', '')) desc,
           greatest(s.created_at, s.updated_at, s.refreshed_at at time zone 'UTC') desc;
$$;
revoke all on function public.my_sessions() from public, anon;
grant execute on function public.my_sessions() to authenticated;

-- Sign out one of the caller's other sessions.
create or replace function public.revoke_session(p_session_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_session_id::text = coalesce(auth.jwt() ->> 'session_id', '') then
    raise exception 'use sign out for the current session' using errcode = '22023';
  end if;
  delete from auth.sessions where id = p_session_id and user_id = uid;
  if not found then
    raise exception 'session not found' using errcode = 'P0002';
  end if;
end;
$$;
revoke all on function public.revoke_session(uuid) from public, anon;
grant execute on function public.revoke_session(uuid) to authenticated;

-- Sign out every session of the caller except this one; returns how many.
create or replace function public.revoke_other_sessions()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  n integer;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  delete from auth.sessions
  where user_id = uid and id::text <> coalesce(auth.jwt() ->> 'session_id', '');
  get diagnostics n = row_count;
  return n;
end;
$$;
revoke all on function public.revoke_other_sessions() from public, anon;
grant execute on function public.revoke_other_sessions() to authenticated;


-- ===========================================================================
-- 20261014000000_mfa_login_alerts.sql
-- ===========================================================================

-- Two-factor authentication (Supabase MFA / TOTP) enforced in the database,
-- an admin "reset 2FA" for account recovery, and Telegram alerts for new
-- sign-ins. Idempotent.

-- ---------------------------------------------------------------------------
-- Security events (sign-ins, 2FA resets): the user reads their own.
-- ---------------------------------------------------------------------------
create table if not exists public.security_events (
  id          bigint generated always as identity primary key,
  user_id     uuid not null references auth.users (id) on delete cascade,
  kind        text not null check (kind in ('LOGIN', 'MFA_RESET')),
  session_id  uuid,
  user_agent  text,
  ip          text,
  actor       uuid references auth.users (id) on delete set null,
  note        text check (note is null or char_length(note) <= 300),
  created_at  timestamptz not null default now()
);
create unique index if not exists security_events_login_once on public.security_events (user_id, session_id) where kind = 'LOGIN';
create index if not exists security_events_user_idx on public.security_events (user_id, created_at desc);
alter table public.security_events enable row level security;
drop policy if exists security_events_select_own on public.security_events;
create policy security_events_select_own on public.security_events
  for select to authenticated using (user_id = (select auth.uid()));
grant select on public.security_events to authenticated;

-- ---------------------------------------------------------------------------
-- 2FA gate: a user with a verified authenticator must be signed in at aal2
-- (password/Google + 6-digit code). Users without 2FA are unaffected.
-- ---------------------------------------------------------------------------
do $$
begin
  if has_table_privilege('auth.mfa_factors', 'select') then
    execute $f$
      create or replace function public.mfa_ok()
      returns boolean
      language sql
      stable
      security definer
      set search_path = ''
      as $body$
        select coalesce(auth.jwt() ->> 'aal', '') = 'aal2'
            or not exists (
              select 1 from auth.mfa_factors f
              where f.user_id = (select auth.uid()) and f.status = 'verified'
            );
      $body$
    $f$;
  else
    raise warning 'auth.mfa_factors is not readable: 2FA is not enforced in the database';
    execute $f$
      create or replace function public.mfa_ok()
      returns boolean
      language sql
      stable
      set search_path = ''
      as $body$ select true $body$
    $f$;
  end if;
end $$;
revoke all on function public.mfa_ok() from public, anon;
grant execute on function public.mfa_ok() to authenticated;

-- Live session and, when 2FA is on, a verified code.
create or replace function public.access_ok()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.session_alive() and public.mfa_ok();
$$;
revoke all on function public.access_ok() from public, anon;
grant execute on function public.access_ok() to authenticated;

create or replace function public.is_workspace_member(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.access_ok() and exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid())
  );
$$;

create or replace function public.can_write_workspace(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.access_ok() and exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid()) and m.role in ('OWNER', 'MEMBER')
  ) and (public.workspace_plan_access(ws_id)).writable;
$$;

-- Every table with RLS also gets a restrictive policy, so own-only tables
-- (profiles, settings, payments…) are covered too. (select …) makes it run
-- once per query, not per row. Later migrations that add tables end with
-- "select public.apply_security_gate();".
create or replace function public.apply_security_gate()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  t record;
  n integer := 0;
begin
  for t in
    select c.relname
    from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
    where ns.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity
  loop
    execute format('drop policy if exists security_gate on public.%I', t.relname);
    execute format(
      'create policy security_gate on public.%I as restrictive for all to authenticated using ((select public.access_ok())) with check ((select public.access_ok()))',
      t.relname
    );
    n := n + 1;
  end loop;
  return n;
end;
$$;
revoke all on function public.apply_security_gate() from public, anon, authenticated;
select public.apply_security_gate();

-- Admin tools also require the admin's own 2FA when they have it.
create or replace function public.require_admin()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() or not public.access_ok() then
    raise exception 'admin only' using errcode = '42501';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin: 2FA status and emergency reset (after verifying the person through
-- support). The reset removes the authenticators and signs every device out.
-- ---------------------------------------------------------------------------
create or replace function public.admin_user_security(p_user_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return jsonb_build_object(
    'mfa', (select count(*) from auth.mfa_factors f where f.user_id = p_user_id and f.status = 'verified'),
    'sessions', (select count(*) from auth.sessions s where s.user_id = p_user_id),
    'last_reset', (select max(created_at) from public.security_events e where e.user_id = p_user_id and e.kind = 'MFA_RESET')
  );
end;
$$;
revoke all on function public.admin_user_security(uuid) from public, anon;
grant execute on function public.admin_user_security(uuid) to authenticated;

create or replace function public.admin_reset_mfa(p_user_id uuid, p_note text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  if p_user_id = (select auth.uid()) then
    raise exception 'ask another admin to reset your own 2FA' using errcode = '42501';
  end if;
  delete from auth.mfa_factors where user_id = p_user_id;
  delete from auth.sessions where user_id = p_user_id;
  insert into public.security_events (user_id, kind, actor, note)
  values (p_user_id, 'MFA_RESET', (select auth.uid()), left(nullif(btrim(coalesce(p_note, '')), ''), 300));
end;
$$;
revoke all on function public.admin_reset_mfa(uuid, text) from public, anon;
grant execute on function public.admin_reset_mfa(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- New sign-in alerts on Telegram (the user's own bot from Settings), once per
-- session. Device and IP come from auth.sessions, not from the browser.
-- ---------------------------------------------------------------------------
create or replace function public.record_login(p_user_id uuid, p_session_id uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  s record;
  ts record;
  device text;
  inserted integer;
begin
  if p_user_id is null or p_session_id is null then
    return false;
  end if;
  select user_agent, host(ip) as ip into s from auth.sessions where id = p_session_id and user_id = p_user_id;
  if not found then
    return false;
  end if;
  insert into public.security_events (user_id, kind, session_id, user_agent, ip)
  values (p_user_id, 'LOGIN', p_session_id, left(s.user_agent, 400), s.ip)
  on conflict do nothing;
  get diagnostics inserted = row_count;
  if inserted = 0 then
    return false;
  end if;

  select bot_token, chat_id, language into ts from public.telegram_settings where user_id = p_user_id and enabled;
  if found then
    device := case
      when s.user_agent ~ 'iPhone' then 'iPhone'
      when s.user_agent ~ 'iPad' then 'iPad'
      when s.user_agent ~ 'Android' then 'Android'
      when s.user_agent ~ 'Windows' then 'Windows'
      when s.user_agent ~ 'Mac OS X|Macintosh' then 'Mac'
      when s.user_agent ~ 'Linux' then 'Linux'
      else '?'
    end || case
      when s.user_agent ~ 'Edg/' then ' · Edge'
      when s.user_agent ~ 'SamsungBrowser' then ' · Samsung Internet'
      when s.user_agent ~ 'Firefox|FxiOS' then ' · Firefox'
      when s.user_agent ~ 'CriOS|Chrome/' then ' · Chrome'
      when s.user_agent ~ 'Safari/' then ' · Safari'
      else ''
    end;
    perform net.http_post(
      url := 'https://api.telegram.org/bot' || ts.bot_token || '/sendMessage',
      body := jsonb_build_object(
        'chat_id', ts.chat_id,
        'parse_mode', 'HTML',
        'text', case when ts.language = 'en' then
            '🔐 <b>New sign-in to your account</b>' || E'\n📱 ' || device || E'\n🌐 IP: ' || coalesce(s.ip, '?')
            || E'\n🕒 ' || to_char(now() at time zone 'Asia/Phnom_Penh', 'DD/MM/YYYY HH24:MI')
            || E'\n\nNot you? Open Settings › Security › Active devices, sign it out and change your password.'
          else
            '🔐 <b>សកម្មភាពចូលថ្មីពីឧបករណ៍ថ្មី</b>' || E'\n📱 ' || device || E'\n🌐 IP: ' || coalesce(s.ip, '?')
            || E'\n🕒 ' || to_char(now() at time zone 'Asia/Phnom_Penh', 'DD/MM/YYYY HH24:MI')
            || E'\n\nមិនមែនអ្នក? ចូល ការកំណត់ › សុវត្ថិភាព › ឧបករណ៍កំពុងដំណើរការ ហើយចាកចេញ រួចប្តូរពាក្យសម្ងាត់។'
          end || E'\n\n— លុយឆ្លាត · LuyChlat'
      ),
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  end if;
  return true;
end;
$$;
revoke all on function public.record_login(uuid, uuid) from public, anon, authenticated;

-- Called by the app when it opens (the caller's own current session only).
create or replace function public.note_login()
returns boolean
language sql
security definer
set search_path = ''
as $$
  select public.record_login((select auth.uid()), nullif(auth.jwt() ->> 'session_id', '')::uuid);
$$;
revoke all on function public.note_login() from public, anon;
grant execute on function public.note_login() to authenticated;

-- Optional Supabase Auth hook (Authentication › Hooks › Customize Access
-- Token → public.custom_access_token_hook): records the sign-in server-side
-- even when the app isn't opened. Claims are returned unchanged.
create or replace function public.custom_access_token_hook(event jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  begin
    perform public.record_login((event ->> 'user_id')::uuid, nullif(event -> 'claims' ->> 'session_id', '')::uuid);
  exception when others then
    -- Never block a sign-in because of an alert.
    null;
  end;
  return event;
end;
$$;
revoke all on function public.custom_access_token_hook(jsonb) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'supabase_auth_admin') then
    execute 'grant execute on function public.custom_access_token_hook(jsonb) to supabase_auth_admin';
  end if;
end $$;


-- ===========================================================================
-- 20261015000000_free_statement_import.sql
-- ===========================================================================

-- One free bank statement import per account (onboarding hook); after that,
-- statement import stays a PRO feature.
--
-- The credit is kept apart from statement_imports so undoing an import (which
-- deletes it) or resetting data doesn't hand out another free one. Users can
-- read their own row; only import_statement (security definer) writes it, in
-- the same transaction as the import, so a failed import uses no credit.

create table if not exists public.statement_import_credits (
  user_id  uuid primary key references auth.users (id) on delete cascade,
  used_at  timestamptz not null default now()
);

alter table public.statement_import_credits enable row level security;

drop policy if exists statement_import_credits_select on public.statement_import_credits;
create policy statement_import_credits_select on public.statement_import_credits
  for select to authenticated using (user_id = (select auth.uid()));

revoke all on public.statement_import_credits from anon;
revoke insert, update, delete on public.statement_import_credits from authenticated;
grant select on public.statement_import_credits to authenticated;

-- import_statement: FREE users may import once.
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.import_statement(uuid, jsonb, jsonb, boolean)'::regprocedure);
  if position('statement_import_credits' in def) = 0 then
    def := replace(
      def,
      $old$  if public.plan_code_of(uid) = 'FREE' then
    raise exception 'plan_required' using errcode = 'P0001';
  end if;$old$,
      $new$  if public.plan_code_of(uid) = 'FREE' then
    -- The one free import: claimed atomically, refused once used.
    insert into public.statement_import_credits (user_id) values (uid) on conflict (user_id) do nothing;
    if not found then
      raise exception 'plan_required' using errcode = 'P0001';
    end if;
  end if;$new$
    );
    if position('statement_import_credits' in def) = 0 then
      raise exception 'import_statement: plan check not found, free import not applied';
    end if;
    execute def;
  end if;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261016000000_credit_cards_debt_phase_a.sql
-- ===========================================================================

-- Phase A: credit-card wallets, card due-date alerts, Qard Hasan / doubtful
-- debts, debt photos (PRO), the Zakat "subtract debts I owe" switch and the
-- user's own KHQR image for payment reminders.

-- ---------------------------------------------------------------------------
-- Credit cards: a wallet whose balance is what you owe (negative). Spending
-- on it is an ordinary expense; paying the bill is a transfer into it, so it
-- is never counted twice.
-- ---------------------------------------------------------------------------
alter table public.wallets_accounts add column if not exists kind text not null default 'STANDARD';
alter table public.wallets_accounts add column if not exists credit_limit numeric(18, 2);
alter table public.wallets_accounts add column if not exists statement_day smallint;
alter table public.wallets_accounts add column if not exists due_day smallint;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'wallets_kind_check') then
    alter table public.wallets_accounts add constraint wallets_kind_check check (kind in ('STANDARD', 'CREDIT_CARD'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'wallets_credit_card_check') then
    alter table public.wallets_accounts add constraint wallets_credit_card_check check (
      (kind = 'STANDARD' and credit_limit is null and statement_day is null and due_day is null)
      or (kind = 'CREDIT_CARD' and credit_limit > 0 and statement_day between 1 and 31 and due_day between 1 and 31 and goal_target is null)
    );
  end if;
end $$;

grant update (kind, credit_limit, statement_day, due_day) on public.wallets_accounts to authenticated;

-- Transfers may take a card below zero, down to minus its limit (a cash
-- advance or a transfer out); other wallets still stop at zero.
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.adjust_wallet_balances(public.transactions, integer)'::regprocedure);
  if position('CREDIT_CARD' in def) = 0 then
    def := replace(
      def,
      'select 1 from public.wallets_accounts where id = t.wallet_id and balance < 0',
      'select 1 from public.wallets_accounts where id = t.wallet_id
      and balance < case when kind = ''CREDIT_CARD'' then -credit_limit else 0 end'
    );
    if position('CREDIT_CARD' in def) = 0 then
      raise exception 'adjust_wallet_balances: balance check not found';
    end if;
    execute def;
  end if;
end $$;

-- Next payment due date of a card, on or after p_today. The bill closes on
-- statement_day; it is due on due_day of the same month when due_day comes
-- later, else of the next month. Days past a month's end use its last day.
create or replace function public.card_day(p_year integer, p_month integer, p_day integer)
returns date
language sql
immutable
set search_path = ''
as $$
  -- p_month may run past 12 or below 1 (next / previous year).
  select make_date(y, m, least(p_day, extract(day from (make_date(y, m, 1) + interval '1 month - 1 day'))::integer))
  from (
    select p_year + floor((p_month - 1) / 12.0)::integer as y,
           (((p_month - 1) % 12) + 12) % 12 + 1 as m
  ) s
$$;

create or replace function public.card_next_due(p_statement_day integer, p_due_day integer, p_today date)
returns date
language plpgsql
immutable
set search_path = ''
as $$
declare
  y integer := extract(year from p_today)::integer;
  m integer := extract(month from p_today)::integer;
  k integer;
  stmt date;
  due date;
begin
  -- Statements from last month onwards; the first due date not yet past.
  for k in -1..2 loop
    stmt := public.card_day(y, m + k, p_statement_day);
    due := public.card_day(
      extract(year from stmt)::integer,
      extract(month from stmt)::integer + case when p_due_day > p_statement_day then 0 else 1 end,
      p_due_day
    );
    if due >= p_today then
      return due;
    end if;
  end loop;
  return null;
end;
$$;

-- Card alerts reuse public.notifications: keyed by wallet + due date + stage.
alter table public.notifications add column if not exists wallet_id uuid references public.wallets_accounts (id) on delete cascade;
create unique index if not exists notifications_wallet_alert_unique on public.notifications (wallet_id, alert_key) where wallet_id is not null;

create or replace function public.run_card_alerts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'Asia/Phnom_Penh')::date;
  r record;
  due date;
  stage text;
  lang text;
  title text;
  body text;
  safe_name text;
  new_id uuid;
  sent integer := 0;
begin
  for r in
    select w.*, ws.user_id, ts.bot_token, ts.chat_id, ts.enabled as tg_enabled, ts.language as tg_language
    from public.wallets_accounts w
    join public.workspaces ws on ws.id = w.workspace_id
    left join public.telegram_settings ts on ts.user_id = ws.user_id
    where w.kind = 'CREDIT_CARD' and w.archived_at is null and w.balance < 0
  loop
    due := public.card_next_due(r.statement_day, r.due_day, today);
    continue when due is null;
    stage := case due - today when 3 then 'D3' when 0 then 'D0' else null end;
    continue when stage is null;

    lang := coalesce(r.tg_language, 'km');
    safe_name := replace(replace(replace(r.name, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
    if lang = 'km' then
      title := case stage when 'D0' then '🔔 ប័ណ្ណឥណទានដល់ថ្ងៃបង់ថ្ងៃនេះ' else '🔔 ប័ណ្ណឥណទានជិតដល់ថ្ងៃបង់ (៣ ថ្ងៃទៀត)' end;
      body := 'កាបូបប័ណ្ណឥណទាន ' || safe_name || ' មានបំណុលត្រូវសង ' || public.format_money_text(-r.balance, r.currency)
        || ' ដល់ថ្ងៃកំណត់នៅថ្ងៃទី ' || to_char(due, 'DD/MM/YYYY')
        || '! សូមបង់ផ្ដាច់ឱ្យបានទាន់ពេល ដើម្បីជៀសវាងការប្រាក់ធនាគារ។';
    else
      title := case stage when 'D0' then '🔔 Credit card payment due today' else '🔔 Credit card payment due in 3 days' end;
      body := safe_name || ' has ' || public.format_money_text(-r.balance, r.currency) || ' to pay by '
        || to_char(due, 'DD/MM/YYYY') || '. Pay it in full on time to avoid bank interest.';
    end if;

    new_id := null;
    insert into public.notifications (workspace_id, wallet_id, title, message, type, alert_key, scheduled_at)
    values (r.workspace_id, r.id, title, body, 'DUE_DATE', 'CC:' || due::text || ':' || stage, now())
    on conflict (wallet_id, alert_key) where wallet_id is not null do nothing
    returning id into new_id;

    if new_id is not null and r.bot_token is not null and r.tg_enabled then
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || r.bot_token || '/sendMessage',
        body := jsonb_build_object('chat_id', r.chat_id, 'parse_mode', 'HTML',
          'text', '<b>' || title || E'</b>\n' || body || E'\n\n— លុយឆ្លាត · LuyChlat'),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
      sent := sent + 1;
    end if;
  end loop;
  return sent;
end;
$$;
revoke all on function public.run_card_alerts() from public, anon, authenticated;

-- Same daily slot as the debt alerts (08:00 Phnom Penh), when pg_cron is there.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('luychlat-card-alerts', '5 1 * * *', 'select public.run_card_alerts()');
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Debts: Qard Hasan (interest-free loan), doubtful receivables (left out of
-- Zakat until repaid), and up to two photos (contract, IOU, receipt). Photos
-- are a PRO feature.
-- ---------------------------------------------------------------------------
alter table public.debts add column if not exists qard_hasan boolean not null default false;
alter table public.debts add column if not exists doubtful boolean not null default false;
alter table public.debts add column if not exists attachment_paths text[] not null default '{}';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'debts_qard_hasan_check') then
    alter table public.debts add constraint debts_qard_hasan_check check (not qard_hasan or coalesce(interest_rate, 0) = 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'debts_attachments_check') then
    alter table public.debts add constraint debts_attachments_check check (cardinality(attachment_paths) <= 2);
  end if;
end $$;

grant update (qard_hasan, doubtful, attachment_paths) on public.debts to authenticated;

create or replace function public.guard_debt_attachments()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p text;
begin
  if uid is null then
    return new;
  end if;
  -- Only new photos are checked: removing one is always allowed.
  if tg_op = 'UPDATE' and new.attachment_paths <@ old.attachment_paths then
    return new;
  end if;
  if cardinality(new.attachment_paths) = 0 then
    return new;
  end if;
  if public.plan_code_of(uid) = 'FREE' then
    raise exception 'plan_required' using errcode = 'P0001';
  end if;
  foreach p in array new.attachment_paths loop
    if tg_op = 'INSERT' or not p = any (old.attachment_paths) then
      -- receipts/<uploader>/<file>: only your own uploads can be attached.
      if split_part(p, '/', 1) <> uid::text then
        raise exception 'attachment must be your own upload' using errcode = '42501';
      end if;
    end if;
  end loop;
  return new;
end;
$$;

drop trigger if exists debts_guard_attachments on public.debts;
create trigger debts_guard_attachments
  before insert or update of attachment_paths on public.debts
  for each row execute function public.guard_debt_attachments();

-- Family members of the workspace may view a debt's photos.
drop policy if exists receipts_select_debt on storage.objects;
create policy receipts_select_debt on storage.objects
  for select to authenticated
  using (
    bucket_id = 'receipts'
    and exists (
      select 1 from public.debts d
      where objects.name = any (d.attachment_paths) and public.is_workspace_member(d.workspace_id)
    )
  );

-- ---------------------------------------------------------------------------
-- Zakat: subtracting debts you owe is the Hanafi / AAOIFI approach; in the
-- Shafi'i school (most of Cambodia) debts don't reduce Zakat. Off by default.
-- ---------------------------------------------------------------------------
alter table public.islamic_settings add column if not exists subtract_debts boolean not null default false;

-- ---------------------------------------------------------------------------
-- The user's own KHQR image (profile-images bucket, user/<id>/…), attached to
-- payment reminders they send.
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists khqr_path text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_khqr_path_check') then
    alter table public.profiles add constraint profiles_khqr_path_check
      check (khqr_path is null or khqr_path like 'user/' || id::text || '/%');
  end if;
end $$;
grant update (khqr_path) on public.profiles to authenticated;

select public.apply_security_gate();


-- ===========================================================================
-- 20261017000000_debt_installments.sql
-- ===========================================================================

-- Phase B: installment schedules on debts (PRO). The app computes the schedule
-- (lib/loans/amortization.ts) and stores its shape here; with a schedule,
-- total_amount is the total to repay (principal + interest) and due_date the
-- last installment, so balances, status and net worth work unchanged. Payments
-- cover installments oldest first; reminders follow the next unpaid one.

alter table public.debts add column if not exists schedule_frequency text;
alter table public.debts add column if not exists schedule_count smallint;
alter table public.debts add column if not exists schedule_method text;
alter table public.debts add column if not exists schedule_first_due date;
-- Regular installment (the last one may differ by rounding) and the amount borrowed.
alter table public.debts add column if not exists schedule_payment numeric(18, 2);
alter table public.debts add column if not exists schedule_principal numeric(18, 2);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'debts_schedule_check') then
    -- num_nulls: a CHECK that evaluates to NULL passes, so test the nulls explicitly.
    alter table public.debts add constraint debts_schedule_check check (
      num_nulls(schedule_frequency, schedule_count, schedule_method, schedule_first_due, schedule_payment, schedule_principal) = 6
      or (
        num_nulls(schedule_frequency, schedule_count, schedule_method, schedule_first_due, schedule_payment, schedule_principal) = 0
        and schedule_frequency in ('MONTHLY', 'WEEKLY') and schedule_count between 1 and 600
        and schedule_method in ('FLAT', 'REDUCING') and schedule_payment > 0 and schedule_principal > 0
      )
    );
  end if;
end $$;

grant update (schedule_frequency, schedule_count, schedule_method, schedule_first_due, schedule_payment, schedule_principal)
  on public.debts to authenticated;

-- Phase A's card rule had the same NULL gap (a card without a limit passed):
-- replace it with explicit null counts.
alter table public.wallets_accounts drop constraint if exists wallets_credit_card_check;
alter table public.wallets_accounts add constraint wallets_credit_card_check check (
  (kind = 'STANDARD' and num_nulls(credit_limit, statement_day, due_day) = 3)
  or (kind = 'CREDIT_CARD' and num_nulls(credit_limit, statement_day, due_day) = 0 and goal_target is null
      and credit_limit > 0 and statement_day between 1 and 31 and due_day between 1 and 31)
);

-- Installment schedules are a PRO feature; removing one is always allowed.
create or replace function public.guard_debt_schedule()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
begin
  if uid is null or new.schedule_frequency is null then
    return new;
  end if;
  if tg_op = 'UPDATE'
    and (new.schedule_frequency, new.schedule_count, new.schedule_method, new.schedule_first_due, new.schedule_payment, new.schedule_principal)
      is not distinct from (old.schedule_frequency, old.schedule_count, old.schedule_method, old.schedule_first_due, old.schedule_payment, old.schedule_principal) then
    return new;
  end if;
  if public.plan_code_of(uid) = 'FREE' then
    raise exception 'plan_required' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists debts_guard_schedule on public.debts;
create trigger debts_guard_schedule
  before insert or update of schedule_frequency, schedule_count, schedule_method, schedule_first_due, schedule_payment, schedule_principal
  on public.debts
  for each row execute function public.guard_debt_schedule();

-- The next unpaid installment: its number (1-based), due date and amount still
-- owed on it. Null without a schedule or when everything is paid.
create or replace function public.debt_next_installment(d public.debts, out n integer, out due date, out amount numeric)
language plpgsql
stable
set search_path = ''
as $$
declare
  covered integer;
  step interval;
begin
  if d.schedule_frequency is null or d.paid_amount >= d.total_amount then
    return;
  end if;
  step := case d.schedule_frequency when 'WEEKLY' then interval '7 days' else interval '1 month' end;
  covered := least(floor((d.paid_amount + 0.001) / d.schedule_payment)::integer, d.schedule_count - 1);
  n := covered + 1;
  due := (d.schedule_first_due + step * covered)::date;
  -- What's left of this installment (the last one takes the remainder).
  amount := case
    when n = d.schedule_count then d.total_amount - d.paid_amount
    else least(d.schedule_payment * n - d.paid_amount, d.total_amount - d.paid_amount)
  end;
end;
$$;

-- Debt reminders: scheduled loans are reminded of each installment (keyed by
-- its date, so every month gets its own D7 / D3 / D0 / overdue alert).
create or replace function public.run_debt_alerts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'Asia/Phnom_Penh')::date;
  d public.debts;
  inst record;
  due date;
  key text;
  m record;
  stage text;
  days integer;
  txt record;
  extra text;
  new_id uuid;
  sent integer := 0;
begin
  -- Keep stored statuses fresh (OVERDUE depends on the date).
  update public.debts set paid_amount = paid_amount
  where status in ('ACTIVE', 'PARTIALLY_PAID') and due_date < current_date;

  for d in select * from public.debts where status <> 'SETTLED' and (due_date is not null or schedule_frequency is not null) loop
    inst := public.debt_next_installment(d);
    due := coalesce(inst.due, d.due_date);
    continue when due is null;
    stage := public.debt_alert_stage(due, today);
    continue when stage is null;
    days := due - today;
    key := case when inst.due is null then stage else stage || ':' || inst.due::text end;

    -- In-app text is re-rendered in the viewer's language by the app.
    d.due_date := due;
    select * into txt from public.debt_alert_text(d, stage, days, 'km');
    extra := case when inst.n is null then '' else
      E'\n🧾 បង់រំលោះលើកទី ' || inst.n || '/' || d.schedule_count || ': ' || public.format_money_text(inst.amount, d.currency) end;
    new_id := null;
    insert into public.notifications (workspace_id, debt_id, title, message, type, alert_key, scheduled_at)
    values (d.workspace_id, d.id, txt.title, coalesce(txt.body, '') || coalesce(extra, ''), 'DUE_DATE', key, now())
    on conflict (debt_id, alert_key) do nothing
    returning id into new_id;
    continue when new_id is null;

    for m in
      select ts.bot_token, ts.chat_id, ts.language
      from public.workspace_members wm
      join public.telegram_settings ts on ts.user_id = wm.user_id
      where wm.workspace_id = d.workspace_id and ts.enabled
    loop
      select * into txt from public.debt_alert_text(d, stage, days, m.language);
      extra := case when inst.n is null then '' when m.language = 'km' then
          E'\n🧾 បង់រំលោះលើកទី ' || inst.n || '/' || d.schedule_count || ': ' || public.format_money_text(inst.amount, d.currency)
        else E'\n🧾 Installment ' || inst.n || '/' || d.schedule_count || ': ' || public.format_money_text(inst.amount, d.currency) end;
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || m.bot_token || '/sendMessage',
        body := jsonb_build_object(
          'chat_id', m.chat_id,
          'parse_mode', 'HTML',
          'text', '<b>' || txt.title || E'</b>\n' || txt.body || extra || E'\n\n— លុយឆ្លាត · LuyChlat'
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
      sent := sent + 1;
    end loop;
  end loop;
  return sent;
end;
$$;
revoke all on function public.run_debt_alerts() from public, anon, authenticated;

-- Card alerts reach every member of the workspace with Telegram on (as debt alerts do).
create or replace function public.run_card_alerts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'Asia/Phnom_Penh')::date;
  w public.wallets_accounts;
  m record;
  due date;
  stage text;
  title text;
  body text;
  safe_name text;
  new_id uuid;
  sent integer := 0;
begin
  for w in select * from public.wallets_accounts where kind = 'CREDIT_CARD' and archived_at is null and balance < 0 loop
    due := public.card_next_due(w.statement_day, w.due_day, today);
    continue when due is null;
    stage := case due - today when 3 then 'D3' when 0 then 'D0' else null end;
    continue when stage is null;
    safe_name := replace(replace(replace(w.name, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');

    new_id := null;
    insert into public.notifications (workspace_id, wallet_id, title, message, type, alert_key, scheduled_at)
    values (
      w.workspace_id, w.id,
      case stage when 'D0' then '🔔 ប័ណ្ណឥណទានដល់ថ្ងៃបង់ថ្ងៃនេះ' else '🔔 ប័ណ្ណឥណទានជិតដល់ថ្ងៃបង់ (៣ ថ្ងៃទៀត)' end,
      'កាបូបប័ណ្ណឥណទាន ' || w.name || ' មានបំណុលត្រូវសង ' || public.format_money_text(-w.balance, w.currency)
        || ' ដល់ថ្ងៃកំណត់នៅថ្ងៃទី ' || to_char(due, 'DD/MM/YYYY') || '! សូមបង់ផ្ដាច់ឱ្យបានទាន់ពេល ដើម្បីជៀសវាងការប្រាក់ធនាគារ។',
      'DUE_DATE', 'CC:' || due::text || ':' || stage, now()
    )
    on conflict (wallet_id, alert_key) where wallet_id is not null do nothing
    returning id into new_id;
    continue when new_id is null;

    for m in
      select ts.bot_token, ts.chat_id, ts.language
      from public.workspace_members wm
      join public.telegram_settings ts on ts.user_id = wm.user_id
      where wm.workspace_id = w.workspace_id and ts.enabled
    loop
      if coalesce(m.language, 'km') = 'km' then
        title := case stage when 'D0' then '🔔 ប័ណ្ណឥណទានដល់ថ្ងៃបង់ថ្ងៃនេះ' else '🔔 ប័ណ្ណឥណទានជិតដល់ថ្ងៃបង់ (៣ ថ្ងៃទៀត)' end;
        body := 'កាបូបប័ណ្ណឥណទាន ' || safe_name || ' មានបំណុលត្រូវសង ' || public.format_money_text(-w.balance, w.currency)
          || ' ដល់ថ្ងៃកំណត់នៅថ្ងៃទី ' || to_char(due, 'DD/MM/YYYY')
          || '! សូមបង់ផ្ដាច់ឱ្យបានទាន់ពេល ដើម្បីជៀសវាងការប្រាក់ធនាគារ។';
      else
        title := case stage when 'D0' then '🔔 Credit card payment due today' else '🔔 Credit card payment due in 3 days' end;
        body := safe_name || ' has ' || public.format_money_text(-w.balance, w.currency) || ' to pay by '
          || to_char(due, 'DD/MM/YYYY') || '. Pay it in full on time to avoid bank interest.';
      end if;
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || m.bot_token || '/sendMessage',
        body := jsonb_build_object('chat_id', m.chat_id, 'parse_mode', 'HTML',
          'text', '<b>' || title || E'</b>\n' || body || E'\n\n— លុយឆ្លាត · LuyChlat'),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
      sent := sent + 1;
    end loop;
  end loop;
  return sent;
end;
$$;
revoke all on function public.run_card_alerts() from public, anon, authenticated;

select public.apply_security_gate();


-- ===========================================================================
-- 20261018000000_place_photos.sql
-- ===========================================================================

-- Community places (mosques, surau, halal food): a photo per suggestion.
-- Private bucket place-photos, path <uploader id>/<file>. The uploader and
-- admins see it while the place waits for review; once an admin approves the
-- place, every signed-in user can. Places are shown on an OpenStreetMap map.

alter table public.islamic_places add column if not exists photo_path text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'islamic_places_photo_path_check') then
    alter table public.islamic_places add constraint islamic_places_photo_path_check
      check (photo_path is null or (char_length(photo_path) <= 200 and photo_path ~ '^[0-9a-f-]{36}/[A-Za-z0-9._-]+$'));
  end if;
end $$;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('place-photos', 'place-photos', false, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists place_photos_insert on storage.objects;
create policy place_photos_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'place-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists place_photos_select on storage.objects;
create policy place_photos_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'place-photos'
    and (
      (storage.foldername(name))[1] = (select auth.uid())::text
      or public.is_admin()
      or exists (select 1 from public.islamic_places p where p.photo_path = objects.name and p.approved)
    )
  );

drop policy if exists place_photos_delete on storage.objects;
create policy place_photos_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'place-photos' and ((storage.foldername(name))[1] = (select auth.uid())::text or public.is_admin()));

-- A suggestion may only point at the suggester's own upload (admins: any).
create or replace function public.guard_place_photo()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.photo_path is null or public.is_admin() then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.photo_path is not distinct from old.photo_path then
    return new;
  end if;
  if split_part(new.photo_path, '/', 1) <> coalesce((select auth.uid())::text, '') then
    raise exception 'photo must be your own upload' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists islamic_places_guard_photo on public.islamic_places;
create trigger islamic_places_guard_photo
  before insert or update of photo_path on public.islamic_places
  for each row execute function public.guard_place_photo();

select public.apply_security_gate();


-- ===========================================================================
-- 20261019000000_official_bot.sql
-- ===========================================================================

-- Phase C: the official LuyChlat Telegram bot (@LuyChlat_bot).
--
-- The bot runs on our server (TELEGRAM_BOT_TOKEN in its environment). The
-- server has no master database key: it calls only the bot_* functions below,
-- which check a key derived from the bot token. Only that key's SHA-256 is
-- stored here (bot_config), set once by an admin ("Activate bot" in /admin).
--
-- Linking: the app asks for a one-time code (create_telegram_link_code), the
-- user opens t.me/<bot>?start=<code>, and the bot links that chat to them.
-- Reminders: the server sends due-date notifications (debts, cards) and, if
-- the user turned it on, prayer times for their chosen province.

create table if not exists public.bot_config (
  id         smallint primary key default 1 check (id = 1),
  key_hash   text not null check (key_hash ~ '^[0-9a-f]{64}$'),
  username   text check (username is null or username ~ '^[A-Za-z0-9_]{5,32}$'),
  updated_at timestamptz not null default now()
);
alter table public.bot_config enable row level security;
revoke all on public.bot_config from anon, authenticated;

create table if not exists public.telegram_links (
  user_id         uuid primary key references auth.users (id) on delete cascade,
  chat_id         bigint not null unique,
  username        text check (username is null or char_length(username) <= 64),
  language        text not null default 'km' check (language in ('km', 'en')),
  debt_alerts     boolean not null default true,
  prayer_alerts   boolean not null default false,
  -- A province key from lib/prayer.ts PROVINCES (never GPS).
  prayer_province text check (prayer_province is null or prayer_province ~ '^[a-z_]{2,30}$'),
  linked_at       timestamptz not null default now()
);
alter table public.telegram_links enable row level security;
drop policy if exists telegram_links_select on public.telegram_links;
create policy telegram_links_select on public.telegram_links for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists telegram_links_update on public.telegram_links;
create policy telegram_links_update on public.telegram_links for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
drop policy if exists telegram_links_delete on public.telegram_links;
create policy telegram_links_delete on public.telegram_links for delete to authenticated using (user_id = (select auth.uid()));
revoke all on public.telegram_links from anon, authenticated;
grant select, delete on public.telegram_links to authenticated;
grant update (language, debt_alerts, prayer_alerts, prayer_province) on public.telegram_links to authenticated;

create table if not exists public.telegram_link_codes (
  code       text primary key check (code ~ '^[0-9a-f]{32}$'),
  user_id    uuid not null references auth.users (id) on delete cascade,
  expires_at timestamptz not null
);
alter table public.telegram_link_codes enable row level security;
revoke all on public.telegram_link_codes from anon, authenticated;

create table if not exists public.telegram_deliveries (
  notification_id uuid not null references public.notifications (id) on delete cascade,
  user_id         uuid not null references auth.users (id) on delete cascade,
  sent_at         timestamptz not null default now(),
  primary key (notification_id, user_id)
);
alter table public.telegram_deliveries enable row level security;
revoke all on public.telegram_deliveries from anon, authenticated;

create table if not exists public.telegram_prayer_sent (
  user_id uuid not null references auth.users (id) on delete cascade,
  day     date not null,
  prayer  text not null check (prayer in ('fajr', 'dhuhr', 'asr', 'maghrib', 'isha')),
  primary key (user_id, day, prayer)
);
alter table public.telegram_prayer_sent enable row level security;
revoke all on public.telegram_prayer_sent from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Key check: SHA-256 of the key the server derives from the bot token.
-- ---------------------------------------------------------------------------
create or replace function public.bot_key_ok(p_key text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_key is not null and char_length(p_key) between 32 and 128
    and exists (select 1 from public.bot_config c where c.key_hash = encode(sha256(convert_to(p_key, 'UTF8')), 'hex'))
$$;
revoke all on function public.bot_key_ok(text) from public, anon, authenticated;

create or replace function public.require_bot(p_key text)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.bot_key_ok(p_key) then
    raise exception 'bot not authorized' using errcode = '42501';
  end if;
end;
$$;
revoke all on function public.require_bot(text) from public, anon, authenticated;

-- Admin ("Activate bot"): store the key's hash and the bot's username.
create or replace function public.admin_set_bot(p_key_hash text, p_username text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  insert into public.bot_config (id, key_hash, username, updated_at) values (1, lower(p_key_hash), p_username, now())
  on conflict (id) do update set key_hash = excluded.key_hash, username = excluded.username, updated_at = now();
  insert into public.app_settings (key, value, updated_at) values ('telegram_bot', jsonb_build_object('username', p_username), now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_bot(text, text) from public, anon;
grant execute on function public.admin_set_bot(text, text) to authenticated;

-- App: a one-time code for t.me/<bot>?start=<code> (15 minutes).
create or replace function public.create_telegram_link_code()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  new_code text := replace(gen_random_uuid()::text, '-', '');
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  delete from public.telegram_link_codes where user_id = uid or expires_at < now();
  insert into public.telegram_link_codes (code, user_id, expires_at) values (new_code, uid, now() + interval '15 minutes');
  return new_code;
end;
$$;
revoke all on function public.create_telegram_link_code() from public, anon;
grant execute on function public.create_telegram_link_code() to authenticated;

-- ---------------------------------------------------------------------------
-- Bot (server) functions: each needs the bot key.
-- ---------------------------------------------------------------------------

-- /start <code>: link this chat to the code's user. Returns their display name.
create or replace function public.bot_link_chat(p_key text, p_code text, p_chat_id bigint, p_username text, p_language text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid;
  name text;
begin
  perform public.require_bot(p_key);
  delete from public.telegram_link_codes where code = lower(coalesce(p_code, '')) and expires_at >= now() returning user_id into uid;
  if uid is null then
    return jsonb_build_object('ok', false, 'reason', 'invalid_code');
  end if;
  -- One chat belongs to one account.
  delete from public.telegram_links where chat_id = p_chat_id and user_id <> uid;
  insert into public.telegram_links (user_id, chat_id, username, language)
  values (uid, p_chat_id, left(p_username, 64), case when p_language = 'en' then 'en' else 'km' end)
  on conflict (user_id) do update set chat_id = excluded.chat_id, username = excluded.username, linked_at = now();
  -- The official bot replaces a personal bot: no double messages.
  update public.telegram_settings set enabled = false where user_id = uid;
  select display_name into name from public.profiles where id = uid;
  return jsonb_build_object('ok', true, 'name', coalesce(name, ''));
end;
$$;

-- /stop: unlink this chat.
create or replace function public.bot_unlink_chat(p_key text, p_chat_id bigint)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  delete from public.telegram_links where chat_id = p_chat_id;
  return found;
end;
$$;

-- Due-date notifications (debts, installments, cards) from the last two days
-- not yet sent to each linked member of the workspace.
create or replace function public.bot_due_notifications(p_key text, p_limit integer default 100)
returns table (notification_id uuid, user_id uuid, chat_id bigint, language text, title text, message text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return query
    select n.id, l.user_id, l.chat_id, l.language, n.title, n.message
    from public.notifications n
    join public.workspace_members wm on wm.workspace_id = n.workspace_id
    join public.telegram_links l on l.user_id = wm.user_id and l.debt_alerts
    where n.type = 'DUE_DATE'
      and n.created_at > now() - interval '2 days'
      and not exists (select 1 from public.telegram_deliveries d where d.notification_id = n.id and d.user_id = l.user_id)
    order by n.created_at
    limit least(greatest(p_limit, 1), 500);
end;
$$;

create or replace function public.bot_mark_delivered(p_key text, p_notification_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  insert into public.telegram_deliveries (notification_id, user_id) values (p_notification_id, p_user_id) on conflict do nothing;
end;
$$;

-- People who want prayer-time messages, with their province.
create or replace function public.bot_prayer_subscribers(p_key text)
returns table (user_id uuid, chat_id bigint, language text, province text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return query
    select l.user_id, l.chat_id, l.language, coalesce(l.prayer_province, 'phnom_penh')
    from public.telegram_links l
    where l.prayer_alerts;
end;
$$;

-- Each prayer is announced once per person and day (true = this call claimed it).
create or replace function public.bot_claim_prayer(p_key text, p_user_id uuid, p_day date, p_prayer text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  claimed integer;
begin
  perform public.require_bot(p_key);
  insert into public.telegram_prayer_sent (user_id, day, prayer) values (p_user_id, p_day, p_prayer) on conflict do nothing;
  get diagnostics claimed = row_count;
  delete from public.telegram_prayer_sent where day < current_date - 7;
  return claimed > 0;
end;
$$;

-- The server's bot calls these without a user session: anon may execute, the key decides.
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.bot_link_chat(text, text, bigint, text, text)',
    'public.bot_unlink_chat(text, bigint)',
    'public.bot_due_notifications(text, integer)',
    'public.bot_mark_delivered(text, uuid, uuid)',
    'public.bot_prayer_subscribers(text)',
    'public.bot_claim_prayer(text, uuid, date, text)'
  ] loop
    execute format('revoke all on function %s from public', f);
    execute format('grant execute on function %s to anon, authenticated', f);
  end loop;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261020000000_bot_commands.sql
-- ===========================================================================

-- Phase C part 2: log expenses, income and debt payments by chatting with the
-- official bot (PRO, opt-in). The server parses the message and proposes an
-- action; nothing is written until the user presses ✅ on the confirmation card.
--
-- Telegram becomes a way to add records without the app's PIN or 2FA code, so
-- it is off until the user turns it on in Settings (commands_enabled). Every
-- check is done again when ✅ is pressed: link, opt-in, PRO, workspace write
-- access, and that the wallet / category / debt belong to that workspace.

alter table public.telegram_links add column if not exists commands_enabled boolean not null default false;
alter table public.telegram_links add column if not exists workspace_id uuid references public.workspaces (id) on delete set null;
grant update (commands_enabled, workspace_id) on public.telegram_links to authenticated;

-- The chosen workspace must be one the user may write to.
create or replace function public.guard_telegram_workspace()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.workspace_id is not null and new.workspace_id is distinct from old.workspace_id
     and not public.can_write_workspace(new.workspace_id) then
    raise exception 'workspace not writable' using errcode = '42501';
  end if;
  return new;
end;
$$;
drop trigger if exists telegram_links_guard_workspace on public.telegram_links;
create trigger telegram_links_guard_workspace
  before update of workspace_id on public.telegram_links
  for each row execute function public.guard_telegram_workspace();

create table if not exists public.telegram_pending (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  chat_id    bigint not null,
  action     jsonb not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '15 minutes'
);
create index if not exists telegram_pending_chat_idx on public.telegram_pending (chat_id);
alter table public.telegram_pending enable row level security;
revoke all on public.telegram_pending from anon, authenticated;

-- Run the rest of the transaction as this user (auth.uid() in checks and
-- triggers, created_by on new rows). Internal only.
create or replace function public.bot_act_as(p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform set_config('request.jwt.claim.sub', p_user::text, true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', p_user, 'role', 'authenticated', 'aal', 'aal2')::text, true);
end;
$$;
revoke all on function public.bot_act_as(uuid) from public, anon, authenticated;

-- The link for a chat, with the workspace the bot writes to (default: Personal).
create or replace function public.bot_link_for(p_chat_id bigint, out uid uuid, out ws uuid, out enabled boolean, out lang text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  select l.user_id, l.workspace_id, l.commands_enabled, l.language into uid, ws, enabled, lang
  from public.telegram_links l where l.chat_id = p_chat_id;
  if uid is not null and ws is null then
    select w.id into ws from public.workspaces w where w.user_id = uid and w.type = 'PERSONAL' limit 1;
  end if;
end;
$$;
revoke all on function public.bot_link_for(bigint) from public, anon, authenticated;

-- What the server needs to understand a message: wallets, categories, open debts.
create or replace function public.bot_context(p_key text, p_chat_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  link record;
  rate numeric;
  ws_type text;
begin
  perform public.require_bot(p_key);
  link := public.bot_link_for(p_chat_id);
  if link.uid is null then
    return jsonb_build_object('linked', false);
  end if;
  perform public.bot_act_as(link.uid);
  select w.type, coalesce(w.khr_per_usd, 4000) into ws_type, rate from public.workspaces w where w.id = link.ws;
  return jsonb_build_object(
    'linked', true,
    'pro', public.plan_code_of(link.uid) <> 'FREE',
    'enabled', link.enabled,
    'writable', link.ws is not null and public.can_write_workspace(link.ws),
    'language', link.lang,
    'workspace_type', ws_type,
    'rate', rate,
    'wallets', coalesce((
      select jsonb_agg(jsonb_build_object('id', w.id, 'name', w.name, 'currency', w.currency, 'icon', w.icon, 'kind', w.kind, 'balance', w.balance) order by w.sort_order)
      from public.wallets_accounts w
      where w.workspace_id = link.ws and w.archived_at is null and w.goal_target is null
        and (w.visibility = 'SHARED' or w.owner_id is null or w.owner_id = link.uid)
    ), '[]'::jsonb),
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'type', c.type, 'preset_key', c.preset_key))
      from public.categories c where c.workspace_id = link.ws
    ), '[]'::jsonb),
    'debts', coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'type', d.type, 'party_name', d.party_name, 'currency', d.currency, 'remaining', d.total_amount - d.paid_amount))
      from public.debts d where d.workspace_id = link.ws and d.status <> 'SETTLED'
    ), '[]'::jsonb)
  );
end;
$$;

-- Checks an action and keeps it until ✅ / ❌. Returns the pending id.
--   {kind: EXPENSE|INCOME, wallet_id, category_id?, amount, currency, note?}
--   {kind: REPAY, debt_id, wallet_id, amount, note?}
create or replace function public.bot_propose(p_key text, p_chat_id bigint, p_action jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  link record;
  kind text := p_action ->> 'kind';
  amount numeric := (p_action ->> 'amount')::numeric;
  new_id uuid;
begin
  perform public.require_bot(p_key);
  link := public.bot_link_for(p_chat_id);
  if link.uid is null then raise exception 'not_linked' using errcode = 'P0001'; end if;
  if not link.enabled then raise exception 'commands_off' using errcode = 'P0001'; end if;
  if public.plan_code_of(link.uid) = 'FREE' then raise exception 'plan_required' using errcode = 'P0001'; end if;
  if kind not in ('EXPENSE', 'INCOME', 'REPAY') or amount is null or amount <= 0 or amount > 1e12 then
    raise exception 'invalid_action' using errcode = '22023';
  end if;
  if not exists (select 1 from public.wallets_accounts w where w.id = (p_action ->> 'wallet_id')::uuid and w.workspace_id = link.ws and w.archived_at is null) then
    raise exception 'invalid_wallet' using errcode = '22023';
  end if;
  if kind = 'REPAY' then
    if not exists (select 1 from public.debts d where d.id = (p_action ->> 'debt_id')::uuid and d.workspace_id = link.ws and d.status <> 'SETTLED') then
      raise exception 'invalid_debt' using errcode = '22023';
    end if;
  else
    if (p_action ->> 'currency') not in ('USD', 'KHR') then raise exception 'invalid_action' using errcode = '22023'; end if;
    if (p_action ->> 'category_id') is not null and not exists (
      select 1 from public.categories c where c.id = (p_action ->> 'category_id')::uuid and c.workspace_id = link.ws and c.type::text = kind
    ) then
      raise exception 'invalid_category' using errcode = '22023';
    end if;
  end if;
  -- One open card per chat: a new message replaces the previous proposal.
  delete from public.telegram_pending where chat_id = p_chat_id or expires_at < now();
  insert into public.telegram_pending (user_id, chat_id, action) values (link.uid, p_chat_id, p_action || jsonb_build_object('workspace_id', link.ws))
  returning id into new_id;
  return new_id;
end;
$$;

-- ✅: write the record as the user, after checking everything again.
create or replace function public.bot_confirm(p_key text, p_chat_id bigint, p_pending_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  p public.telegram_pending;
  link record;
  a jsonb;
  ws uuid;
  w public.wallets_accounts;
  d public.debts;
  rate numeric;
  currency text;
  tx_type public.transaction_type;
begin
  perform public.require_bot(p_key);
  delete from public.telegram_pending where id = p_pending_id and chat_id = p_chat_id and expires_at >= now() returning * into p;
  if p.id is null then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  link := public.bot_link_for(p_chat_id);
  if link.uid is distinct from p.user_id or not link.enabled then raise exception 'commands_off' using errcode = 'P0001'; end if;
  if public.plan_code_of(p.user_id) = 'FREE' then raise exception 'plan_required' using errcode = 'P0001'; end if;
  a := p.action;
  ws := (a ->> 'workspace_id')::uuid;
  perform public.bot_act_as(p.user_id);
  if not public.can_write_workspace(ws) then raise exception 'not_writable' using errcode = '42501'; end if;

  select * into w from public.wallets_accounts where id = (a ->> 'wallet_id')::uuid and workspace_id = ws and archived_at is null;
  if w.id is null then raise exception 'invalid_wallet' using errcode = '22023'; end if;
  if w.visibility = 'PERSONAL' and w.owner_id is not null and w.owner_id <> p.user_id then raise exception 'invalid_wallet' using errcode = '42501'; end if;
  select coalesce(khr_per_usd, 4000) into rate from public.workspaces where id = ws;

  if a ->> 'kind' = 'REPAY' then
    select * into d from public.debts where id = (a ->> 'debt_id')::uuid and workspace_id = ws;
    if d.id is null then raise exception 'invalid_debt' using errcode = '22023'; end if;
    perform public.record_debt_repayment(d.id, w.id, (a ->> 'amount')::numeric, rate, now(), nullif(a ->> 'note', ''));
    select * into d from public.debts where id = d.id;
    select * into w from public.wallets_accounts where id = w.id;
    return jsonb_build_object('ok', true, 'kind', 'REPAY', 'wallet', w.name, 'balance', w.balance, 'wallet_currency', w.currency,
      'remaining', d.total_amount - d.paid_amount, 'debt_currency', d.currency, 'party', d.party_name);
  end if;

  currency := a ->> 'currency';
  tx_type := (a ->> 'kind')::public.transaction_type;
  if (a ->> 'category_id') is not null and not exists (
    select 1 from public.categories c where c.id = (a ->> 'category_id')::uuid and c.workspace_id = ws and c.type::text = a ->> 'kind'
  ) then
    raise exception 'invalid_category' using errcode = '22023';
  end if;
  insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date)
  values (ws, w.id, (a ->> 'category_id')::uuid, (a ->> 'amount')::numeric, currency::public.currency_code, tx_type,
          case when currency = w.currency::text then null else rate end, left(nullif(a ->> 'note', ''), 500), now());
  select * into w from public.wallets_accounts where id = w.id;
  return jsonb_build_object('ok', true, 'kind', a ->> 'kind', 'wallet', w.name, 'balance', w.balance, 'wallet_currency', w.currency);
end;
$$;

-- ❌: drop the proposal.
create or replace function public.bot_cancel(p_key text, p_chat_id bigint, p_pending_id uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  delete from public.telegram_pending where id = p_pending_id and chat_id = p_chat_id;
  return found;
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.bot_context(text, bigint)',
    'public.bot_propose(text, bigint, jsonb)',
    'public.bot_confirm(text, bigint, uuid)',
    'public.bot_cancel(text, bigint, uuid)'
  ] loop
    execute format('revoke all on function %s from public', f);
    execute format('grant execute on function %s to anon, authenticated', f);
  end loop;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261021000000_bot_multi_workspace.sql
-- ===========================================================================

-- ULTRA: log into any of your workspaces from one chat ("កត់ត្រាបានទាំងអស់").
-- With route_all on, the server routes each message by a workspace name or tag
-- in it ("DL សាំង 20$" → DL MEAT SUPPLY), defaulting to Personal, and the card
-- has buttons to switch the target before ✅. Every check is repeated on ✅:
-- still ULTRA, route_all still on, and write access to that workspace.

alter table public.telegram_links add column if not exists route_all boolean not null default false;
grant update (route_all) on public.telegram_links to authenticated;

-- Internal: the user's plan tier (FREE / PRO / ULTRA).
create or replace function public.bot_tier(p_user uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select p.tier from public.plans p where p.code = public.plan_code_of(p_user)), 'FREE');
$$;
revoke all on function public.bot_tier(uuid) from public, anon, authenticated;

-- Internal: one workspace's wallets, categories and open debts for the parser.
create or replace function public.bot_workspace_payload(p_ws uuid, p_user uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', w.id,
    'name', w.name,
    'type', w.type,
    'rate', coalesce(w.khr_per_usd, 4000),
    'wallets', coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name, 'currency', a.currency, 'icon', a.icon, 'kind', a.kind, 'balance', a.balance) order by a.sort_order)
      from public.wallets_accounts a
      where a.workspace_id = w.id and a.archived_at is null and a.goal_target is null
        and (a.visibility = 'SHARED' or a.owner_id is null or a.owner_id = p_user)
    ), '[]'::jsonb),
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'type', c.type, 'preset_key', c.preset_key))
      from public.categories c where c.workspace_id = w.id
    ), '[]'::jsonb),
    'debts', coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'type', d.type, 'party_name', d.party_name, 'currency', d.currency, 'remaining', d.total_amount - d.paid_amount))
      from public.debts d where d.workspace_id = w.id and d.status <> 'SETTLED'
    ), '[]'::jsonb)
  )
  from public.workspaces w where w.id = p_ws;
$$;
revoke all on function public.bot_workspace_payload(uuid, uuid) from public, anon, authenticated;

-- Internal: true when this chat may write to p_ws (its default workspace, or any
-- writable one with ULTRA + route_all). Call after bot_act_as.
create or replace function public.bot_ws_allowed(p_user uuid, p_default uuid, p_route_all boolean, p_ws uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_ws is not null
     and public.can_write_workspace(p_ws)
     and (p_ws = p_default or (p_route_all and public.bot_tier(p_user) = 'ULTRA'));
$$;
revoke all on function public.bot_ws_allowed(uuid, uuid, boolean, uuid) from public, anon, authenticated;

-- The link for a chat (bot_link_for plus route_all, which counts only on ULTRA). With routing the default is Personal.
create or replace function public.bot_chat_link(p_chat_id bigint, out uid uuid, out ws uuid, out enabled boolean, out lang text, out route_all boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  select l.user_id, l.workspace_id, l.commands_enabled, l.language, l.route_all into uid, ws, enabled, lang, route_all
  from public.telegram_links l where l.chat_id = p_chat_id;
  -- Routing is an ULTRA feature: after a downgrade the chat goes back to its one chosen workspace.
  route_all := coalesce(route_all, false) and uid is not null and public.bot_tier(uid) = 'ULTRA';
  if uid is not null and (ws is null or route_all) then
    select w.id into ws from public.workspaces w where w.user_id = uid and w.type = 'PERSONAL' limit 1;
  end if;
end;
$$;
revoke all on function public.bot_chat_link(bigint) from public, anon, authenticated;

create or replace function public.bot_context(p_key text, p_chat_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  link record;
  tier text;
  routing boolean;
  base jsonb;
begin
  perform public.require_bot(p_key);
  link := public.bot_chat_link(p_chat_id);
  if link.uid is null then
    return jsonb_build_object('linked', false);
  end if;
  perform public.bot_act_as(link.uid);
  tier := public.bot_tier(link.uid);
  routing := link.route_all and tier = 'ULTRA';
  base := coalesce(public.bot_workspace_payload(link.ws, link.uid), '{}'::jsonb);
  return jsonb_build_object(
    'linked', true,
    'pro', tier <> 'FREE',
    'ultra', tier = 'ULTRA',
    'route_all', routing,
    'enabled', link.enabled,
    'writable', link.ws is not null and public.can_write_workspace(link.ws),
    'language', link.lang,
    'workspace_id', link.ws,
    'workspace_type', base ->> 'type',
    'rate', coalesce((base ->> 'rate')::numeric, 4000),
    'wallets', coalesce(base -> 'wallets', '[]'::jsonb),
    'categories', coalesce(base -> 'categories', '[]'::jsonb),
    'debts', coalesce(base -> 'debts', '[]'::jsonb),
    -- Every workspace this chat can log into: Personal first, then by type and age.
    'workspaces', case when routing then coalesce((
      select jsonb_agg(public.bot_workspace_payload(w.id, link.uid) order by (w.id = link.ws) desc, w.type, w.created_at)
      from public.workspaces w
      join public.workspace_members m on m.workspace_id = w.id and m.user_id = link.uid and m.role in ('OWNER', 'MEMBER')
      where w.archived_at is null and public.can_write_workspace(w.id)
    ), '[]'::jsonb) else jsonb_build_array(base) end
  );
end;
$$;

-- action.workspace_id picks the target (ULTRA + route_all); otherwise the chat's workspace.
create or replace function public.bot_propose(p_key text, p_chat_id bigint, p_action jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  link record;
  kind text := p_action ->> 'kind';
  amount numeric := (p_action ->> 'amount')::numeric;
  target uuid;
  new_id uuid;
begin
  perform public.require_bot(p_key);
  link := public.bot_chat_link(p_chat_id);
  if link.uid is null then raise exception 'not_linked' using errcode = 'P0001'; end if;
  if not link.enabled then raise exception 'commands_off' using errcode = 'P0001'; end if;
  if public.plan_code_of(link.uid) = 'FREE' then raise exception 'plan_required' using errcode = 'P0001'; end if;
  perform public.bot_act_as(link.uid);
  target := coalesce((p_action ->> 'workspace_id')::uuid, link.ws);
  if not public.bot_ws_allowed(link.uid, link.ws, link.route_all, target) then
    raise exception 'not_writable' using errcode = '42501';
  end if;
  if kind not in ('EXPENSE', 'INCOME', 'REPAY') or amount is null or amount <= 0 or amount > 1e12 then
    raise exception 'invalid_action' using errcode = '22023';
  end if;
  if not exists (select 1 from public.wallets_accounts w where w.id = (p_action ->> 'wallet_id')::uuid and w.workspace_id = target and w.archived_at is null) then
    raise exception 'invalid_wallet' using errcode = '22023';
  end if;
  if kind = 'REPAY' then
    if not exists (select 1 from public.debts d where d.id = (p_action ->> 'debt_id')::uuid and d.workspace_id = target and d.status <> 'SETTLED') then
      raise exception 'invalid_debt' using errcode = '22023';
    end if;
  else
    if (p_action ->> 'currency') not in ('USD', 'KHR') then raise exception 'invalid_action' using errcode = '22023'; end if;
    if (p_action ->> 'category_id') is not null and not exists (
      select 1 from public.categories c where c.id = (p_action ->> 'category_id')::uuid and c.workspace_id = target and c.type::text = kind
    ) then
      raise exception 'invalid_category' using errcode = '22023';
    end if;
  end if;
  -- One open card per chat: a new message (or a workspace switch) replaces the previous proposal.
  delete from public.telegram_pending where chat_id = p_chat_id or expires_at < now();
  insert into public.telegram_pending (user_id, chat_id, action)
  values (link.uid, p_chat_id, p_action || jsonb_build_object('workspace_id', target))
  returning id into new_id;
  return new_id;
end;
$$;

-- The pending action behind a card (to switch its workspace).
create or replace function public.bot_pending(p_key text, p_chat_id bigint, p_pending_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return (select p.action from public.telegram_pending p where p.id = p_pending_id and p.chat_id = p_chat_id and p.expires_at >= now());
end;
$$;

-- ✅: as before, plus the target workspace must still be allowed for this chat.
create or replace function public.bot_confirm(p_key text, p_chat_id bigint, p_pending_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  p public.telegram_pending;
  link record;
  a jsonb;
  ws uuid;
  w public.wallets_accounts;
  d public.debts;
  rate numeric;
  currency text;
  tx_type public.transaction_type;
  ws_name text;
begin
  perform public.require_bot(p_key);
  delete from public.telegram_pending where id = p_pending_id and chat_id = p_chat_id and expires_at >= now() returning * into p;
  if p.id is null then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  link := public.bot_chat_link(p_chat_id);
  if link.uid is distinct from p.user_id or not link.enabled then raise exception 'commands_off' using errcode = 'P0001'; end if;
  if public.plan_code_of(p.user_id) = 'FREE' then raise exception 'plan_required' using errcode = 'P0001'; end if;
  a := p.action;
  ws := (a ->> 'workspace_id')::uuid;
  perform public.bot_act_as(p.user_id);
  if not public.bot_ws_allowed(p.user_id, link.ws, link.route_all, ws) then raise exception 'not_writable' using errcode = '42501'; end if;
  select name into ws_name from public.workspaces where id = ws;

  select * into w from public.wallets_accounts where id = (a ->> 'wallet_id')::uuid and workspace_id = ws and archived_at is null;
  if w.id is null then raise exception 'invalid_wallet' using errcode = '22023'; end if;
  if w.visibility = 'PERSONAL' and w.owner_id is not null and w.owner_id <> p.user_id then raise exception 'invalid_wallet' using errcode = '42501'; end if;
  select coalesce(khr_per_usd, 4000) into rate from public.workspaces where id = ws;

  if a ->> 'kind' = 'REPAY' then
    select * into d from public.debts where id = (a ->> 'debt_id')::uuid and workspace_id = ws;
    if d.id is null then raise exception 'invalid_debt' using errcode = '22023'; end if;
    perform public.record_debt_repayment(d.id, w.id, (a ->> 'amount')::numeric, rate, now(), nullif(a ->> 'note', ''));
    select * into d from public.debts where id = d.id;
    select * into w from public.wallets_accounts where id = w.id;
    return jsonb_build_object('ok', true, 'kind', 'REPAY', 'wallet', w.name, 'balance', w.balance, 'wallet_currency', w.currency,
      'remaining', d.total_amount - d.paid_amount, 'debt_currency', d.currency, 'party', d.party_name, 'workspace', ws_name);
  end if;

  currency := a ->> 'currency';
  tx_type := (a ->> 'kind')::public.transaction_type;
  if (a ->> 'category_id') is not null and not exists (
    select 1 from public.categories c where c.id = (a ->> 'category_id')::uuid and c.workspace_id = ws and c.type::text = a ->> 'kind'
  ) then
    raise exception 'invalid_category' using errcode = '22023';
  end if;
  insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date)
  values (ws, w.id, (a ->> 'category_id')::uuid, (a ->> 'amount')::numeric, currency::public.currency_code, tx_type,
          case when currency = w.currency::text then null else rate end, left(nullif(a ->> 'note', ''), 500), now());
  select * into w from public.wallets_accounts where id = w.id;
  return jsonb_build_object('ok', true, 'kind', a ->> 'kind', 'wallet', w.name, 'balance', w.balance, 'wallet_currency', w.currency, 'workspace', ws_name);
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.bot_context(text, bigint)',
    'public.bot_propose(text, bigint, jsonb)',
    'public.bot_pending(text, bigint, uuid)',
    'public.bot_confirm(text, bigint, uuid)'
  ] loop
    execute format('revoke all on function %s from public', f);
    execute format('grant execute on function %s to anon, authenticated', f);
  end loop;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261022000000_islamic_mode_prayer_bot.sql
-- ===========================================================================

-- Islamic Mode off = no Islamic content anywhere: the bot only sends prayer
-- times to people whose Islamic Lifestyle & Finance Mode is on. Their
-- prayer_alerts choice is kept, so turning the mode back on resumes them.
create or replace function public.bot_prayer_subscribers(p_key text)
returns table (user_id uuid, chat_id bigint, language text, province text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return query
    select l.user_id, l.chat_id, l.language, coalesce(l.prayer_province, 'phnom_penh')
    from public.telegram_links l
    join public.islamic_settings s on s.user_id = l.user_id and s.enabled
    where l.prayer_alerts;
end;
$$;


-- ===========================================================================
-- 20261023000000_starter_wallets.sql
-- ===========================================================================

-- New accounts start with two wallets, so the first expense (in the app or
-- "កាហ្វេ 2$" to the bot) has somewhere to go: "សាច់ប្រាក់" (Cash) and
-- "កុងធនាគារ" (Bank account), in the workspace's default currency, at 0.
--
-- Only the Personal workspace gets them. They are extra: starter wallets don't
-- count toward the Free plan's wallet limit (decided 2026-10-03), so a Free
-- user still has their own slots, e.g. for the Business trial. Users rename
-- them freely (e.g. "ABA"); only the server sets is_starter. Runs once, when
-- the workspace is created, and never when it already has wallets; existing
-- accounts are not touched.

alter table public.wallets_accounts add column if not exists is_starter boolean not null default false;

create or replace function public.seed_starter_wallets()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.type = 'PERSONAL' and not exists (select 1 from public.wallets_accounts w where w.workspace_id = new.id) then
    insert into public.wallets_accounts (workspace_id, name, balance, currency, icon, sort_order, visibility, owner_id, is_starter)
    values
      (new.id, 'សាច់ប្រាក់', 0, new.currency_default, 'cash', 0, 'SHARED', new.user_id, true),
      (new.id, 'កុងធនាគារ', 0, new.currency_default, 'other', 1, 'SHARED', new.user_id, true);
  end if;
  return new;
end;
$$;
revoke all on function public.seed_starter_wallets() from public, anon, authenticated;

drop trigger if exists workspaces_starter_wallets on public.workspaces;
create trigger workspaces_starter_wallets
  after insert on public.workspaces
  for each row execute function public.seed_starter_wallets();

-- The wallet limit, as before, but starter wallets don't use a slot.
create or replace function public.guard_wallet_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  owner uuid;
  max_wallets integer;
  used integer;
begin
  if (select auth.uid()) is null or coalesce(current_setting('luysmart.import', true), '') = 'on' then
    return new;
  end if;
  -- Only creating a wallet or bringing one back from the archive counts.
  if tg_op = 'UPDATE' and not (old.archived_at is not null and new.archived_at is null) then
    return new;
  end if;
  if new.archived_at is not null or new.goal_target is not null or new.is_starter then
    return new;
  end if;
  select user_id into owner from public.workspaces where id = new.workspace_id;
  max_wallets := (public.plan_of(owner)).max_wallets;
  if max_wallets is null then
    return new;
  end if;
  select count(*) into used
  from public.wallets_accounts w join public.workspaces ws on ws.id = w.workspace_id
  where ws.user_id = owner and w.archived_at is null and w.goal_target is null and not w.is_starter and w.id <> new.id;
  if used >= max_wallets then
    raise exception 'plan_limit:wallets' using errcode = 'P0001', hint = max_wallets::text;
  end if;
  return new;
end;
$$;


-- ===========================================================================
-- 20261024000000_market_live.sql
-- ===========================================================================

-- Live market rates, fetched by the server every 30 minutes and readable by
-- every signed-in user (app_settings "market_live", existing read policy):
--   - NBC official exchange rates (National Bank of Cambodia, via Frankfurter),
--   - international gold / platinum spot ($/oz) and the reference price per
--     damlung for each purity (spot × 1.20565 × purity).
-- The server has no master key: like the bot, it writes through a function
-- that checks the key derived from TELEGRAM_BOT_TOKEN. Admin-entered gold
-- rates ("gold_rates") stay as the manual override for local shop prices.

create or replace function public.bot_set_market(p_key text, p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  if jsonb_typeof(p_value) <> 'object' or pg_column_size(p_value) > 20000 then
    raise exception 'invalid market data' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at) values ('market_live', p_value, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;

-- Daily server jobs (e.g. the 08:00 community bulletin): true for the first
-- caller of the day only, so a restart or a second instance never repeats it.
create table if not exists public.bot_daily_runs (
  job text not null check (char_length(job) between 1 and 40),
  day date not null,
  ran_at timestamptz not null default now(),
  primary key (job, day)
);
alter table public.bot_daily_runs enable row level security;
revoke all on public.bot_daily_runs from anon, authenticated;

create or replace function public.bot_claim_daily(p_key text, p_job text, p_day date)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  perform public.require_bot(p_key);
  insert into public.bot_daily_runs (job, day) values (p_job, p_day) on conflict do nothing;
  get diagnostics n = row_count;
  delete from public.bot_daily_runs where day < current_date - 60;
  return n > 0;
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array['public.bot_set_market(text, jsonb)', 'public.bot_claim_daily(text, text, date)'] loop
    execute format('revoke all on function %s from public', f);
    execute format('grant execute on function %s to anon, authenticated', f);
  end loop;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261025000000_health_watchdog.sql
-- ===========================================================================

-- System health watchdog: the server samples its own health every minute and
-- stores one row every 5 minutes; alerts and the weekly summary go to admins
-- who linked the official bot. All through bot_* functions (bot key), like the
-- rest of the server: no master database key.

create table if not exists public.health_samples (
  at        timestamptz primary key default now(),
  ok        boolean not null,
  ram_pct   numeric(5, 1),
  cpu_pct   numeric(5, 1),
  disk_pct  numeric(5, 1),
  app_mem_pct numeric(5, 1),
  db_ms     integer,
  tg_ms     integer,
  issues    text[] not null default '{}'
);
alter table public.health_samples enable row level security;
revoke all on public.health_samples from anon, authenticated;

-- Also the database ping: the call itself is the round trip being measured.
create or replace function public.bot_record_health(p_key text, p_sample jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  if p_sample is null then
    return;
  end if;
  insert into public.health_samples (ok, ram_pct, cpu_pct, disk_pct, app_mem_pct, db_ms, tg_ms, issues)
  values (
    coalesce((p_sample ->> 'ok')::boolean, false),
    (p_sample ->> 'ram_pct')::numeric, (p_sample ->> 'cpu_pct')::numeric, (p_sample ->> 'disk_pct')::numeric,
    (p_sample ->> 'app_mem_pct')::numeric, (p_sample ->> 'db_ms')::integer, (p_sample ->> 'tg_ms')::integer,
    coalesce(array(select jsonb_array_elements_text(p_sample -> 'issues')), '{}')
  )
  on conflict (at) do nothing;
  delete from public.health_samples where at < now() - interval '35 days';
end;
$$;

-- A cheap round trip for the latency check.
create or replace function public.bot_ping(p_key text)
returns timestamptz
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return now();
end;
$$;

-- Weekly numbers: uptime = healthy 5-minute slots / slots in the period
-- (a slot without a sample means the server wasn't running).
create or replace function public.bot_health_summary(p_key text, p_days integer default 7)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  since timestamptz := now() - make_interval(days => greatest(1, least(p_days, 31)));
  slots integer := greatest(1, least(p_days, 31)) * 24 * 12;
begin
  perform public.require_bot(p_key);
  return (
    select jsonb_build_object(
      'samples', count(*),
      'slots', slots,
      'healthy', count(*) filter (where s.ok),
      'uptime_pct', round(100.0 * least(count(*) filter (where s.ok), slots) / slots, 2),
      'avg_db_ms', round(avg(s.db_ms)),
      'p95_db_ms', round((percentile_cont(0.95) within group (order by s.db_ms))::numeric),
      'avg_tg_ms', round(avg(s.tg_ms)),
      'max_ram_pct', max(s.ram_pct),
      'avg_ram_pct', round(avg(s.ram_pct), 1),
      'max_cpu_pct', max(s.cpu_pct),
      'avg_cpu_pct', round(avg(s.cpu_pct), 1),
      'last_disk_pct', (select h.disk_pct from public.health_samples h order by h.at desc limit 1),
      'issues', coalesce((select jsonb_agg(distinct i) from public.health_samples h, unnest(h.issues) i where h.at >= since), '[]'::jsonb)
    )
    from public.health_samples s
    where s.at >= since
  );
end;
$$;

-- Where alerts go: admins who linked the official bot.
create or replace function public.bot_admin_chats(p_key text)
returns table (chat_id bigint, language text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return query
    select l.chat_id, l.language
    from public.telegram_links l
    join public.app_admins a on a.user_id = l.user_id;
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.bot_record_health(text, jsonb)',
    'public.bot_ping(text)',
    'public.bot_health_summary(text, integer)',
    'public.bot_admin_chats(text)'
  ] loop
    execute format('revoke all on function %s from public', f);
    execute format('grant execute on function %s to anon, authenticated', f);
  end loop;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261026000000_market_read.sql
-- ===========================================================================

-- The server reads back the stored market data (after a restart, and to merge
-- an admin's /setgold): app_settings is readable by signed-in users only, and
-- the server has no user session, so it reads through the bot key like the
-- rest of its functions.
create or replace function public.bot_get_market(p_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return (select s.value from public.app_settings s where s.key = 'market_live');
end;
$$;
revoke all on function public.bot_get_market(text) from public;
grant execute on function public.bot_get_market(text) to anon, authenticated;


-- ===========================================================================
-- 20261027000000_admin_system_status.sql
-- ===========================================================================

-- /admin › System health & bot security: a small server event log, and one
-- admin-only function that gathers the status the dashboard shows.

-- Server events (feed failures, bulletins, alerts, rejected webhook calls…).
-- Written by the server through the bot key; read by admins only.
create table if not exists public.server_events (
  id      bigint generated always as identity primary key,
  at      timestamptz not null default now(),
  level   text not null check (level in ('info', 'warn', 'error', 'security')),
  source  text not null check (char_length(source) between 1 and 40),
  message text not null check (char_length(message) <= 300),
  -- Repeats folded into one row by the server (e.g. 37 rejected calls in 10 minutes).
  count   integer not null default 1 check (count >= 1)
);
create index if not exists server_events_at_idx on public.server_events (at desc);
alter table public.server_events enable row level security;
revoke all on public.server_events from anon, authenticated;

create or replace function public.bot_log_event(p_key text, p_level text, p_source text, p_message text, p_count integer default 1)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  insert into public.server_events (level, source, message, count)
  values (p_level, left(p_source, 40), left(coalesce(p_message, ''), 300), greatest(1, coalesce(p_count, 1)));
  delete from public.server_events where at < now() - interval '30 days';
end;
$$;
revoke all on function public.bot_log_event(text, text, text, text, integer) from public;
grant execute on function public.bot_log_event(text, text, text, text, integer) to anon, authenticated;

-- Everything the dashboard needs from the database, for admins (live session + 2FA).
create or replace function public.admin_system_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  since timestamptz := now() - interval '7 days';
begin
  if not public.is_admin() or not public.access_ok() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'now', now(),
    'latest_sample', (select to_jsonb(h) from public.health_samples h order by h.at desc limit 1),
    -- Healthy 5-minute slots since monitoring began (at most 7 days back).
    'uptime_7d', (
      select round(100.0 * least(count(*) filter (where h.ok), slots) / slots, 2)
      from public.health_samples h,
           lateral (select greatest(1, ceil(extract(epoch from now() - greatest(since, (select min(x.at) from public.health_samples x))) / 300))::int as slots) n
      where h.at >= since
      group by n.slots
    ),
    'samples_7d', (select count(*) from public.health_samples h where h.at >= since),
    'bulletin_runs', coalesce((
      select jsonb_agg(jsonb_build_object('day', r.day, 'ran_at', r.ran_at) order by r.day desc)
      from (select * from public.bot_daily_runs where job = 'community-bulletin' order by day desc limit 7) r
    ), '[]'::jsonb),
    'weekly_health_last', (select max(ran_at) from public.bot_daily_runs where job = 'weekly-health'),
    'bot', (select jsonb_build_object('username', c.username, 'activated_at', c.updated_at) from public.bot_config c limit 1),
    'linked_chats', (select count(*) from public.telegram_links),
    'admins_linked', (select count(*) from public.telegram_links l join public.app_admins a on a.user_id = l.user_id),
    'market_updated_at', (select s.updated_at from public.app_settings s where s.key = 'market_live'),
    'events', coalesce((
      select jsonb_agg(to_jsonb(e) order by e.at desc) from (select * from public.server_events order by at desc limit 25) e
    ), '[]'::jsonb),
    'security_24h', (select coalesce(sum(count), 0) from public.server_events where level = 'security' and at >= now() - interval '24 hours'),
    'errors_24h', (select coalesce(sum(count), 0) from public.server_events where level = 'error' and at >= now() - interval '24 hours')
  );
end;
$$;
revoke all on function public.admin_system_status() from public, anon;
grant execute on function public.admin_system_status() to authenticated;

-- Weekly summary: the same uptime basis (since monitoring began, at most the period).
create or replace function public.bot_health_summary(p_key text, p_days integer default 7)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  since timestamptz := now() - make_interval(days => greatest(1, least(p_days, 31)));
  slots integer;
begin
  perform public.require_bot(p_key);
  slots := greatest(1, ceil(extract(epoch from now() - greatest(since, coalesce((select min(x.at) from public.health_samples x), now()))) / 300))::int;
  return (
    select jsonb_build_object(
      'samples', count(*),
      'slots', slots,
      'healthy', count(*) filter (where s.ok),
      'uptime_pct', round(100.0 * least(count(*) filter (where s.ok), slots) / slots, 2),
      'avg_db_ms', round(avg(s.db_ms)),
      'p95_db_ms', round((percentile_cont(0.95) within group (order by s.db_ms))::numeric),
      'avg_tg_ms', round(avg(s.tg_ms)),
      'max_ram_pct', max(s.ram_pct),
      'avg_ram_pct', round(avg(s.ram_pct), 1),
      'max_cpu_pct', max(s.cpu_pct),
      'avg_cpu_pct', round(avg(s.cpu_pct), 1),
      'last_disk_pct', (select h.disk_pct from public.health_samples h order by h.at desc limit 1),
      'issues', coalesce((select jsonb_agg(distinct i) from public.health_samples h, unnest(h.issues) i where h.at >= since), '[]'::jsonb)
    )
    from public.health_samples s
    where s.at >= since
  );
end;
$$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261028000000_admin_test_plan.sql
-- ===========================================================================

-- Admin test mode: an admin can try their OWN account as FREE, PRO or ULTRA
-- for a few hours, to check limits end to end (app, database rules, bot).
-- The override sits in front of the real subscription in plan_code_of — the
-- one place every plan rule reads — so nothing else changes; the real
-- subscription is never touched, and the override expires by itself.
-- Admin statistics and the subscriber list keep reading real subscriptions.

create table if not exists public.admin_plan_overrides (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  plan_code  text not null references public.plans (code),
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);
alter table public.admin_plan_overrides enable row level security;
revoke all on public.admin_plan_overrides from anon, authenticated;

-- The plan in force: an admin's unexpired test plan, else the active subscription, else FREE.
create or replace function public.plan_code_of(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select o.plan_code from public.admin_plan_overrides o
     join public.app_admins a on a.user_id = o.user_id
     where o.user_id = p_user_id and o.expires_at > now()),
    (select s.plan_code from public.subscriptions s
     where s.user_id = p_user_id and s.status = 'ACTIVE' and s.current_period_end > now()),
    'FREE'
  );
$$;

-- Start / change / end the caller's test plan: 'FREE' | 'PRO' | 'ULTRA', or null to end it.
create or replace function public.admin_set_test_plan(p_tier text, p_hours integer default 2)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  v_code text;
begin
  if not public.is_admin() or not public.access_ok() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_tier is null or p_tier = '' then
    delete from public.admin_plan_overrides where user_id = uid;
    insert into public.server_events (level, source, message) values ('security', 'test-plan', 'Admin ended plan test mode');
    return public.my_plan();
  end if;
  v_code := case upper(p_tier) when 'FREE' then 'FREE' when 'PRO' then 'PRO_MONTHLY' when 'ULTRA' then 'ULTRA_MONTHLY' end;
  if v_code is null or not exists (select 1 from public.plans pl where pl.code = v_code) then
    raise exception 'invalid tier' using errcode = '22023';
  end if;
  insert into public.admin_plan_overrides (user_id, plan_code, expires_at)
  values (uid, v_code, now() + make_interval(hours => greatest(1, least(coalesce(p_hours, 2), 24))))
  on conflict (user_id) do update set plan_code = excluded.plan_code, expires_at = excluded.expires_at, created_at = now();
  insert into public.server_events (level, source, message)
  values ('security', 'test-plan', format('Admin testing own account as %s for %s h', upper(p_tier), greatest(1, least(coalesce(p_hours, 2), 24))));
  return public.my_plan();
end;
$$;
revoke all on function public.admin_set_test_plan(text, integer) from public, anon;
grant execute on function public.admin_set_test_plan(text, integer) to authenticated;

-- my_plan, as before, plus the active test plan (for the app's banner).
create or replace function public.my_plan()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  s public.subscriptions;
  used integer;
  first_business uuid;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select * into s from public.subscriptions where user_id = uid;
  select coalesce((select ai_queries from public.usage_counters where user_id = uid and month = public.current_ai_month()), 0) into used;
  select id into first_business from public.workspaces where user_id = uid and type = 'BUSINESS' order by created_at, id limit 1;
  return jsonb_build_object(
    'tier', p.tier,
    'plan_code', p.code,
    'period_end', case when p.tier <> 'FREE' then s.current_period_end end,
    'last_plan_code', s.plan_code,
    'last_period_end', s.current_period_end,
    'max_wallets', p.max_wallets,
    'max_family_members', p.max_family_members,
    'max_business_workspaces', p.max_business_workspaces,
    'business_trial_ends_at', case when p.tier = 'FREE' and first_business is not null then (public.workspace_plan_access(first_business)).trial_ends_at end,
    'ai_queries_per_month', p.ai_queries_per_month,
    'ai_queries_used', used,
    'can_export', p.can_export,
    'can_credit_score', p.can_credit_score,
    'is_admin', public.is_admin(),
    'test_plan', (
      select jsonb_build_object('tier', tp.tier, 'expires_at', o.expires_at)
      from public.admin_plan_overrides o join public.plans tp on tp.code = o.plan_code
      where o.user_id = uid and o.expires_at > now() and public.is_admin()
    )
  );
end;
$$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261029000000_chinese_locale.sql
-- ===========================================================================

-- Simplified Chinese (zh) as a third language: the official bot can talk to a
-- linked chat in Chinese, chosen in Settings › Telegram or with /lang zh.

alter table public.telegram_links drop constraint if exists telegram_links_language_check;
alter table public.telegram_links add constraint telegram_links_language_check check (language in ('km', 'en', 'zh'));

-- /lang km | en | zh from a linked chat. True when the chat is linked.
create or replace function public.bot_set_language(p_key text, p_chat_id bigint, p_language text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  perform public.require_bot(p_key);
  if p_language not in ('km', 'en', 'zh') then
    raise exception 'invalid language' using errcode = '22023';
  end if;
  update public.telegram_links set language = p_language where chat_id = p_chat_id;
  get diagnostics n = row_count;
  return n > 0;
end;
$$;
revoke all on function public.bot_set_language(text, bigint, text) from public;
grant execute on function public.bot_set_language(text, bigint, text) to anon, authenticated;


-- ===========================================================================
-- 20261030000000_upload_safety.sql
-- ===========================================================================

-- Statement files are read on the device and never uploaded, so the server
-- never holds one. When the device's safety check refuses a file (a program,
-- a macro workbook, a zip bomb, a PDF with scripts, a disguised file), it
-- reports it here: one row per refusal (reason only — never the file or its
-- name), a security event for /admin › System health, and after 3 refusals in
-- 24 hours statement import is paused for that account for 24 hours.

create table if not exists public.upload_rejections (
  id      bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  at      timestamptz not null default now(),
  reason  text not null check (reason in ('executable', 'macro', 'embedded', 'zip_bomb', 'pdf_active', 'mismatch', 'extension')),
  format  text not null default '' check (char_length(format) <= 8),
  size_kb integer not null default 0 check (size_kb >= 0)
);
create index if not exists upload_rejections_user_idx on public.upload_rejections (user_id, at desc);
alter table public.upload_rejections enable row level security;
revoke all on public.upload_rejections from anon, authenticated;

-- When the caller's statement import is paused until, or null.
create or replace function public.statement_import_blocked_until()
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select case when count(*) >= 3 then max(r.at) + interval '24 hours' end
  from public.upload_rejections r
  where r.user_id = (select auth.uid()) and r.at > now() - interval '24 hours';
$$;
revoke all on function public.statement_import_blocked_until() from public, anon;
grant execute on function public.statement_import_blocked_until() to authenticated;

-- The device refused a file: record it, tell the admins, maybe pause imports.
create or replace function public.report_unsafe_upload(p_reason text, p_format text default '', p_size_kb integer default 0)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  recent integer;
begin
  if uid is null or not public.access_ok() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select count(*) into recent from public.upload_rejections where user_id = uid and at > now() - interval '24 hours';
  -- Already paused: nothing more is written, so this can't flood the log.
  if recent < 3 then
    insert into public.upload_rejections (user_id, reason, format, size_kb)
    values (uid, p_reason, lower(left(regexp_replace(coalesce(p_format, ''), '[^a-zA-Z0-9]', '', 'g'), 8)), greatest(0, least(coalesce(p_size_kb, 0), 1000000)));
    recent := recent + 1;
    insert into public.server_events (level, source, message)
    values ('security', 'upload', format('Unsafe statement file refused (%s, .%s, %s KB) · user %s%s',
      p_reason, coalesce(nullif(lower(left(regexp_replace(coalesce(p_format, ''), '[^a-zA-Z0-9]', '', 'g'), 8)), ''), '?'),
      greatest(0, coalesce(p_size_kb, 0)), left(uid::text, 8),
      case when recent >= 3 then ' — import paused 24 h' else '' end));
    delete from public.upload_rejections where at < now() - interval '30 days';
  end if;
  return jsonb_build_object('blocked_until', public.statement_import_blocked_until());
end;
$$;
revoke all on function public.report_unsafe_upload(text, text, integer) from public, anon;
grant execute on function public.report_unsafe_upload(text, text, integer) to authenticated;

select public.apply_security_gate();


-- ===========================================================================
-- 20261031000000_admin_console.sql
-- ===========================================================================

-- Admin console: account controls (suspend, require 2FA, business verified),
-- a richer user directory, and an append-only, hash-chained audit log of
-- every admin action.
--
-- Privacy: nothing here gives admins wallet, debt or transaction data — the
-- directory shows account and subscription metadata and counts only.

-- ---------------------------------------------------------------------------
-- Account controls
-- ---------------------------------------------------------------------------
create table if not exists public.account_controls (
  user_id              uuid primary key references auth.users (id) on delete cascade,
  suspended_at         timestamptz,
  suspended_reason     text check (suspended_reason is null or char_length(suspended_reason) <= 300),
  require_2fa          boolean not null default false,
  business_verified_at timestamptz,
  business_note        text check (business_note is null or char_length(business_note) <= 300),
  updated_at           timestamptz not null default now()
);
alter table public.account_controls enable row level security;
revoke all on public.account_controls from anon, authenticated;

-- The caller's account is usable: not suspended, and 2FA passed when an admin requires it.
create or replace function public.account_ok()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select not exists (
    select 1 from public.account_controls c
    where c.user_id = (select auth.uid())
      and (c.suspended_at is not null or (c.require_2fa and coalesce(auth.jwt() ->> 'aal', '') <> 'aal2'))
  );
$$;
revoke all on function public.account_ok() from public, anon;
grant execute on function public.account_ok() to authenticated;

-- Every table's security gate and every workspace check go through access_ok.
create or replace function public.access_ok()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.session_alive() and public.mfa_ok() and public.account_ok();
$$;

-- For the app's own screens ("account suspended", "set up 2FA"): readable even when access_ok is false.
create or replace function public.my_account_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'suspended', coalesce(c.suspended_at is not null, false),
    'suspended_reason', c.suspended_reason,
    'require_2fa', coalesce(c.require_2fa, false)
  )
  from (select 1) one
  left join public.account_controls c on c.user_id = (select auth.uid());
$$;
revoke all on function public.my_account_status() from public, anon;
grant execute on function public.my_account_status() to authenticated;

-- ---------------------------------------------------------------------------
-- Audit log: append-only, each row chained to the previous one by SHA-256
-- ---------------------------------------------------------------------------
create table if not exists public.admin_audit_log (
  id           bigint generated always as identity primary key,
  seq          bigint not null unique,
  at           timestamptz not null default now(),
  actor_id     uuid,
  actor_email  text,
  session_id   uuid,
  action       text not null check (action ~ '^[A-Z0-9_]{3,40}$'),
  target_id    uuid,
  target_email text,
  note         text check (note is null or char_length(note) <= 500),
  ref          text check (ref is null or char_length(ref) <= 120),
  prev_hash    text not null,
  hash         text not null
);
-- No foreign keys on purpose: deleting a user must not touch (and so cannot be blocked by) the log.
create index if not exists admin_audit_log_at_idx on public.admin_audit_log (at desc);
create index if not exists admin_audit_log_target_idx on public.admin_audit_log (target_id, at desc);
alter table public.admin_audit_log enable row level security;
revoke all on public.admin_audit_log from anon, authenticated;

create or replace function public.audit_row_hash(r public.admin_audit_log)
returns text
language sql
immutable
set search_path = ''
as $$
  select encode(sha256(convert_to(concat_ws('|',
    r.prev_hash, r.seq, to_char(r.at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
    r.actor_id, r.actor_email, r.session_id, r.action, r.target_id, r.target_email, r.note, r.ref
  ), 'UTF8')), 'hex');
$$;

create or replace function public.admin_audit_log_chain()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  last public.admin_audit_log;
begin
  -- One writer at a time, so seq and prev_hash follow commit order.
  perform pg_advisory_xact_lock(hashtext('admin_audit_log'));
  select * into last from public.admin_audit_log order by seq desc limit 1;
  new.at := now();
  new.seq := coalesce(last.seq, 0) + 1;
  new.prev_hash := coalesce(last.hash, repeat('0', 64));
  new.hash := public.audit_row_hash(new);
  return new;
end;
$$;
drop trigger if exists admin_audit_log_chain on public.admin_audit_log;
create trigger admin_audit_log_chain before insert on public.admin_audit_log
  for each row execute function public.admin_audit_log_chain();

create or replace function public.admin_audit_log_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'admin_audit_log is append-only' using errcode = '42501';
end;
$$;
drop trigger if exists admin_audit_log_no_change on public.admin_audit_log;
create trigger admin_audit_log_no_change before update or delete on public.admin_audit_log
  for each row execute function public.admin_audit_log_immutable();
drop trigger if exists admin_audit_log_no_truncate on public.admin_audit_log;
create trigger admin_audit_log_no_truncate before truncate on public.admin_audit_log
  for each statement execute function public.admin_audit_log_immutable();

-- Write one entry. The actor is the signed-in admin unless given (Telegram /setgold).
create or replace function public.audit(p_action text, p_target uuid default null, p_note text default null, p_ref text default null, p_actor uuid default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := coalesce(p_actor, (select auth.uid()));
  v_session uuid;
begin
  begin
    v_session := case when p_actor is null then nullif(auth.jwt() ->> 'session_id', '')::uuid end;
  exception when others then
    v_session := null;
  end;
  insert into public.admin_audit_log (actor_id, actor_email, session_id, action, target_id, target_email, note, ref, seq, prev_hash, hash)
  values (
    v_actor, (select u.email::text from auth.users u where u.id = v_actor), v_session, p_action,
    p_target, (select u.email::text from auth.users u where u.id = p_target),
    left(nullif(btrim(coalesce(p_note, '')), ''), 500), left(p_ref, 120), 0, '', ''
  );
end;
$$;
revoke all on function public.audit(text, uuid, text, text, uuid) from public, anon, authenticated;

-- Existing admin actions, recorded where their changes land -----------------

-- Plan changes by an admin (extend, set end, cancel, approve / reject a payment).
create or replace function public.audit_subscription_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.actor is not null and new.actor <> new.user_id and exists (select 1 from public.app_admins a where a.user_id = new.actor) then
    perform public.audit(
      case new.kind
        when 'EXTENDED' then 'EXPIRY_EXTENDED'
        when 'SET_END' then 'EXPIRY_SET'
        when 'CANCELLED' then 'PLAN_CANCELLED'
        when 'REJECTED' then 'PAYMENT_REJECTED'
        else left('PLAN_' || upper(regexp_replace(new.kind, '[^A-Za-z0-9]+', '_', 'g')), 40)
      end,
      new.user_id,
      concat_ws(' · ', new.plan_code, case when new.period_end is not null then 'until ' || to_char(new.period_end at time zone 'Asia/Phnom_Penh', 'YYYY-MM-DD') end, new.note),
      coalesce(new.payment_id::text, 'subscription_event:' || new.id),
      new.actor
    );
  end if;
  return new;
end;
$$;
drop trigger if exists audit_subscription_events on public.subscription_events;
create trigger audit_subscription_events after insert on public.subscription_events
  for each row execute function public.audit_subscription_events();

-- 2FA reset for a user.
create or replace function public.audit_security_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.kind = 'MFA_RESET' and new.actor is not null then
    perform public.audit('MFA_RESET', new.user_id, new.note, 'security_event:' || new.id, new.actor);
  end if;
  return new;
end;
$$;
drop trigger if exists audit_security_events on public.security_events;
create trigger audit_security_events after insert on public.security_events
  for each row execute function public.audit_security_events();

-- Settings saved from /admin (payment instructions, support contacts, about, gold rates…).
-- The bot's own writes (live market data) have no signed-in admin and aren't logged.
create or replace function public.audit_app_settings()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and public.is_admin() then
    perform public.audit('SETTINGS_UPDATED', null, new.key, 'app_settings:' || new.key);
  end if;
  return new;
end;
$$;
drop trigger if exists audit_app_settings on public.app_settings;
create trigger audit_app_settings after insert or update on public.app_settings
  for each row execute function public.audit_app_settings();

-- Admin test plan on their own account.
create or replace function public.audit_plan_overrides()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    perform public.audit('TEST_PLAN_ENDED', old.user_id, null, null);
    return old;
  end if;
  perform public.audit('TEST_PLAN_SET', new.user_id, new.plan_code || ' until ' || to_char(new.expires_at at time zone 'Asia/Phnom_Penh', 'YYYY-MM-DD HH24:MI'), null);
  return new;
end;
$$;
drop trigger if exists audit_plan_overrides on public.admin_plan_overrides;
create trigger audit_plan_overrides after insert or update or delete on public.admin_plan_overrides
  for each row execute function public.audit_plan_overrides();

-- Bot (re)activation.
create or replace function public.audit_bot_config()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and public.is_admin() then
    perform public.audit('BOT_ACTIVATED', null, '@' || coalesce(new.username, '?'), null);
  end if;
  return new;
end;
$$;
drop trigger if exists audit_bot_config on public.bot_config;
create trigger audit_bot_config after insert or update on public.bot_config
  for each row execute function public.audit_bot_config();

-- Support ticket status / replies.
create or replace function public.audit_support_tickets()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and (select auth.uid()) <> new.user_id and public.is_admin()
     and (new.status is distinct from old.status or new.admin_reply is distinct from old.admin_reply) then
    perform public.audit('TICKET_UPDATED', new.user_id, new.status, 'ticket:' || new.id);
  end if;
  return new;
end;
$$;
do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'support_tickets' and column_name = 'admin_reply') then
    drop trigger if exists audit_support_tickets on public.support_tickets;
    create trigger audit_support_tickets after update on public.support_tickets
      for each row execute function public.audit_support_tickets();
  else
    raise warning 'support_tickets.admin_reply not found: ticket updates are not audited';
  end if;
end $$;

-- Gold prices set from /admin (server route, as the admin) ------------------
create or replace function public.admin_log_action(p_action text, p_note text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  if p_action not in ('SET_GOLD_OVERRIDE', 'CLEAR_GOLD_OVERRIDE') then
    raise exception 'invalid action' using errcode = '22023';
  end if;
  perform public.audit(p_action, null, p_note, null);
end;
$$;
revoke all on function public.admin_log_action(text, text) from public, anon;
grant execute on function public.admin_log_action(text, text) to authenticated;

-- …and from Telegram /setgold, by an admin's linked chat.
create or replace function public.bot_admin_audit(p_key text, p_chat_id bigint, p_action text, p_note text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_admin uuid;
begin
  perform public.require_bot(p_key);
  if p_action not in ('SET_GOLD_OVERRIDE', 'CLEAR_GOLD_OVERRIDE') then
    raise exception 'invalid action' using errcode = '22023';
  end if;
  select l.user_id into v_admin from public.telegram_links l join public.app_admins a on a.user_id = l.user_id where l.chat_id = p_chat_id limit 1;
  if v_admin is null then
    raise exception 'admin only' using errcode = '42501';
  end if;
  perform public.audit(p_action, null, concat_ws(' · ', p_note, 'via Telegram'), null, v_admin);
end;
$$;
revoke all on function public.bot_admin_audit(text, bigint, text, text) from public;
grant execute on function public.bot_admin_audit(text, bigint, text, text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- New admin actions
-- ---------------------------------------------------------------------------
create or replace function public.admin_check_target(p_user_id uuid, p_note text)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'user not found' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
end;
$$;
revoke all on function public.admin_check_target(uuid, text) from public, anon, authenticated;

-- Suspend: no data access (access_ok), signed out everywhere, Telegram unlinked. Reactivate undoes the block.
create or replace function public.admin_set_account_status(p_user_id uuid, p_suspend boolean, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.admin_check_target(p_user_id, p_note);
  if p_suspend then
    if p_user_id = (select auth.uid()) or exists (select 1 from public.app_admins a where a.user_id = p_user_id) then
      raise exception 'admins cannot be suspended' using errcode = '42501';
    end if;
    insert into public.account_controls (user_id, suspended_at, suspended_reason)
    values (p_user_id, now(), left(btrim(p_note), 300))
    on conflict (user_id) do update set suspended_at = now(), suspended_reason = excluded.suspended_reason, updated_at = now();
    delete from auth.sessions where user_id = p_user_id;
    delete from public.telegram_links where user_id = p_user_id;
    perform public.audit('ACCOUNT_SUSPENDED', p_user_id, p_note, null);
  else
    update public.account_controls set suspended_at = null, suspended_reason = null, updated_at = now() where user_id = p_user_id;
    perform public.audit('ACCOUNT_REACTIVATED', p_user_id, p_note, null);
  end if;
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.admin_set_account_status(uuid, boolean, text) from public, anon;
grant execute on function public.admin_set_account_status(uuid, boolean, text) to authenticated;

-- Require 2FA: until the user sets it up and passes it, the app shows only the 2FA setup.
create or replace function public.admin_set_require_2fa(p_user_id uuid, p_on boolean, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.admin_check_target(p_user_id, p_note);
  insert into public.account_controls (user_id, require_2fa) values (p_user_id, p_on)
  on conflict (user_id) do update set require_2fa = excluded.require_2fa, updated_at = now();
  perform public.audit(case when p_on then 'FORCE_2FA_ON' else 'FORCE_2FA_OFF' end, p_user_id, p_note, null);
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.admin_set_require_2fa(uuid, boolean, text) from public, anon;
grant execute on function public.admin_set_require_2fa(uuid, boolean, text) to authenticated;

-- Business verified: set by an admin after checking documents (the note says what was checked).
create or replace function public.admin_set_business_verified(p_user_id uuid, p_on boolean, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.admin_check_target(p_user_id, p_note);
  insert into public.account_controls (user_id, business_verified_at, business_note)
  values (p_user_id, case when p_on then now() end, case when p_on then left(btrim(p_note), 300) end)
  on conflict (user_id) do update set
    business_verified_at = excluded.business_verified_at, business_note = excluded.business_note, updated_at = now();
  perform public.audit(case when p_on then 'BUSINESS_VERIFIED' else 'BUSINESS_UNVERIFIED' end, p_user_id, p_note, null);
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.admin_set_business_verified(uuid, boolean, text) from public, anon;
grant execute on function public.admin_set_business_verified(uuid, boolean, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Directory and log for /admin
-- ---------------------------------------------------------------------------
create or replace function public.admin_list_users(p_search text, p_filter text, p_limit integer, p_offset integer)
returns table (
  user_id uuid, email text, display_name text, joined_at timestamptz, last_active_at timestamptz,
  plan_code text, tier text, status text, period_end timestamptz, pending_payments integer,
  workspace_count integer, telegram_linked boolean, phone_verified boolean, mfa_enabled boolean,
  suspended boolean, suspended_reason text, require_2fa boolean, business_verified boolean, business_note text,
  total bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return query
  with rows as (
    select
      u.id as user_id, u.email::text as email, pr.display_name, u.created_at as joined_at, public.last_active_at(u.id) as last_active_at,
      s.plan_code,
      case when s.status = 'ACTIVE' and s.current_period_end > now() then (case when s.plan_code like 'ULTRA%' then 'ULTRA' else 'PRO' end) else 'FREE' end as tier,
      s.status, s.current_period_end as period_end,
      (select count(*)::integer from public.payments p where p.user_id = u.id and p.status = 'PENDING') as pending_payments,
      (select count(*)::integer from public.workspace_members m where m.user_id = u.id) as workspace_count,
      exists (select 1 from public.telegram_links l where l.user_id = u.id) as telegram_linked,
      u.phone_confirmed_at is not null as phone_verified,
      exists (select 1 from auth.mfa_factors f where f.user_id = u.id and f.status = 'verified') as mfa_enabled,
      c.suspended_at is not null as suspended, c.suspended_reason,
      coalesce(c.require_2fa, false) as require_2fa,
      c.business_verified_at is not null as business_verified, c.business_note
    from auth.users u
    left join public.subscriptions s on s.user_id = u.id
    left join public.profiles pr on pr.id = u.id
    left join public.account_controls c on c.user_id = u.id
    where coalesce(p_search, '') = ''
      or u.email ilike '%' || p_search || '%'
      or pr.display_name ilike '%' || p_search || '%'
      or u.id::text = p_search
  ), filtered as (
    select * from rows r
    where case coalesce(p_filter, 'all')
      when 'pro' then r.tier <> 'FREE'
      when 'free' then r.tier = 'FREE'
      when 'expiring' then r.tier <> 'FREE' and r.period_end <= now() + interval '7 days'
      when 'expired' then r.tier = 'FREE' and r.period_end is not null
      when 'pending' then r.pending_payments > 0
      when 'suspended' then r.suspended
      else true
    end
  )
  select f.*, count(*) over () as total from filtered f
  order by f.pending_payments desc, f.suspended desc, f.period_end asc nulls last, f.joined_at desc
  limit least(coalesce(p_limit, 50), 500) offset greatest(coalesce(p_offset, 0), 0);
end;
$$;
revoke all on function public.admin_list_users(text, text, integer, integer) from public, anon;
grant execute on function public.admin_list_users(text, text, integer, integer) to authenticated;

create or replace function public.admin_audit_list(p_limit integer default 50, p_offset integer default 0, p_target uuid default null)
returns setof public.admin_audit_log
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return query
  select * from public.admin_audit_log l
  where p_target is null or l.target_id = p_target
  order by l.seq desc
  limit least(coalesce(p_limit, 50), 10000) offset greatest(coalesce(p_offset, 0), 0);
end;
$$;
revoke all on function public.admin_audit_list(integer, integer, uuid) from public, anon;
grant execute on function public.admin_audit_list(integer, integer, uuid) to authenticated;

-- Recomputes the whole chain: ok, number of entries, and the first entry that doesn't match.
create or replace function public.admin_audit_verify()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  r public.admin_audit_log;
  prev text := repeat('0', 64);
  expected bigint := 1;
  n bigint := 0;
begin
  perform public.require_admin();
  for r in select * from public.admin_audit_log order by seq loop
    if r.seq <> expected or r.prev_hash <> prev or r.hash <> public.audit_row_hash(r) then
      return jsonb_build_object('ok', false, 'entries', n, 'broken_at', r.seq);
    end if;
    prev := r.hash;
    expected := expected + 1;
    n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'entries', n, 'last_hash', case when n > 0 then prev end);
end;
$$;
revoke all on function public.admin_audit_verify() from public, anon;
grant execute on function public.admin_audit_verify() to authenticated;

select public.apply_security_gate();


-- ===========================================================================
-- 20261101000000_weekly_digest.sql
-- ===========================================================================

-- Weekly spending digest in Telegram (Sunday evening), opt-in per user.
--
-- The bot never shows finances unless asked: a digest puts weekly totals in
-- the chat, so it is OFF by default and the user switches it on in
-- Settings › Telegram (with a warning). PRO / ULTRA get the full digest;
-- FREE gets a teaser without amounts. The server receives per-category sums
-- of the bot's workspace for this week and last week — never transactions.

alter table public.telegram_links add column if not exists weekly_digest boolean not null default false;
grant update (weekly_digest) on public.telegram_links to authenticated;

create table if not exists public.telegram_digest_sent (
  user_id    uuid not null references auth.users (id) on delete cascade,
  week_start date not null,
  sent_at    timestamptz not null default now(),
  primary key (user_id, week_start)
);
alter table public.telegram_digest_sent enable row level security;
revoke all on public.telegram_digest_sent from anon, authenticated;

-- Opted-in chats not yet sent this week, with spending of the week starting
-- p_week_start (Monday, Cambodia time) and of the week before, by category.
-- Only chats with at least one expense this week are returned.
create or replace function public.bot_weekly_digest(p_key text, p_week_start date, p_limit integer default 50)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  this_from timestamptz := (p_week_start::timestamp) at time zone 'Asia/Phnom_Penh';
  this_to   timestamptz := ((p_week_start + 7)::timestamp) at time zone 'Asia/Phnom_Penh';
  last_from timestamptz := ((p_week_start - 7)::timestamp) at time zone 'Asia/Phnom_Penh';
  out jsonb := '[]'::jsonb;
  l record;
  link record;
  ws public.workspaces;
  rate numeric;
  cats jsonb;
  n integer;
begin
  perform public.require_bot(p_key);
  for l in
    select t.user_id, t.chat_id, t.language from public.telegram_links t
    where t.weekly_digest
      and not exists (select 1 from public.telegram_digest_sent s where s.user_id = t.user_id and s.week_start = p_week_start)
      and not exists (select 1 from public.account_controls c where c.user_id = t.user_id and c.suspended_at is not null)
    order by t.user_id
  loop
    exit when jsonb_array_length(out) >= least(coalesce(p_limit, 50), 200);
    select * into link from public.bot_chat_link(l.chat_id);
    continue when link.uid is distinct from l.user_id or link.ws is null;
    continue when not exists (select 1 from public.workspace_members m where m.workspace_id = link.ws and m.user_id = l.user_id);
    select * into ws from public.workspaces w where w.id = link.ws;
    rate := coalesce(ws.khr_per_usd, 4000);

    -- Expenses from wallets this member can see (not other members' personal wallets).
    select count(*) filter (where x.transaction_date >= this_from),
           coalesce(jsonb_agg(jsonb_build_object('id', x.category_id, 'preset_key', x.preset_key, 'name', x.name, 'icon', x.icon,
                                                 'this_usd', x.this_usd, 'last_usd', x.last_usd)) filter (where x.first), '[]'::jsonb)
      into n, cats
    from (
      select tx.transaction_date, tx.category_id, c.preset_key, c.name, c.icon,
             row_number() over (partition by tx.category_id order by tx.id) = 1 as first,
             sum(case when tx.transaction_date >= this_from then case when tx.currency = 'USD' then tx.amount else tx.amount / rate end else 0 end) over (partition by tx.category_id) as this_usd,
             sum(case when tx.transaction_date < this_from then case when tx.currency = 'USD' then tx.amount else tx.amount / rate end else 0 end) over (partition by tx.category_id) as last_usd
      from public.transactions tx
      join public.wallets_accounts wa on wa.id = tx.wallet_id
      left join public.categories c on c.id = tx.category_id
      where tx.workspace_id = link.ws and tx.type = 'EXPENSE'
        and tx.transaction_date >= last_from and tx.transaction_date < this_to
        and (wa.visibility <> 'PERSONAL' or wa.owner_id is null or wa.owner_id = l.user_id)
    ) x;
    continue when coalesce(n, 0) = 0;

    out := out || jsonb_build_array(jsonb_build_object(
      'user_id', l.user_id, 'chat_id', l.chat_id, 'language', l.language, 'tier', public.bot_tier(l.user_id),
      'workspace', ws.name, 'workspace_type', ws.type, 'currency', ws.currency_default, 'rate', rate,
      'entries', n, 'categories', cats
    ));
  end loop;
  return out;
end;
$$;
revoke all on function public.bot_weekly_digest(text, date, integer) from public;
grant execute on function public.bot_weekly_digest(text, date, integer) to anon, authenticated;

create or replace function public.bot_mark_digest_sent(p_key text, p_user_id uuid, p_week_start date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  insert into public.telegram_digest_sent (user_id, week_start) values (p_user_id, p_week_start) on conflict do nothing;
  delete from public.telegram_digest_sent where week_start < current_date - 120;
end;
$$;
revoke all on function public.bot_mark_digest_sent(text, uuid, date) from public;
grant execute on function public.bot_mark_digest_sent(text, uuid, date) to anon, authenticated;

select public.apply_security_gate();


-- ===========================================================================
-- 20261102000000_staff_roles.sql
-- ===========================================================================

-- Staff roles (RBAC) and the Super Admin console, step 1.
--
-- Roles live on public.app_admins (the existing staff table):
--   support      support tickets and system health
--   admin        + payments, users, operations settings (everything /admin had)
--   super_admin  + business metrics, pricing and limits, partner hub, staff, audit log
-- is_admin() now means admin or super_admin, so every existing admin_*
-- function keeps working for those two roles. Every staff member is required
-- to use 2FA when added (account_controls.require_2fa), and every change is audited.
--
-- Bootstrap: the people who are admins today become super_admin. No e-mail
-- address is written into code; later changes go through the Staff module,
-- which never lets the last super_admin be removed or demoted.

alter table public.app_admins add column if not exists role text not null default 'admin';
alter table public.app_admins add column if not exists added_by uuid;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'app_admins_role_check') then
    alter table public.app_admins add constraint app_admins_role_check check (role in ('support', 'admin', 'super_admin'));
    update public.app_admins set role = 'super_admin';
  end if;
end $$;

-- Staff added from now on must use 2FA (admin_staff_set). Existing staff are not
-- forced here, so nobody is locked out by a deploy; the Staff list flags "No 2FA".

create or replace function public.staff_role()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select a.role from public.app_admins a where a.user_id = (select auth.uid());
$$;
revoke all on function public.staff_role() from public, anon;
grant execute on function public.staff_role() to authenticated;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.app_admins a where a.user_id = (select auth.uid()) and a.role in ('admin', 'super_admin'));
$$;

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.app_admins a where a.user_id = (select auth.uid()));
$$;
revoke all on function public.is_staff() from public, anon;
grant execute on function public.is_staff() to authenticated;

create or replace function public.is_super_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.app_admins a where a.user_id = (select auth.uid()) and a.role = 'super_admin');
$$;
revoke all on function public.is_super_admin() from public, anon;
grant execute on function public.is_super_admin() to authenticated;

create or replace function public.require_staff()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_staff() or not public.access_ok() then
    raise exception 'staff only' using errcode = '42501';
  end if;
end;
$$;
revoke all on function public.require_staff() from public, anon, authenticated;

create or replace function public.require_super_admin()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_super_admin() or not public.access_ok() then
    raise exception 'super admin only' using errcode = '42501';
  end if;
end;
$$;
revoke all on function public.require_super_admin() from public, anon, authenticated;

-- Re-scope existing functions by rewriting only their access check:
--   support tickets and system health → any staff;
--   business metrics, referral stats, payment details, audit log → super_admin.
do $$
declare
  f record;
  def text;
  changed text;
begin
  for f in
    select * from (values
      ('admin_list_tickets', 'perform public.require_admin();', 'perform public.require_staff();'),
      ('admin_update_ticket', 'perform public.require_admin();', 'perform public.require_staff();'),
      ('admin_system_status', 'if not public.is_admin() or not public.access_ok() then', 'if not public.is_staff() or not public.access_ok() then'),
      ('admin_overview', 'perform public.require_admin();', 'perform public.require_super_admin();'),
      ('admin_referral_stats', 'perform public.require_admin();', 'perform public.require_super_admin();'),
      ('admin_set_payment_instructions', 'perform public.require_admin();', 'perform public.require_super_admin();'),
      ('admin_audit_list', 'perform public.require_admin();', 'perform public.require_super_admin();'),
      ('admin_audit_verify', 'perform public.require_admin();', 'perform public.require_super_admin();')
    ) v(name, old_check, new_check)
  loop
    select pg_get_functiondef(p.oid) into def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = f.name;
    if def is null then
      raise exception 'function % not found', f.name;
    end if;
    if position(f.new_check in def) > 0 then
      continue; -- already re-scoped
    end if;
    changed := replace(def, f.old_check, f.new_check);
    if changed = def then
      raise exception 'access check not found in %', f.name;
    end if;
    execute changed;
  end loop;
end $$;

-- Admin chats for Telegram /setgold: admins and super admins (not support).
do $$
declare
  def text;
begin
  select pg_get_functiondef(p.oid) into def
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.proname = 'bot_admin_chats';
  if def is not null and position('a.role in' in def) = 0 then
    def := replace(def, 'join public.app_admins a on a.user_id = l.user_id', 'join public.app_admins a on a.user_id = l.user_id and a.role in (''admin'', ''super_admin'')');
    execute def;
  end if;
end $$;

-- Ticket updates by support staff are audited too.
create or replace function public.audit_support_tickets()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and (select auth.uid()) <> new.user_id and public.is_staff()
     and (new.status is distinct from old.status or new.admin_reply is distinct from old.admin_reply) then
    perform public.audit('TICKET_UPDATED', new.user_id, new.status, 'ticket:' || new.id);
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Audit log: IP address and structured details on new entries
-- ---------------------------------------------------------------------------
alter table public.admin_audit_log add column if not exists ip text check (ip is null or char_length(ip) <= 64);
alter table public.admin_audit_log add column if not exists metadata jsonb;

-- concat_ws skips nulls, so entries written before these columns hash exactly as before.
create or replace function public.audit_row_hash(r public.admin_audit_log)
returns text
language sql
immutable
set search_path = ''
as $$
  select encode(sha256(convert_to(concat_ws('|',
    r.prev_hash, r.seq, to_char(r.at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
    r.actor_id, r.actor_email, r.session_id, r.action, r.target_id, r.target_email, r.note, r.ref,
    r.ip, r.metadata::text
  ), 'UTF8')), 'hex');
$$;

-- The caller's IP as the API gateway saw it (first X-Forwarded-For entry), when called from a request.
create or replace function public.request_ip()
returns text
language plpgsql
stable
set search_path = ''
as $$
declare
  h jsonb;
begin
  h := nullif(current_setting('request.headers', true), '')::jsonb;
  return left(nullif(btrim(split_part(coalesce(h ->> 'x-forwarded-for', h ->> 'x-real-ip', ''), ',', 1)), ''), 64);
exception when others then
  return null;
end;
$$;

drop function if exists public.audit(text, uuid, text, text, uuid);
create or replace function public.audit(p_action text, p_target uuid default null, p_note text default null, p_ref text default null, p_actor uuid default null, p_metadata jsonb default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := coalesce(p_actor, (select auth.uid()));
  v_session uuid;
begin
  begin
    v_session := case when p_actor is null then nullif(auth.jwt() ->> 'session_id', '')::uuid end;
  exception when others then
    v_session := null;
  end;
  insert into public.admin_audit_log (actor_id, actor_email, session_id, action, target_id, target_email, note, ref, ip, metadata, seq, prev_hash, hash)
  values (
    v_actor, (select u.email::text from auth.users u where u.id = v_actor), v_session, p_action,
    p_target, (select u.email::text from auth.users u where u.id = p_target),
    left(nullif(btrim(coalesce(p_note, '')), ''), 500), left(p_ref, 120),
    case when p_actor is null then public.request_ip() end, p_metadata, 0, '', ''
  );
end;
$$;
revoke all on function public.audit(text, uuid, text, text, uuid, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Module E: staff
-- ---------------------------------------------------------------------------
create or replace function public.admin_staff_list()
returns table (user_id uuid, email text, display_name text, role text, added_at timestamptz, mfa_enabled boolean, last_active_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  return query
  select a.user_id, u.email::text, pr.display_name, a.role, a.created_at,
         exists (select 1 from auth.mfa_factors f where f.user_id = a.user_id and f.status = 'verified'),
         public.last_active_at(a.user_id)
  from public.app_admins a
  join auth.users u on u.id = a.user_id
  left join public.profiles pr on pr.id = a.user_id
  order by case a.role when 'super_admin' then 0 when 'admin' then 1 else 2 end, a.created_at;
end;
$$;
revoke all on function public.admin_staff_list() from public, anon;
grant execute on function public.admin_staff_list() to authenticated;

-- Give an existing LuyChlat account a staff role (or change it). 2FA becomes required for them.
create or replace function public.admin_staff_set(p_email text, p_role text, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
  v_old text;
begin
  perform public.require_super_admin();
  if p_role not in ('support', 'admin', 'super_admin') then
    raise exception 'invalid role' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  select u.id into v_user from auth.users u where lower(u.email) = lower(btrim(p_email));
  if v_user is null then
    return jsonb_build_object('ok', false, 'reason', 'no_account');
  end if;
  if v_user = (select auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'self');
  end if;
  select a.role into v_old from public.app_admins a where a.user_id = v_user;
  if v_old = 'super_admin' and p_role <> 'super_admin' and (select count(*) from public.app_admins where role = 'super_admin') <= 1 then
    return jsonb_build_object('ok', false, 'reason', 'last_super_admin');
  end if;
  insert into public.app_admins (user_id, role, added_by) values (v_user, p_role, (select auth.uid()))
  on conflict (user_id) do update set role = excluded.role;
  insert into public.account_controls (user_id, require_2fa) values (v_user, true)
  on conflict (user_id) do update set require_2fa = true, updated_at = now();
  perform public.audit(case when v_old is null then 'STAFF_ADDED' else 'STAFF_ROLE_CHANGED' end, v_user, p_note, null, null,
    jsonb_build_object('from', v_old, 'to', p_role));
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.admin_staff_set(text, text, text) from public, anon;
grant execute on function public.admin_staff_set(text, text, text) to authenticated;

-- Remove staff access (they stay a normal user; their sessions end).
create or replace function public.admin_staff_remove(p_user_id uuid, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old text;
begin
  perform public.require_super_admin();
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  if p_user_id = (select auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'self');
  end if;
  select a.role into v_old from public.app_admins a where a.user_id = p_user_id;
  if v_old is null then
    return jsonb_build_object('ok', false, 'reason', 'not_staff');
  end if;
  if v_old = 'super_admin' and (select count(*) from public.app_admins where role = 'super_admin') <= 1 then
    return jsonb_build_object('ok', false, 'reason', 'last_super_admin');
  end if;
  delete from public.app_admins where user_id = p_user_id;
  delete from public.admin_plan_overrides where user_id = p_user_id;
  delete from auth.sessions where user_id = p_user_id;
  perform public.audit('STAFF_REMOVED', p_user_id, p_note, null, null, jsonb_build_object('role', v_old));
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.admin_staff_remove(uuid, text) from public, anon;
grant execute on function public.admin_staff_remove(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Module A: business metrics
-- ---------------------------------------------------------------------------
-- Paying = an active subscription bought with money (KHQR or entered by an admin
-- after payment), not a trial, a referral reward or an admin's own test plan.
create or replace function public.admin_exec_metrics()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  month_ago timestamptz := now() - interval '30 days';
  paying_now integer;
  paying_then integer;
  churned integer;
  users_total integer;
begin
  perform public.require_super_admin();
  select count(*) into users_total from auth.users;
  select count(*) into paying_now from public.subscriptions s
  where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN');
  -- Paying 30 days ago: a paid period covered that moment.
  select count(*) into paying_then from public.subscriptions s
  where s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN') and s.current_period_start <= month_ago and s.current_period_end > month_ago;
  -- …and no longer paying now.
  select count(*) into churned from public.subscriptions s
  where s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN') and s.current_period_start <= month_ago and s.current_period_end > month_ago
    and not (s.status = 'ACTIVE' and s.current_period_end > now());
  return jsonb_build_object(
    'users', users_total,
    'dau', (select count(*) from auth.users u where public.last_active_at(u.id) > now() - interval '1 day'),
    'mau', (select count(*) from auth.users u where public.last_active_at(u.id) > month_ago),
    'new_30d', (select count(*) from auth.users u where u.created_at > month_ago),
    'paying_users', paying_now,
    'paying_by_tier', (
      select coalesce(jsonb_object_agg(t.tier, t.n), '{}'::jsonb) from (
        select p.tier, count(*) as n from public.subscriptions s join public.plans p on p.code = s.plan_code
        where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN')
        group by p.tier) t
    ),
    'trial_or_referral', (select count(*) from public.subscriptions s where s.status = 'ACTIVE' and s.current_period_end > now() and s.source in ('TRIAL', 'REFERRAL')),
    -- Monthly recurring revenue: each paying subscription at its plan's monthly equivalent.
    'mrr_usd', (
      select coalesce(round(sum(p.price_usd * 30.0 / greatest(p.period_days, 1)), 2), 0) from public.subscriptions s join public.plans p on p.code = s.plan_code
      where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN')
    ),
    'mrr_khr', (
      select coalesce(round(sum(p.price_khr * 30.0 / greatest(p.period_days, 1))), 0) from public.subscriptions s join public.plans p on p.code = s.plan_code
      where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN')
    ),
    'revenue_total', (select coalesce(jsonb_object_agg(x.currency, x.total), '{}'::jsonb) from (select currency, sum(amount) as total from public.payments where status = 'PAID' group by currency) x),
    'revenue_30d', (select coalesce(jsonb_object_agg(x.currency, x.total), '{}'::jsonb) from (select currency, sum(amount) as total from public.payments where status = 'PAID' and reviewed_at > month_ago group by currency) x),
    'payments_30d', (select count(*) from public.payments where status = 'PAID' and reviewed_at > month_ago),
    'conversion_pct', case when users_total > 0 then round(100.0 * paying_now / users_total, 1) end,
    'churn_30d_pct', case when paying_then > 0 then round(100.0 * churned / paying_then, 1) end,
    'churn_base', paying_then,
    'pending_payments', (select count(*) from public.payments where status = 'PENDING')
  );
end;
$$;
revoke all on function public.admin_exec_metrics() from public, anon;
grant execute on function public.admin_exec_metrics() to authenticated;

-- ---------------------------------------------------------------------------
-- Module B: prices and plan limits (public.plans is what the app and the
-- database already read, so a change applies at once, without a deploy)
-- ---------------------------------------------------------------------------
create or replace function public.admin_plans()
returns setof public.plans
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  return query select * from public.plans order by sort_order, code;
end;
$$;
revoke all on function public.admin_plans() from public, anon;
grant execute on function public.admin_plans() to authenticated;

-- Fields not given (null in p_changes) stay as they are; for limits, the key "unlimited" sets null.
create or replace function public.admin_update_plan(p_code text, p_changes jsonb, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  before public.plans;
  after public.plans;
  lim text;
begin
  perform public.require_super_admin();
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  select * into before from public.plans where code = p_code for update;
  if before.code is null then
    raise exception 'unknown plan' using errcode = '22023';
  end if;
  update public.plans p set
    price_usd = coalesce((p_changes ->> 'price_usd')::numeric, p.price_usd),
    price_khr = coalesce((p_changes ->> 'price_khr')::numeric, p.price_khr),
    ai_queries_per_month = coalesce((p_changes ->> 'ai_queries_per_month')::integer, p.ai_queries_per_month),
    business_trial_days = coalesce((p_changes ->> 'business_trial_days')::integer, p.business_trial_days),
    active = case when p.code = 'FREE' then true else coalesce((p_changes ->> 'active')::boolean, p.active) end
  where p.code = p_code;
  -- Nullable limits: a number, or "unlimited".
  foreach lim in array array['max_wallets', 'max_family_members', 'max_business_workspaces'] loop
    if p_changes ? lim then
      execute format('update public.plans set %I = $1 where code = $2', lim)
      using case when p_changes ->> lim = 'unlimited' then null else (p_changes ->> lim)::integer end, p_code;
    end if;
  end loop;
  select * into after from public.plans where code = p_code;
  if after.price_usd < 0 or after.price_khr < 0 or coalesce(after.max_wallets, 1) < 1 or coalesce(after.max_family_members, 0) < 0
     or coalesce(after.max_business_workspaces, 0) < 0 or after.ai_queries_per_month < 0 or after.business_trial_days < 0
     or (after.code <> 'FREE' and after.price_usd = 0) then
    raise exception 'invalid values' using errcode = '22023';
  end if;
  perform public.audit('PLAN_PRICING_UPDATED', null, p_note, 'plan:' || p_code, null,
    jsonb_build_object('before', to_jsonb(before) - 'sort_order', 'after', to_jsonb(after) - 'sort_order'));
  return to_jsonb(after);
end;
$$;
revoke all on function public.admin_update_plan(text, jsonb, text) from public, anon;
grant execute on function public.admin_update_plan(text, jsonb, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Module D: partner integrations. Configuration and status only — secret
-- values never enter the database; the server reads them from its environment
-- (secret_env names the variable).
-- ---------------------------------------------------------------------------
create table if not exists public.partner_integrations (
  id           uuid primary key default gen_random_uuid(),
  kind         text not null check (kind in ('BANK', 'MFI', 'CBC', 'BAKONG', 'OTHER')),
  name         text not null check (char_length(name) between 2 and 80),
  status       text not null default 'NOT_CONNECTED' check (status in ('NOT_CONNECTED', 'PLANNED', 'TESTING', 'LIVE', 'DISABLED')),
  endpoint_url text check (endpoint_url is null or (endpoint_url ~ '^https://' and char_length(endpoint_url) <= 300)),
  secret_env   text check (secret_env is null or secret_env ~ '^[A-Z][A-Z0-9_]{2,63}$'),
  notes        text check (notes is null or char_length(notes) <= 1000),
  updated_at   timestamptz not null default now(),
  updated_by   uuid
);
alter table public.partner_integrations enable row level security;
revoke all on public.partner_integrations from anon, authenticated;

create or replace function public.admin_partners()
returns setof public.partner_integrations
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  return query select * from public.partner_integrations order by kind, name;
end;
$$;
revoke all on function public.admin_partners() from public, anon;
grant execute on function public.admin_partners() to authenticated;

create or replace function public.admin_save_partner(p_id uuid, p_value jsonb, p_note text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  before jsonb;
begin
  perform public.require_super_admin();
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  if p_id is null then
    insert into public.partner_integrations (kind, name, status, endpoint_url, secret_env, notes, updated_by)
    values (p_value ->> 'kind', btrim(p_value ->> 'name'), coalesce(p_value ->> 'status', 'NOT_CONNECTED'),
            nullif(btrim(coalesce(p_value ->> 'endpoint_url', '')), ''), nullif(btrim(coalesce(p_value ->> 'secret_env', '')), ''),
            nullif(btrim(coalesce(p_value ->> 'notes', '')), ''), (select auth.uid()))
    returning id into v_id;
  else
    select to_jsonb(p) into before from public.partner_integrations p where p.id = p_id;
    update public.partner_integrations set
      kind = p_value ->> 'kind', name = btrim(p_value ->> 'name'), status = coalesce(p_value ->> 'status', status),
      endpoint_url = nullif(btrim(coalesce(p_value ->> 'endpoint_url', '')), ''),
      secret_env = nullif(btrim(coalesce(p_value ->> 'secret_env', '')), ''),
      notes = nullif(btrim(coalesce(p_value ->> 'notes', '')), ''),
      updated_at = now(), updated_by = (select auth.uid())
    where id = p_id
    returning id into v_id;
    if v_id is null then
      raise exception 'not found' using errcode = '22023';
    end if;
  end if;
  perform public.audit('PARTNER_SAVED', null, p_note, 'partner:' || v_id, null,
    jsonb_build_object('before', before, 'after', (select to_jsonb(p) from public.partner_integrations p where p.id = v_id)));
  return v_id;
end;
$$;
revoke all on function public.admin_save_partner(uuid, jsonb, text) from public, anon;
grant execute on function public.admin_save_partner(uuid, jsonb, text) to authenticated;

-- my_plan: add the caller's staff role for the app's navigation.
do $$
declare
  def text;
begin
  select pg_get_functiondef(p.oid) into def
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.proname = 'my_plan';
  if position('''staff_role''' in def) = 0 then
    def := replace(def, '''is_admin'', public.is_admin(),', '''is_admin'', public.is_admin(), ''staff_role'', public.staff_role(),');
    if position('''staff_role''' in def) = 0 then
      raise exception 'my_plan: is_admin field not found';
    end if;
    execute def;
  end if;
end $$;

select public.apply_security_gate();


