-- Referral campaign
-- ---------------------------------------------------------------------------
insert into public.app_settings (key, value)
values ('referral_campaign', '{"active": true, "referee_days": 7, "referrer_days": 7, "monthly_cap": 20, "max_account_age_days": 7, "daily_flag": 5}'::jsonb)
