create or replace function public.redeem_referral(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  normalized text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  c jsonb := public.referral_campaign();
  referrer uuid;
  this_month integer;
  ref public.referrals;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not coalesce((c ->> 'active')::boolean, true) then
    return jsonb_build_object('status', 'inactive');
  end if;
  -- Shares the invite-code guessing limit.
  if (select count(*) from public.invite_failures where user_id = uid and attempted_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('status', 'rate_limited');
  end if;
  select user_id into referrer from public.referral_codes where code = normalized;
  if referrer is null then
    insert into public.invite_failures (user_id) values (uid);
    return jsonb_build_object('status', 'invalid');
  end if;
  if referrer = uid then
    return jsonb_build_object('status', 'own_code');
  end if;
  if exists (select 1 from public.referrals where referred_id = uid) then
    return jsonb_build_object('status', 'already_redeemed');
  end if;
  if (select now() - created_at from auth.users where id = uid) >= make_interval(days => (c ->> 'max_account_age_days')::integer) then
    return jsonb_build_object('status', 'too_late');
  end if;

  select count(*) into this_month from public.referrals
  where referrer_id = referrer and referrer_rewarded
    and created_at >= date_trunc('month', now() at time zone 'Asia/Phnom_Penh') at time zone 'Asia/Phnom_Penh';

  insert into public.referrals (referrer_id, referred_id, code, referrer_rewarded, referred_rewarded, reward_days, referrer_reward_days)
  values (referrer, uid, normalized,
          this_month < (c ->> 'monthly_cap')::integer and not exists (select 1 from public.referral_blocks b where b.user_id = referrer),
          true, (c ->> 'referee_days')::integer, (c ->> 'referrer_days')::integer)
  returning * into ref;

  perform public.extend_subscription(uid, 'PRO_MONTHLY', ref.reward_days, 'REFERRAL', uid, 'Referral welcome bonus', null);
  if ref.referrer_rewarded then
    perform public.extend_subscription(referrer, 'PRO_MONTHLY', ref.referrer_reward_days, 'REFERRAL', uid, 'Referral reward', null);
  end if;
  return jsonb_build_object('status', 'ok', 'days', ref.reward_days);
end;
$$;

create or replace function public.my_referral()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  bytes bytea;
  new_code text;
  my_code text;
  account_age interval;
  c jsonb := public.referral_campaign();
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select code into my_code from public.referral_codes where user_id = uid;
  while my_code is null loop
    bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    new_code := '';
    for i in 0..7 loop
      new_code := new_code || substr(alphabet, get_byte(bytes, i) % 32 + 1, 1);
    end loop;
    insert into public.referral_codes (user_id, code) values (uid, new_code)
    on conflict do nothing
    returning code into my_code;
    if my_code is null then
      select code into my_code from public.referral_codes where user_id = uid;
    end if;
  end loop;
  select now() - created_at into account_age from auth.users where id = uid;
  return jsonb_build_object(
    'code', my_code,
    'invited', (select count(*) from public.referrals where referrer_id = uid),
    'days_earned', (select coalesce(sum(referrer_reward_days), 0) from public.referrals where referrer_id = uid and referrer_rewarded),
    'referred_by', (select r.code from public.referrals r where r.referred_id = uid),
    'can_redeem', coalesce((c ->> 'active')::boolean, true)
      and account_age < make_interval(days => (c ->> 'max_account_age_days')::integer)
      and not exists (select 1 from public.referrals where referred_id = uid),
    'active', coalesce((c ->> 'active')::boolean, true),
    'referee_days', (c ->> 'referee_days')::integer,
    'referrer_days', (c ->> 'referrer_days')::integer,
    'max_account_age_days', (c ->> 'max_account_age_days')::integer
  );
end;
$$;

-- Results, the campaign, and anti-fraud flags for the top referrers:
--   burst     ≥ daily_flag referrals in the last 24 hours
--   inactive  ≥ 5 referrals and over 80% of the friends never came back after day one
create or replace function public.admin_referral_stats()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  c jsonb := public.referral_campaign();
begin
  perform public.require_super_admin();
  return jsonb_build_object(
    'campaign', c,
    'total', (select count(*) from public.referrals),
    'last_30d', (select count(*) from public.referrals where created_at > now() - interval '30 days'),
    'days_granted', (select coalesce(sum(reward_days * (referred_rewarded)::int + referrer_reward_days * (referrer_rewarded)::int), 0) from public.referrals),
    'top', coalesce((
      select jsonb_agg(t order by t.invited desc)
      from (
        select r.referrer_id as user_id, u.email::text as email, pr.display_name, count(*) as invited,
               coalesce(sum(r.referrer_reward_days) filter (where r.referrer_rewarded), 0) as days_earned,
               count(*) filter (where r.created_at > now() - interval '24 hours') as last_24h,
               count(*) filter (where coalesce(public.last_active_at(r.referred_id), ru.created_at) < ru.created_at + interval '1 day') as inactive_friends,
               exists (select 1 from public.referral_blocks b where b.user_id = r.referrer_id) as blocked,
               array_remove(array[
                 case when count(*) filter (where r.created_at > now() - interval '24 hours') >= (c ->> 'daily_flag')::integer then 'burst' end,
                 case when count(*) >= 5 and count(*) filter (where coalesce(public.last_active_at(r.referred_id), ru.created_at) < ru.created_at + interval '1 day') > 0.8 * count(*) then 'inactive' end
               ], null) as flags
        from public.referrals r
        join auth.users u on u.id = r.referrer_id
        join auth.users ru on ru.id = r.referred_id
        left join public.profiles pr on pr.id = r.referrer_id
        group by r.referrer_id, u.email, pr.display_name
        order by count(*) desc
        limit 20
      ) t
    ), '[]'::jsonb)
  );
end;
$$;

create or replace function public.admin_set_referral_campaign(p_value jsonb, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  before jsonb := public.referral_campaign();
  v_next jsonb;
begin
  perform public.require_super_admin();
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  v_next := jsonb_build_object(
    'active', coalesce((p_value ->> 'active')::boolean, (before ->> 'active')::boolean),
    'referee_days', coalesce((p_value ->> 'referee_days')::integer, (before ->> 'referee_days')::integer),
    'referrer_days', coalesce((p_value ->> 'referrer_days')::integer, (before ->> 'referrer_days')::integer),
    'monthly_cap', coalesce((p_value ->> 'monthly_cap')::integer, (before ->> 'monthly_cap')::integer),
    'max_account_age_days', coalesce((p_value ->> 'max_account_age_days')::integer, (before ->> 'max_account_age_days')::integer),
    'daily_flag', coalesce((p_value ->> 'daily_flag')::integer, (before ->> 'daily_flag')::integer)
  );
  if (v_next ->> 'referee_days')::integer not between 1 and 90 or (v_next ->> 'referrer_days')::integer not between 0 and 90
     or (v_next ->> 'monthly_cap')::integer not between 0 and 1000 or (v_next ->> 'max_account_age_days')::integer not between 1 and 90
     or (v_next ->> 'daily_flag')::integer not between 1 and 1000 then
    raise exception 'invalid values' using errcode = '22023';
  end if;
  perform set_config('luychlat.audited', 'on', true);
  insert into public.app_settings (key, value, updated_at) values ('referral_campaign', v_next, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  perform public.audit('REFERRAL_CAMPAIGN_UPDATED', null, p_note, null, null, jsonb_build_object('before', before, 'after', v_next));
  return v_next;
end;
$$;
revoke all on function public.admin_set_referral_campaign(jsonb, text) from public, anon;
grant execute on function public.admin_set_referral_campaign(jsonb, text) to authenticated;

create or replace function public.admin_set_referrer_block(p_user_id uuid, p_block boolean, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  if p_block then
    insert into public.referral_blocks (user_id, note) values (p_user_id, left(btrim(p_note), 300)) on conflict (user_id) do update set note = excluded.note;
  else
    delete from public.referral_blocks where user_id = p_user_id;
  end if;
  perform public.audit(case when p_block then 'REFERRER_PAUSED' else 'REFERRER_UNPAUSED' end, p_user_id, p_note, null);
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.admin_set_referrer_block(uuid, boolean, text) from public, anon;
grant execute on function public.admin_set_referrer_block(uuid, boolean, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Promo codes: free days of PRO or ULTRA (not revenue)
-- ---------------------------------------------------------------------------
alter table public.subscriptions drop constraint if exists subscriptions_source_check;
alter table public.subscriptions add constraint subscriptions_source_check check (source in ('ADMIN', 'KHQR', 'TRIAL', 'REFERRAL', 'PROMO'));

-- A free reward on top of a paid plan keeps that plan (as for referrals).
do $$
declare
  def text := pg_get_functiondef('public.extend_subscription(uuid, text, integer, text, uuid, text, uuid)'::regprocedure);
begin
  if position('''PROMO''' in def) = 0 then
    def := replace(def, 'if p_source = ''REFERRAL'' and current_end is not null then', 'if p_source in (''REFERRAL'', ''PROMO'') and current_end is not null then');
    if position('''PROMO''' in def) = 0 then
      raise exception 'extend_subscription: reward check not found';
    end if;
    execute def;
  end if;
  -- Metrics: promo days are free PRO, like trials and referrals.
  def := pg_get_functiondef('public.admin_exec_metrics()'::regprocedure);
  if position('''PROMO''' in def) = 0 then
    def := replace(def, 's.source in (''TRIAL'', ''REFERRAL'')', 's.source in (''TRIAL'', ''REFERRAL'', ''PROMO'')');
    execute def;
  end if;
end $$;

create table if not exists public.promo_codes (
  code            text primary key check (code ~ '^[A-Z0-9]{4,20}$'),
  plan_code       text not null references public.plans (code),
  days            integer not null check (days between 1 and 366),
  max_redemptions integer check (max_redemptions is null or max_redemptions > 0),
  redeemed_count  integer not null default 0,
  new_users_only  boolean not null default false,
  expires_at      timestamptz,
  active          boolean not null default true,
  note            text check (note is null or char_length(note) <= 300),
  created_by      uuid,
  created_at      timestamptz not null default now()
);
alter table public.promo_codes enable row level security;
revoke all on public.promo_codes from anon, authenticated;

create table if not exists public.promo_redemptions (
  code        text not null references public.promo_codes (code) on delete cascade,
  user_id     uuid not null references auth.users (id) on delete cascade,
  redeemed_at timestamptz not null default now(),
  primary key (code, user_id)
);
alter table public.promo_redemptions enable row level security;
revoke all on public.promo_redemptions from anon, authenticated;

-- The signed-in user redeems a code: each code once per account.
create or replace function public.redeem_promo(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  normalized text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  p public.promo_codes;
  sub public.subscriptions;
begin
  if uid is null or not public.access_ok() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  -- Shares the code-guessing limit with invites and referrals.
  if (select count(*) from public.invite_failures where user_id = uid and attempted_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('status', 'rate_limited');
  end if;
  select * into p from public.promo_codes where code = normalized for update;
  if p.code is null or not p.active then
    insert into public.invite_failures (user_id) values (uid);
    return jsonb_build_object('status', 'invalid');
  end if;
  if p.expires_at is not null and p.expires_at <= now() then
    return jsonb_build_object('status', 'expired');
  end if;
  if p.max_redemptions is not null and p.redeemed_count >= p.max_redemptions then
    return jsonb_build_object('status', 'used_up');
  end if;
  if p.new_users_only and (select now() - created_at from auth.users where id = uid) >= interval '30 days' then
    return jsonb_build_object('status', 'new_users_only');
  end if;
  insert into public.promo_redemptions (code, user_id) values (p.code, uid) on conflict do nothing;
  if not found then
    return jsonb_build_object('status', 'already_redeemed');
  end if;
  update public.promo_codes set redeemed_count = redeemed_count + 1 where code = p.code;
  sub := public.extend_subscription(uid, p.plan_code, p.days, 'PROMO', uid, 'Promo code ' || p.code, null);
  return jsonb_build_object('status', 'ok', 'days', p.days, 'plan_code', sub.plan_code, 'period_end', sub.current_period_end);
end;
$$;
revoke all on function public.redeem_promo(text) from public, anon;
grant execute on function public.redeem_promo(text) to authenticated;

create or replace function public.admin_promos()
returns setof public.promo_codes
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  return query select * from public.promo_codes order by active desc, created_at desc;
end;
$$;
revoke all on function public.admin_promos() from public, anon;
grant execute on function public.admin_promos() to authenticated;

-- Create a code, or change an existing one (active, limits, expiry). The plan and days of a used code are kept.
create or replace function public.admin_save_promo(p_value jsonb, p_note text)
returns public.promo_codes
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_code text := upper(regexp_replace(coalesce(p_value ->> 'code', ''), '[^A-Za-z0-9]', '', 'g'));
  before public.promo_codes;
  after public.promo_codes;
begin
  perform public.require_super_admin();
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  if not exists (select 1 from public.plans where code = p_value ->> 'plan_code' and tier in ('PRO', 'ULTRA')) then
    raise exception 'invalid plan' using errcode = '22023';
  end if;
  select * into before from public.promo_codes where code = v_code for update;
  if before.code is null then
    insert into public.promo_codes (code, plan_code, days, max_redemptions, new_users_only, expires_at, active, note, created_by)
    values (v_code, p_value ->> 'plan_code', (p_value ->> 'days')::integer, nullif(p_value ->> 'max_redemptions', '')::integer,
            coalesce((p_value ->> 'new_users_only')::boolean, false), nullif(p_value ->> 'expires_at', '')::timestamptz,
            coalesce((p_value ->> 'active')::boolean, true), left(nullif(btrim(coalesce(p_value ->> 'note', '')), ''), 300), (select auth.uid()))
    returning * into after;
  else
    update public.promo_codes set
      plan_code = case when redeemed_count = 0 then p_value ->> 'plan_code' else plan_code end,
      days = case when redeemed_count = 0 then (p_value ->> 'days')::integer else days end,
      max_redemptions = nullif(p_value ->> 'max_redemptions', '')::integer,
      new_users_only = coalesce((p_value ->> 'new_users_only')::boolean, new_users_only),
      expires_at = nullif(p_value ->> 'expires_at', '')::timestamptz,
      active = coalesce((p_value ->> 'active')::boolean, active),
      note = left(nullif(btrim(coalesce(p_value ->> 'note', '')), ''), 300)
    where code = v_code
    returning * into after;
  end if;
  perform public.audit(case when before.code is null then 'PROMO_CREATED' else 'PROMO_UPDATED' end, null, p_note, 'promo:' || v_code, null,
    jsonb_build_object('before', case when before.code is not null then to_jsonb(before) end, 'after', to_jsonb(after)));
  return after;
end;
$$;
revoke all on function public.admin_save_promo(jsonb, text) from public, anon;
grant execute on function public.admin_save_promo(jsonb, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Statement imports per plan (lifetime count; null = unlimited). FREE keeps 1.
-- ---------------------------------------------------------------------------
alter table public.plans add column if not exists max_statement_imports integer check (max_statement_imports is null or max_statement_imports >= 0);
update public.plans set max_statement_imports = 1 where code = 'FREE' and max_statement_imports is null;

alter table public.statement_import_credits add column if not exists used_count integer not null default 1;

do $$
declare
  def text := pg_get_functiondef('public.import_statement(uuid, jsonb, jsonb, boolean)'::regprocedure);
  old_block constant text := $old$  if public.plan_code_of(uid) = 'FREE' then
    -- The one free import: claimed atomically, refused once used.
    insert into public.statement_import_credits (user_id) values (uid) on conflict (user_id) do nothing;
    if not found then
      raise exception 'plan_required' using errcode = 'P0001';
    end if;
  end if;$old$;
  new_block constant text := $new$  -- Imports allowed by the plan (null = unlimited), counted for the account and
  -- claimed atomically with the import, so a failed import uses nothing.
  if (select p.max_statement_imports from public.plans p where p.code = public.plan_code_of(uid)) is not null then
    insert into public.statement_import_credits as c (user_id, used_count)
    select uid, 1 where (select p.max_statement_imports from public.plans p where p.code = public.plan_code_of(uid)) >= 1
    on conflict (user_id) do update set used_count = c.used_count + 1, used_at = now()
      where c.used_count < (select p.max_statement_imports from public.plans p where p.code = public.plan_code_of(uid));
    if not found then
      raise exception 'plan_required' using errcode = 'P0001';
    end if;
  end if;$new$;
begin
  if position('max_statement_imports' in def) = 0 then
    if position(old_block in def) = 0 then
      raise exception 'import_statement: free-import block not found';
    end if;
    execute replace(def, old_block, new_block);
  end if;
end $$;

-- admin_update_plan: the import limit is editable like the other nullable limits.
do $$
declare
  def text := pg_get_functiondef('public.admin_update_plan(text, jsonb, text)'::regprocedure);
begin
  if position('max_statement_imports' in def) = 0 then
    def := replace(def, 'array[''max_wallets'', ''max_family_members'', ''max_business_workspaces'']',
                        'array[''max_wallets'', ''max_family_members'', ''max_business_workspaces'', ''max_statement_imports'']');
    if position('max_statement_imports' in def) = 0 then
      raise exception 'admin_update_plan: limits list not found';
    end if;
    execute def;
  end if;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261104000000_owner_guard.sql
-- ===========================================================================

-- The founder account is protected: no one (including other super admins)
-- can remove it from staff, demote it, or suspend it. The owner is the first
-- super admin (marked once here; no e-mail address is written into code).

alter table public.app_admins add column if not exists is_owner boolean not null default false;
create unique index if not exists app_admins_one_owner on public.app_admins (is_owner) where is_owner;

update public.app_admins set is_owner = true
where user_id = (select a.user_id from public.app_admins a where a.role = 'super_admin' order by a.created_at, a.user_id limit 1)
  and not exists (select 1 from public.app_admins o where o.is_owner);

-- The owner always stays super_admin.
create or replace function public.app_admins_guard_owner()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' and old.is_owner then
    raise exception 'the owner cannot be removed' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and old.is_owner and (new.role <> 'super_admin' or not new.is_owner) then
    raise exception 'the owner stays super_admin' using errcode = '42501';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;
drop trigger if exists app_admins_guard_owner on public.app_admins;
create trigger app_admins_guard_owner before update or delete on public.app_admins
  for each row execute function public.app_admins_guard_owner();

drop function if exists public.admin_staff_list();
create or replace function public.admin_staff_list()
returns table (user_id uuid, email text, display_name text, role text, is_owner boolean, added_at timestamptz, mfa_enabled boolean, last_active_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  return query
  select a.user_id, u.email::text, pr.display_name, a.role, a.is_owner, a.created_at,
         exists (select 1 from auth.mfa_factors f where f.user_id = a.user_id and f.status = 'verified'),
         public.last_active_at(a.user_id)
  from public.app_admins a
  join auth.users u on u.id = a.user_id
  left join public.profiles pr on pr.id = a.user_id
  order by a.is_owner desc, case a.role when 'super_admin' then 0 when 'admin' then 1 else 2 end, a.created_at;
end;
$$;
revoke all on function public.admin_staff_list() from public, anon;
grant execute on function public.admin_staff_list() to authenticated;

-- Friendly refusals before the trigger would raise.
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.admin_staff_set(text, text, text)'::regprocedure);
  if position('''owner''' in def) = 0 then
    def := replace(def, '  select a.role into v_old from public.app_admins a where a.user_id = v_user;',
      '  select a.role into v_old from public.app_admins a where a.user_id = v_user;
  if exists (select 1 from public.app_admins a where a.user_id = v_user and a.is_owner) then
    return jsonb_build_object(''ok'', false, ''reason'', ''owner'');
  end if;');
    if position('''owner''' in def) = 0 then
      raise exception 'admin_staff_set: role lookup not found';
    end if;
    execute def;
  end if;

  def := pg_get_functiondef('public.admin_staff_remove(uuid, text)'::regprocedure);
  if position('''owner''' in def) = 0 then
    def := replace(def, '  select a.role into v_old from public.app_admins a where a.user_id = p_user_id;',
      '  select a.role into v_old from public.app_admins a where a.user_id = p_user_id;
  if exists (select 1 from public.app_admins a where a.user_id = p_user_id and a.is_owner) then
    return jsonb_build_object(''ok'', false, ''reason'', ''owner'');
  end if;');
    if position('''owner''' in def) = 0 then
      raise exception 'admin_staff_remove: role lookup not found';
    end if;
    execute def;
  end if;
end $$;


-- ===========================================================================
-- 20261105000000_customers.sql
-- ===========================================================================

-- Business metrics count customers only: staff accounts (support, admin,
-- super_admin) and their payments are left out of users, activity, paying
-- users, MRR, revenue, conversion and churn. Plus a customer directory for
-- /admin/super (staff left out the same way).

create or replace function public.is_staff_user(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.app_admins a where a.user_id = p_user_id);
$$;
revoke all on function public.is_staff_user(uuid) from public, anon, authenticated;

-- Paying = an active plan bought with money (KHQR, or entered by an admin after
-- payment) — not a trial, referral reward, promo code or an admin's own test plan.
create or replace function public.admin_exec_metrics()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  month_ago timestamptz := now() - interval '30 days';
  paying_now integer;
  paying_then integer;
  churned integer;
  users_total integer;
begin
  perform public.require_super_admin();
  select count(*) into users_total from auth.users u where not public.is_staff_user(u.id);
  select count(*) into paying_now from public.subscriptions s
  where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN')
    and not public.is_staff_user(s.user_id);
  select count(*) into paying_then from public.subscriptions s
  where s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN') and s.current_period_start <= month_ago and s.current_period_end > month_ago
    and not public.is_staff_user(s.user_id);
  select count(*) into churned from public.subscriptions s
  where s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN') and s.current_period_start <= month_ago and s.current_period_end > month_ago
    and not (s.status = 'ACTIVE' and s.current_period_end > now())
    and not public.is_staff_user(s.user_id);
  return jsonb_build_object(
    'users', users_total,
    'staff_excluded', (select count(*) from public.app_admins),
    'dau', (select count(*) from auth.users u where not public.is_staff_user(u.id) and public.last_active_at(u.id) > now() - interval '1 day'),
    'mau', (select count(*) from auth.users u where not public.is_staff_user(u.id) and public.last_active_at(u.id) > month_ago),
    'new_30d', (select count(*) from auth.users u where not public.is_staff_user(u.id) and u.created_at > month_ago),
    'paying_users', paying_now,
    'paying_by_tier', (
      select coalesce(jsonb_object_agg(t.tier, t.n), '{}'::jsonb) from (
        select p.tier, count(*) as n from public.subscriptions s join public.plans p on p.code = s.plan_code
        where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN')
          and not public.is_staff_user(s.user_id)
        group by p.tier) t
    ),
    'trial_or_referral', (
      select count(*) from public.subscriptions s
      where s.status = 'ACTIVE' and s.current_period_end > now() and s.source in ('TRIAL', 'REFERRAL', 'PROMO') and not public.is_staff_user(s.user_id)
    ),
    'mrr_usd', (
      select coalesce(round(sum(p.price_usd * 30.0 / greatest(p.period_days, 1)), 2), 0) from public.subscriptions s join public.plans p on p.code = s.plan_code
      where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN') and not public.is_staff_user(s.user_id)
    ),
    'mrr_khr', (
      select coalesce(round(sum(p.price_khr * 30.0 / greatest(p.period_days, 1))), 0) from public.subscriptions s join public.plans p on p.code = s.plan_code
      where s.status = 'ACTIVE' and s.current_period_end > now() and s.plan_code <> 'FREE' and s.source in ('KHQR', 'ADMIN') and not public.is_staff_user(s.user_id)
    ),
    'revenue_total', (
      select coalesce(jsonb_object_agg(x.currency, x.total), '{}'::jsonb)
      from (select currency, sum(amount) as total from public.payments where status = 'PAID' and not public.is_staff_user(user_id) group by currency) x
    ),
    'revenue_30d', (
      select coalesce(jsonb_object_agg(x.currency, x.total), '{}'::jsonb)
      from (select currency, sum(amount) as total from public.payments where status = 'PAID' and reviewed_at > month_ago and not public.is_staff_user(user_id) group by currency) x
    ),
    'payments_30d', (select count(*) from public.payments where status = 'PAID' and reviewed_at > month_ago and not public.is_staff_user(user_id)),
    'conversion_pct', case when users_total > 0 then round(100.0 * paying_now / users_total, 1) end,
    'churn_30d_pct', case when paying_then > 0 then round(100.0 * churned / paying_then, 1) end,
    'churn_base', paying_then,
    'pending_payments', (select count(*) from public.payments where status = 'PENDING' and not public.is_staff_user(user_id))
  );
end;
$$;

-- Customer directory: account, Telegram, plan and payment metadata only (never finances).
--   filter: 'all' | 'paying' (active plan bought with money) | 'free' (no active plan)
create or replace function public.admin_customers(p_search text, p_filter text, p_limit integer, p_offset integer)
returns table (
  user_id uuid, email text, display_name text, telegram_username text, joined_at timestamptz, last_active_at timestamptz,
  plan_code text, tier text, source text, period_end timestamptz, status text,
  last_paid_at timestamptz, last_payment_method text, last_payment_amount numeric, last_payment_currency text, paid_count integer,
  total bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  return query
  with rows as (
    select
      u.id as user_id, u.email::text as email, pr.display_name, tl.username as telegram_username, u.created_at as joined_at,
      public.last_active_at(u.id) as last_active_at,
      s.plan_code, coalesce(case when s.status = 'ACTIVE' and s.current_period_end > now() then p.tier end, 'FREE') as tier,
      s.source, s.current_period_end as period_end,
      case
        when s.status = 'ACTIVE' and s.current_period_end > now() then 'ACTIVE'
        when s.user_id is not null and s.plan_code <> 'FREE' then 'EXPIRED'
        else 'FREE'
      end as status,
      lp.reviewed_at as last_paid_at, lp.method as last_payment_method, lp.amount as last_payment_amount, lp.currency::text as last_payment_currency,
      (select count(*)::integer from public.payments x where x.user_id = u.id and x.status = 'PAID') as paid_count
    from auth.users u
    left join public.profiles pr on pr.id = u.id
    left join public.telegram_links tl on tl.user_id = u.id
    left join public.subscriptions s on s.user_id = u.id
    left join public.plans p on p.code = s.plan_code
    left join lateral (
      select x.reviewed_at, x.method, x.amount, x.currency from public.payments x
      where x.user_id = u.id and x.status = 'PAID' order by x.reviewed_at desc nulls last limit 1
    ) lp on true
    where not public.is_staff_user(u.id)
      and (coalesce(p_search, '') = ''
        or u.email ilike '%' || p_search || '%'
        or pr.display_name ilike '%' || p_search || '%'
        or tl.username ilike '%' || p_search || '%')
  ), filtered as (
    select * from rows r
    where case coalesce(p_filter, 'all')
      when 'paying' then r.status = 'ACTIVE' and r.source in ('KHQR', 'ADMIN')
      when 'free' then r.status <> 'ACTIVE'
      else true
    end
  )
  select f.*, count(*) over () as total from filtered f
  order by (f.status = 'ACTIVE') desc, f.period_end asc nulls last, f.joined_at desc
  limit least(coalesce(p_limit, 30), 200) offset greatest(coalesce(p_offset, 0), 0);
end;
$$;
revoke all on function public.admin_customers(text, text, integer, integer) from public, anon;
grant execute on function public.admin_customers(text, text, integer, integer) to authenticated;


-- ===========================================================================
-- 20261106000000_rate_override_audit.sql
-- ===========================================================================

-- NBC rate overrides (/admin and Telegram /setrate) are audited like gold overrides.
do $$
declare
  f text;
  def text;
begin
  foreach f in array array['public.admin_log_action(text, text)', 'public.bot_admin_audit(text, bigint, text, text)'] loop
    def := pg_get_functiondef(f::regprocedure);
    if position('SET_RATE_OVERRIDE' in def) = 0 then
      def := replace(def, '(''SET_GOLD_OVERRIDE'', ''CLEAR_GOLD_OVERRIDE'')',
                          '(''SET_GOLD_OVERRIDE'', ''CLEAR_GOLD_OVERRIDE'', ''SET_RATE_OVERRIDE'', ''CLEAR_RATE_OVERRIDE'')');
      if position('SET_RATE_OVERRIDE' in def) = 0 then
        raise exception '%: allowed actions not found', f;
      end if;
      execute def;
    end if;
  end loop;
end $$;


-- ===========================================================================
-- 20261107000000_test_accounts.sql
-- ===========================================================================

-- Internal / test accounts: a super admin can mark a customer account as a
-- test account. Like staff, test accounts are left out of business metrics;
-- they stay in the customer list with a 🧪 badge so the mark can be undone.
-- The customer list also gains the sign-up provider and account status.

alter table public.account_controls add column if not exists is_test boolean not null default false;
alter table public.account_controls add column if not exists test_note text check (test_note is null or char_length(test_note) <= 300);

-- Left out of business metrics: staff (any role) and accounts marked as test.
create or replace function public.is_internal_user(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.app_admins a where a.user_id = p_user_id)
      or exists (select 1 from public.account_controls c where c.user_id = p_user_id and c.is_test);
$$;
revoke all on function public.is_internal_user(uuid) from public, anon, authenticated;

-- Metrics: staff and test accounts out (and say how many test accounts).
do $$
declare
  def text := pg_get_functiondef('public.admin_exec_metrics()'::regprocedure);
begin
  if position('is_internal_user' in def) = 0 then
    def := replace(def, 'public.is_staff_user(', 'public.is_internal_user(');
    def := replace(def, '''staff_excluded'', (select count(*) from public.app_admins),',
      '''staff_excluded'', (select count(*) from public.app_admins),
    ''test_excluded'', (select count(*) from public.account_controls c where c.is_test and not exists (select 1 from public.app_admins a where a.user_id = c.user_id)),');
    if position('test_excluded' in def) = 0 then
      raise exception 'admin_exec_metrics: staff_excluded not found';
    end if;
    execute def;
  end if;
end $$;

drop function if exists public.admin_customers(text, text, integer, integer);
create or replace function public.admin_customers(p_search text, p_filter text, p_limit integer, p_offset integer)
returns table (
  user_id uuid, email text, display_name text, telegram_username text, provider text, joined_at timestamptz, last_active_at timestamptz,
  plan_code text, tier text, source text, period_end timestamptz, status text,
  last_paid_at timestamptz, last_payment_method text, last_payment_amount numeric, last_payment_currency text, paid_count integer,
  is_test boolean, suspended boolean,
  total bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  return query
  with rows as (
    select
      u.id as user_id, u.email::text as email, pr.display_name, tl.username as telegram_username,
      coalesce(u.raw_app_meta_data ->> 'provider', 'email') as provider,
      u.created_at as joined_at, public.last_active_at(u.id) as last_active_at,
      s.plan_code, coalesce(case when s.status = 'ACTIVE' and s.current_period_end > now() then p.tier end, 'FREE') as tier,
      s.source, s.current_period_end as period_end,
      case
        when s.status = 'ACTIVE' and s.current_period_end > now() then 'ACTIVE'
        when s.user_id is not null and s.plan_code <> 'FREE' then 'EXPIRED'
        else 'FREE'
      end as status,
      lp.reviewed_at as last_paid_at, lp.method as last_payment_method, lp.amount as last_payment_amount, lp.currency::text as last_payment_currency,
      (select count(*)::integer from public.payments x where x.user_id = u.id and x.status = 'PAID') as paid_count,
      coalesce(c.is_test, false) as is_test,
      c.suspended_at is not null as suspended
    from auth.users u
    left join public.profiles pr on pr.id = u.id
    left join public.telegram_links tl on tl.user_id = u.id
    left join public.subscriptions s on s.user_id = u.id
    left join public.plans p on p.code = s.plan_code
    left join public.account_controls c on c.user_id = u.id
    left join lateral (
      select x.reviewed_at, x.method, x.amount, x.currency from public.payments x
      where x.user_id = u.id and x.status = 'PAID' order by x.reviewed_at desc nulls last limit 1
    ) lp on true
    where not public.is_staff_user(u.id)
      and (coalesce(p_search, '') = ''
        or u.email ilike '%' || p_search || '%'
        or pr.display_name ilike '%' || p_search || '%'
        or tl.username ilike '%' || p_search || '%')
  ), filtered as (
    select * from rows r
    where case coalesce(p_filter, 'all')
      when 'paying' then r.status = 'ACTIVE' and r.source in ('KHQR', 'ADMIN') and not r.is_test
      when 'free' then r.status <> 'ACTIVE' and not r.is_test
      when 'test' then r.is_test
      else true
    end
  )
  select f.*, count(*) over () as total from filtered f
  order by f.is_test, (f.status = 'ACTIVE') desc, f.period_end asc nulls last, f.joined_at desc
  limit least(coalesce(p_limit, 30), 200) offset greatest(coalesce(p_offset, 0), 0);
end;
$$;
revoke all on function public.admin_customers(text, text, integer, integer) from public, anon;
grant execute on function public.admin_customers(text, text, integer, integer) to authenticated;

create or replace function public.admin_set_test_account(p_user_id uuid, p_on boolean, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_super_admin();
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'note required' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'user not found' using errcode = '22023';
  end if;
  insert into public.account_controls (user_id, is_test, test_note)
  values (p_user_id, p_on, case when p_on then left(btrim(p_note), 300) end)
  on conflict (user_id) do update set is_test = excluded.is_test, test_note = excluded.test_note, updated_at = now();
  perform public.audit(case when p_on then 'ACCOUNT_MARKED_TEST' else 'ACCOUNT_UNMARKED_TEST' end, p_user_id, p_note, null);
  return jsonb_build_object('ok', true);
end;
$$;
revoke all on function public.admin_set_test_account(uuid, boolean, text) from public, anon;
grant execute on function public.admin_set_test_account(uuid, boolean, text) to authenticated;


-- ===========================================================================
-- 20261108000000_users_test_flag.sql
-- ===========================================================================

-- /admin › Users: the user row also says whether the account is marked as a
-- test account (shown and switchable there for super admins).
drop function if exists public.admin_list_users(text, text, integer, integer);
create or replace function public.admin_list_users(p_search text, p_filter text, p_limit integer, p_offset integer)
returns table (
  user_id uuid, email text, display_name text, joined_at timestamptz, last_active_at timestamptz,
  plan_code text, tier text, status text, period_end timestamptz, pending_payments integer,
  workspace_count integer, telegram_linked boolean, phone_verified boolean, mfa_enabled boolean,
  suspended boolean, suspended_reason text, require_2fa boolean, business_verified boolean, business_note text,
  is_test boolean,
  total bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  return query
  with rows as (
    select
      u.id as user_id, u.email::text as email, pr.display_name, u.created_at as joined_at, public.last_active_at(u.id) as last_active_at,
      s.plan_code,
      case when s.status = 'ACTIVE' and s.current_period_end > now() then (case when s.plan_code like 'ULTRA%' then 'ULTRA' else 'PRO' end) else 'FREE' end as tier,
      s.status, s.current_period_end as period_end,
      (select count(*)::integer from public.payments p where p.user_id = u.id and p.status = 'PENDING') as pending_payments,
      (select count(*)::integer from public.workspace_members m where m.user_id = u.id) as workspace_count,
      exists (select 1 from public.telegram_links l where l.user_id = u.id) as telegram_linked,
      u.phone_confirmed_at is not null as phone_verified,
      exists (select 1 from auth.mfa_factors f where f.user_id = u.id and f.status = 'verified') as mfa_enabled,
      c.suspended_at is not null as suspended, c.suspended_reason,
      coalesce(c.require_2fa, false) as require_2fa,
      c.business_verified_at is not null as business_verified, c.business_note,
      coalesce(c.is_test, false) as is_test
    from auth.users u
    left join public.subscriptions s on s.user_id = u.id
    left join public.profiles pr on pr.id = u.id
    left join public.account_controls c on c.user_id = u.id
    where coalesce(p_search, '') = ''
      or u.email ilike '%' || p_search || '%'
      or pr.display_name ilike '%' || p_search || '%'
      or u.id::text = p_search
  ), filtered as (
    select * from rows r
    where case coalesce(p_filter, 'all')
      when 'pro' then r.tier <> 'FREE'
      when 'free' then r.tier = 'FREE'
      when 'expiring' then r.tier <> 'FREE' and r.period_end <= now() + interval '7 days'
      when 'expired' then r.tier = 'FREE' and r.period_end is not null
      when 'pending' then r.pending_payments > 0
      when 'suspended' then r.suspended
      else true
    end
  )
  select f.*, count(*) over () as total from filtered f
  order by f.pending_payments desc, f.suspended desc, f.period_end asc nulls last, f.joined_at desc
  limit least(coalesce(p_limit, 50), 500) offset greatest(coalesce(p_offset, 0), 0);
end;
$$;
revoke all on function public.admin_list_users(text, text, integer, integer) from public, anon;
grant execute on function public.admin_list_users(text, text, integer, integer) to authenticated;


-- ===========================================================================
-- 20261109000000_digest_income.sql
-- ===========================================================================

-- Weekly digest, version 2: income as well as spending (net savings, savings
-- rate), and an on-demand /digest for chats that switched the digest on.
-- One calculation serves both the Sunday job and /digest.
--
-- Per category (INCOME and EXPENSE) of the bot's workspace: this week and last
-- week, converted to USD at the workspace rate. Transfers between wallets are
-- their own type and never counted; debt principal and adjustments are left
-- out in the app (as in Reports). Other members' personal wallets in a family
-- workspace are not counted.

create or replace function public.digest_for(p_user_id uuid, p_chat_id bigint, p_language text, p_week_start date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  this_from timestamptz := (p_week_start::timestamp) at time zone 'Asia/Phnom_Penh';
  this_to   timestamptz := ((p_week_start + 7)::timestamp) at time zone 'Asia/Phnom_Penh';
  last_from timestamptz := ((p_week_start - 7)::timestamp) at time zone 'Asia/Phnom_Penh';
  link record;
  ws public.workspaces;
  rate numeric;
  cats jsonb;
  n integer;
begin
  select * into link from public.bot_chat_link(p_chat_id);
  if link.uid is distinct from p_user_id or link.ws is null then
    return null;
  end if;
  if not exists (select 1 from public.workspace_members m where m.workspace_id = link.ws and m.user_id = p_user_id) then
    return null;
  end if;
  select * into ws from public.workspaces w where w.id = link.ws;
  rate := coalesce(ws.khr_per_usd, 4000);

  select count(*) filter (where x.transaction_date >= this_from),
         coalesce(jsonb_agg(jsonb_build_object('id', x.category_id, 'type', x.type, 'preset_key', x.preset_key, 'name', x.name, 'icon', x.icon,
                                               'this_usd', x.this_usd, 'last_usd', x.last_usd)) filter (where x.first), '[]'::jsonb)
    into n, cats
  from (
    select tx.transaction_date, tx.type, tx.category_id, c.preset_key, c.name, c.icon,
           row_number() over (partition by tx.type, tx.category_id order by tx.id) = 1 as first,
           sum(case when tx.transaction_date >= this_from then case when tx.currency = 'USD' then tx.amount else tx.amount / rate end else 0 end)
             over (partition by tx.type, tx.category_id) as this_usd,
           sum(case when tx.transaction_date < this_from then case when tx.currency = 'USD' then tx.amount else tx.amount / rate end else 0 end)
             over (partition by tx.type, tx.category_id) as last_usd
    from public.transactions tx
    join public.wallets_accounts wa on wa.id = tx.wallet_id
    left join public.categories c on c.id = tx.category_id
    where tx.workspace_id = link.ws and tx.type in ('INCOME', 'EXPENSE')
      and tx.transaction_date >= last_from and tx.transaction_date < this_to
      and (wa.visibility <> 'PERSONAL' or wa.owner_id is null or wa.owner_id = p_user_id)
  ) x;

  return jsonb_build_object(
    'user_id', p_user_id, 'chat_id', p_chat_id, 'language', p_language, 'tier', public.bot_tier(p_user_id),
    'workspace', ws.name, 'workspace_type', ws.type, 'currency', ws.currency_default, 'rate', rate,
    'entries', coalesce(n, 0), 'categories', cats
  );
end;
$$;
revoke all on function public.digest_for(uuid, bigint, text, date) from public, anon, authenticated;

-- The Sunday job: opted-in chats not yet sent this week, with entries this week.
create or replace function public.bot_weekly_digest(p_key text, p_week_start date, p_limit integer default 50)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  out jsonb := '[]'::jsonb;
  l record;
  d jsonb;
begin
  perform public.require_bot(p_key);
  for l in
    select t.user_id, t.chat_id, t.language from public.telegram_links t
    where t.weekly_digest
      and not exists (select 1 from public.telegram_digest_sent s where s.user_id = t.user_id and s.week_start = p_week_start)
      and not exists (select 1 from public.account_controls c where c.user_id = t.user_id and c.suspended_at is not null)
    order by t.user_id
  loop
    exit when jsonb_array_length(out) >= least(coalesce(p_limit, 50), 200);
    d := public.digest_for(l.user_id, l.chat_id, l.language, p_week_start);
    continue when d is null or (d ->> 'entries')::integer = 0;
    out := out || jsonb_build_array(d);
  end loop;
  return out;
end;
$$;

-- /digest: this chat's digest now, or why not ('not_linked', 'off', 'suspended').
create or replace function public.bot_digest_for_chat(p_key text, p_chat_id bigint, p_week_start date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  l public.telegram_links;
  d jsonb;
begin
  perform public.require_bot(p_key);
  select * into l from public.telegram_links t where t.chat_id = p_chat_id;
  if l.user_id is null then
    return jsonb_build_object('status', 'not_linked');
  end if;
  if exists (select 1 from public.account_controls c where c.user_id = l.user_id and c.suspended_at is not null) then
    return jsonb_build_object('status', 'suspended');
  end if;
  if not l.weekly_digest then
    return jsonb_build_object('status', 'off', 'language', l.language);
  end if;
  d := public.digest_for(l.user_id, l.chat_id, l.language, p_week_start);
  if d is null then
    return jsonb_build_object('status', 'not_linked', 'language', l.language);
  end if;
  return jsonb_build_object('status', 'ok', 'digest', d);
end;
$$;
revoke all on function public.bot_digest_for_chat(text, bigint, date) from public;
grant execute on function public.bot_digest_for_chat(text, bigint, date) to anon, authenticated;


-- ===========================================================================
-- 20261110000000_recurring_bills.sql
-- ===========================================================================

-- Bills & reminders: recurring bills of a workspace (electricity, water,
-- internet, rent, waste, loan repayments, NSSF contributions, other), with
-- reminders N days before each due date — in the app's notifications and, for
-- linked chats with due alerts on, in Telegram (the same pipeline as debt and
-- credit-card reminders). "Paid" covers one due date at a time and can log
-- the expense in a wallet.
--
-- NSSF (ប.ស.ស.) presets are defaults the user can edit (amounts and due rules
-- change; the app tells users to check them with NSSF).

create table if not exists public.recurring_bills (
  id            uuid primary key default gen_random_uuid(),
  workspace_id  uuid not null references public.workspaces (id) on delete cascade,
  created_by    uuid references auth.users (id) on delete set null default auth.uid(),
  title         text not null check (char_length(btrim(title)) between 1 and 80),
  kind          text not null default 'OTHER' check (kind in ('ELECTRICITY', 'WATER', 'INTERNET', 'RENT', 'WASTE', 'LOAN', 'NSSF', 'OTHER')),
  amount        numeric(15, 2) not null check (amount > 0),
  currency      public.currency_code not null default 'KHR',
  frequency     text not null default 'MONTHLY' check (frequency in ('MONTHLY', 'YEARLY')),
  -- MONTHLY: day of the month (29–31 fall on the month's last day when shorter).
  due_day       integer check (due_day between 1 and 31),
  -- YEARLY: the first due date; later ones fall on the same day each year.
  due_date      date,
  nssf_type     text check (nssf_type in ('self_employed_monthly', 'self_employed_yearly', 'enterprise')),
  -- Days before the due date to remind (the due day itself is always reminded).
  remind_days   integer[] not null default '{2}' check (array_length(remind_days, 1) <= 5 and 0 <= all (remind_days) and 60 >= all (remind_days)),
  category_id   uuid references public.categories (id) on delete set null,
  -- The last due date that is paid; the next one is the first after it.
  paid_until    date,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check ((frequency = 'MONTHLY' and due_day is not null) or (frequency = 'YEARLY' and due_date is not null))
);
create index if not exists recurring_bills_workspace_idx on public.recurring_bills (workspace_id);
alter table public.recurring_bills enable row level security;

drop policy if exists recurring_bills_select on public.recurring_bills;
create policy recurring_bills_select on public.recurring_bills
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists recurring_bills_insert on public.recurring_bills;
create policy recurring_bills_insert on public.recurring_bills
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists recurring_bills_update on public.recurring_bills;
create policy recurring_bills_update on public.recurring_bills
  for update to authenticated using (public.can_write_workspace(workspace_id)) with check (public.can_write_workspace(workspace_id));
drop policy if exists recurring_bills_delete on public.recurring_bills;
create policy recurring_bills_delete on public.recurring_bills
  for delete to authenticated using (public.can_write_workspace(workspace_id));
grant select, insert, update, delete on public.recurring_bills to authenticated;

-- The category must belong to the bill's workspace.
create or replace function public.guard_bill_category()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.category_id is not null and not exists (select 1 from public.categories c where c.id = new.category_id and c.workspace_id = new.workspace_id) then
    raise exception 'invalid category' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists recurring_bills_guard on public.recurring_bills;
create trigger recurring_bills_guard before insert or update on public.recurring_bills
  for each row execute function public.guard_bill_category();

-- The due date of a bill in a given month (day clamped to the month's length).
create or replace function public.bill_due_in_month(p_day integer, p_month date)
returns date
language sql
immutable
set search_path = ''
as $$
  select (date_trunc('month', p_month)::date + (least(p_day, extract(day from (date_trunc('month', p_month) + interval '1 month - 1 day'))::integer) - 1));
$$;

-- The next unpaid due date: the first occurrence after paid_until (or, for a
-- new bill, the first on or after the day it was created). It may be in the
-- past (overdue).
create or replace function public.bill_next_due(b public.recurring_bills)
returns date
language plpgsql
stable
set search_path = ''
as $$
declare
  after_day date := coalesce(b.paid_until, (b.created_at at time zone 'Asia/Phnom_Penh')::date - 1);
  d date;
  i integer := 0;
begin
  if b.frequency = 'MONTHLY' then
    d := public.bill_due_in_month(b.due_day, after_day);
    while d <= after_day and i < 24 loop
      d := public.bill_due_in_month(b.due_day, (date_trunc('month', d) + interval '1 month')::date);
      i := i + 1;
    end loop;
  else
    d := b.due_date;
    while d <= after_day and i < 50 loop
      d := (b.due_date + make_interval(years => i + 1))::date;
      i := i + 1;
    end loop;
  end if;
  return d;
end;
$$;
grant execute on function public.bill_next_due(public.recurring_bills) to authenticated;

-- Mark the next due date as paid; optionally log the expense in a wallet.
create or replace function public.mark_bill_paid(p_bill_id uuid, p_wallet_id uuid default null, p_amount numeric default null, p_date date default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  b public.recurring_bills;
  due date;
  w public.wallets_accounts;
  rate numeric;
  tx_id uuid;
begin
  select * into b from public.recurring_bills where id = p_bill_id for update;
  if b.id is null or not public.can_write_workspace(b.workspace_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  due := public.bill_next_due(b);
  if p_wallet_id is not null then
    perform public.require_wallet_writer(p_wallet_id);
    select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = b.workspace_id;
    if w.id is null then
      raise exception 'invalid wallet' using errcode = '22023';
    end if;
    select coalesce(khr_per_usd, 4000) into rate from public.workspaces where id = b.workspace_id;
    insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, transaction_date, note, exchange_rate, created_by)
    values (b.workspace_id, w.id, b.category_id, coalesce(p_amount, b.amount), b.currency, 'EXPENSE',
            coalesce(p_date::timestamp at time zone 'Asia/Phnom_Penh' + interval '12 hours', now()), left(b.title, 500),
            case when w.currency <> b.currency then rate end, (select auth.uid()))
    returning id into tx_id;
  end if;
  update public.recurring_bills set paid_until = due where id = b.id;
  return jsonb_build_object('paid_due', due, 'next_due', public.bill_next_due((select r from public.recurring_bills r where r.id = b.id)), 'transaction_id', tx_id);
end;
$$;
revoke all on function public.mark_bill_paid(uuid, uuid, numeric, date) from public, anon;
grant execute on function public.mark_bill_paid(uuid, uuid, numeric, date) to authenticated;

-- Reminders, as notifications (the official bot sends DUE_DATE ones to linked chats with due alerts on).
alter table public.notifications add column if not exists bill_id uuid references public.recurring_bills (id) on delete cascade;
create unique index if not exists notifications_bill_alert_unique on public.notifications (bill_id, alert_key) where bill_id is not null;

create or replace function public.run_bill_alerts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'Asia/Phnom_Penh')::date;
  b public.recurring_bills;
  due date;
  left_days integer;
  new_id uuid;
  n integer := 0;
begin
  for b in select * from public.recurring_bills where is_active loop
    due := public.bill_next_due(b);
    left_days := due - today;
    continue when not (left_days = 0 or left_days = any (b.remind_days));
    new_id := null;
    insert into public.notifications (workspace_id, bill_id, title, message, type, alert_key, scheduled_at)
    values (
      b.workspace_id, b.id,
      case when left_days = 0 then '🧾 ថ្ងៃនេះដល់ថ្ងៃបង់៖ ' || b.title else '🧾 ជិតដល់ថ្ងៃបង់ (' || translate(left_days::text, '0123456789', '០១២៣៤៥៦៧៨៩') || ' ថ្ងៃទៀត)៖ ' || b.title end,
      b.title || ' · ' || public.format_money_text(b.amount, b.currency) || ' · ថ្ងៃកំណត់ ' || to_char(due, 'DD/MM/YYYY')
        || case when b.kind = 'NSSF' then ' · សូមបង់ឱ្យទាន់ពេល ដើម្បីរក្សាសិទ្ធិ ប.ស.ស.' else ' · សូមបង់ឱ្យទាន់ពេល។' end,
      'DUE_DATE', 'BILL:' || due::text || ':' || left_days, now()
    )
    on conflict (bill_id, alert_key) where bill_id is not null do nothing
    returning id into new_id;
    if new_id is not null then
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;
revoke all on function public.run_bill_alerts() from public, anon, authenticated;

-- Every morning (08:10 Cambodia time), like the debt and card reminders.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'luychlat-bill-alerts';
    perform cron.schedule('luychlat-bill-alerts', '10 1 * * *', 'select public.run_bill_alerts()');
  else
    raise warning 'pg_cron is not installed: bill reminders are not scheduled';
  end if;
end $$;

select public.apply_security_gate();


-- ===========================================================================
-- 20261111000000_holy_day_alerts.sql
-- ===========================================================================

-- Buddhist holy-day (ថ្ងៃសីល) reminders in Telegram: opt-in per chat; the
-- server works out the days from the Khmer lunar calendar and sends the
-- evening before (18:00 Cambodia), once per holy day.

alter table public.telegram_links add column if not exists holy_day_alerts boolean not null default false;
grant update (holy_day_alerts) on public.telegram_links to authenticated;

create or replace function public.bot_holy_day_subscribers(p_key text)
returns table (user_id uuid, chat_id bigint, language text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return query
    select l.user_id, l.chat_id, l.language
    from public.telegram_links l
    where l.holy_day_alerts
      and not exists (select 1 from public.account_controls c where c.user_id = l.user_id and c.suspended_at is not null);
end;
$$;
revoke all on function public.bot_holy_day_subscribers(text) from public;
grant execute on function public.bot_holy_day_subscribers(text) to anon, authenticated;


-- ===========================================================================
-- 20261112000000_nssf_cards.sql
-- ===========================================================================

-- NSSF card vault (កាត ប.ស.ស. ឌីជីថល): the account holder's own NSSF cards
-- and their dependents' — name, relationship, NSSF ID and optional card
-- photos for hospital check-in. Private to the account (not shared with
-- workspace members): rows by user_id, photos in a private bucket folder per
-- user, shown through short-lived signed URLs. The number of active members
-- also suggests the NSSF bill amount (15,600៛ × members, editable).

create table if not exists public.nssf_members (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users (id) on delete cascade default auth.uid(),
  name         text not null check (char_length(btrim(name)) between 1 and 80),
  relationship text not null default 'self' check (relationship in ('self', 'spouse', 'child')),
  nssf_id      text check (nssf_id is null or (char_length(nssf_id) <= 40 and nssf_id ~ '^[A-Za-z0-9 ./-]*$')),
  front_path   text check (front_path is null or char_length(front_path) <= 200),
  back_path    text check (back_path is null or char_length(back_path) <= 200),
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists nssf_members_user_idx on public.nssf_members (user_id);
alter table public.nssf_members enable row level security;

drop policy if exists nssf_members_own on public.nssf_members;
create policy nssf_members_own on public.nssf_members
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
grant select, insert, update, delete on public.nssf_members to authenticated;

-- Photos must be in the owner's own folder; at most 10 members per account.
create or replace function public.guard_nssf_member()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (new.front_path is not null and new.front_path not like new.user_id::text || '/%')
     or (new.back_path is not null and new.back_path not like new.user_id::text || '/%') then
    raise exception 'invalid photo path' using errcode = '22023';
  end if;
  if tg_op = 'INSERT' and (select count(*) from public.nssf_members m where m.user_id = new.user_id) >= 10 then
    raise exception 'too many members' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists nssf_members_guard on public.nssf_members;
create trigger nssf_members_guard before insert or update on public.nssf_members
  for each row execute function public.guard_nssf_member();

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('nssf-cards', 'nssf-cards', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists nssf_cards_select on storage.objects;
create policy nssf_cards_select on storage.objects
  for select to authenticated
  using (bucket_id = 'nssf-cards' and (storage.foldername(name))[1] = (select auth.uid())::text and public.access_ok());
drop policy if exists nssf_cards_insert on storage.objects;
create policy nssf_cards_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'nssf-cards' and (storage.foldername(name))[1] = (select auth.uid())::text and public.access_ok());
drop policy if exists nssf_cards_delete on storage.objects;
create policy nssf_cards_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'nssf-cards' and (storage.foldername(name))[1] = (select auth.uid())::text and public.access_ok());

select public.apply_security_gate();


-- ===========================================================================
-- 20261113000000_bot_bills_ev.sql
-- ===========================================================================

-- Phase 3 follow-up: Telegram buttons on bill reminders (✅ paid / ⏰ remind
-- tomorrow), /nssf with the account's NSSF cards, and EV home-charging logs.

-- Bills: the wallet a bill is usually paid from, and a one-day snooze.
alter table public.recurring_bills add column if not exists wallet_id uuid references public.wallets_accounts (id) on delete set null;
alter table public.recurring_bills add column if not exists snooze_on date;

-- Paying from a wallet remembers it (for the Telegram ✅ button); paying clears a snooze.
do $$
declare
  def text := pg_get_functiondef('public.mark_bill_paid(uuid, uuid, numeric, date)'::regprocedure);
begin
  if position('snooze_on' in def) = 0 then
    def := replace(def, 'update public.recurring_bills set paid_until = due where id = b.id;',
      'update public.recurring_bills set paid_until = due, wallet_id = coalesce(p_wallet_id, wallet_id), snooze_on = null where id = b.id;');
    if position('snooze_on' in def) = 0 then
      raise exception 'mark_bill_paid: update not found';
    end if;
    execute def;
  end if;
end $$;

-- Reminders as before, plus a snoozed one on the snooze day.
create or replace function public.run_bill_alerts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'Asia/Phnom_Penh')::date;
  b public.recurring_bills;
  due date;
  left_days integer;
  snoozed boolean;
  new_id uuid;
  n integer := 0;
begin
  for b in select * from public.recurring_bills where is_active loop
    due := public.bill_next_due(b);
    left_days := due - today;
    snoozed := b.snooze_on = today;
    continue when not (left_days = 0 or left_days = any (b.remind_days) or snoozed);
    new_id := null;
    insert into public.notifications (workspace_id, bill_id, title, message, type, alert_key, scheduled_at)
    values (
      b.workspace_id, b.id,
      case
        when left_days < 0 then '🧾 ហួសថ្ងៃកំណត់ (' || translate((-left_days)::text, '0123456789', '០១២៣៤៥៦៧៨៩') || ' ថ្ងៃ)៖ ' || b.title
        when left_days = 0 then '🧾 ថ្ងៃនេះដល់ថ្ងៃបង់៖ ' || b.title
        else '🧾 ជិតដល់ថ្ងៃបង់ (' || translate(left_days::text, '0123456789', '០១២៣៤៥៦៧៨៩') || ' ថ្ងៃទៀត)៖ ' || b.title
      end,
      b.title || ' · ' || public.format_money_text(b.amount, b.currency) || ' · ថ្ងៃកំណត់ ' || to_char(due, 'DD/MM/YYYY')
        || case when b.kind = 'NSSF' then ' · សូមបង់ឱ្យទាន់ពេល ដើម្បីរក្សាសិទ្ធិ ប.ស.ស.' else ' · សូមបង់ឱ្យទាន់ពេល។' end,
      'DUE_DATE',
      'BILL:' || due::text || ':' || case when snoozed and not (left_days = 0 or left_days = any (b.remind_days)) then 'snz' || today::text else left_days::text end,
      now()
    )
    on conflict (bill_id, alert_key) where bill_id is not null do nothing
    returning id into new_id;
    if new_id is not null then
      n := n + 1;
    end if;
    if snoozed then
      update public.recurring_bills set snooze_on = null where id = b.id;
    end if;
  end loop;
  return n;
end;
$$;
revoke all on function public.run_bill_alerts() from public, anon, authenticated;

-- The bot's reminder queue now says which bill (and due date) a reminder is for.
drop function if exists public.bot_due_notifications(text, integer);
create or replace function public.bot_due_notifications(p_key text, p_limit integer default 100)
returns table (notification_id uuid, user_id uuid, chat_id bigint, language text, title text, message text, bill_id uuid, due date)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  return query
    select n.id, l.user_id, l.chat_id, l.language, n.title, n.message, n.bill_id,
           case when n.bill_id is not null then nullif(split_part(n.alert_key, ':', 2), '')::date end
    from public.notifications n
    join public.workspace_members wm on wm.workspace_id = n.workspace_id
    join public.telegram_links l on l.user_id = wm.user_id and l.debt_alerts
    where n.type = 'DUE_DATE'
      and n.created_at > now() - interval '2 days'
      and not exists (select 1 from public.telegram_deliveries d where d.notification_id = n.id and d.user_id = l.user_id)
    order by n.created_at
    limit least(greatest(p_limit, 1), 500);
end;
$$;
revoke all on function public.bot_due_notifications(text, integer) from public;
grant execute on function public.bot_due_notifications(text, integer) to anon, authenticated;

-- A reminder's buttons. 'paid': close that due date (if still the next one)
-- and, on a paid plan, log the expense from the bill's usual wallet (else the
-- first wallet in its currency). 'snooze': remind again tomorrow.
create or replace function public.bot_bill_action(p_key text, p_chat_id bigint, p_bill_id uuid, p_action text, p_due date default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  link record;
  b public.recurring_bills;
  due date;
  w public.wallets_accounts;
  rate numeric;
  logged boolean := false;
begin
  perform public.require_bot(p_key);
  select * into link from public.bot_chat_link(p_chat_id);
  if link.uid is null then
    return jsonb_build_object('status', 'not_linked');
  end if;
  select * into b from public.recurring_bills where id = p_bill_id for update;
  if b.id is null then
    return jsonb_build_object('status', 'gone');
  end if;
  perform public.bot_act_as(link.uid);
  if not public.can_write_workspace(b.workspace_id) then
    return jsonb_build_object('status', 'not_writable');
  end if;

  if p_action = 'snooze' then
    update public.recurring_bills set snooze_on = (now() at time zone 'Asia/Phnom_Penh')::date + 1 where id = b.id;
    return jsonb_build_object('status', 'snoozed', 'title', b.title);
  end if;
  if p_action <> 'paid' then
    raise exception 'invalid action' using errcode = '22023';
  end if;

  due := public.bill_next_due(b);
  if p_due is not null and due <> p_due then
    return jsonb_build_object('status', 'already', 'title', b.title, 'next_due', due);
  end if;
  if public.plan_code_of(link.uid) <> 'FREE' then
    select * into w from public.wallets_accounts x
    where x.workspace_id = b.workspace_id and x.archived_at is null
    order by (x.id = b.wallet_id) desc nulls last, (x.currency = b.currency) desc, x.created_at
    limit 1;
    if w.id is not null then
      select coalesce(khr_per_usd, 4000) into rate from public.workspaces where id = b.workspace_id;
      insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, transaction_date, note, exchange_rate, created_by)
      values (b.workspace_id, w.id, b.category_id, b.amount, b.currency, 'EXPENSE', now(), left(b.title, 500),
              case when w.currency <> b.currency then rate end, link.uid);
      logged := true;
    end if;
  end if;
  update public.recurring_bills set paid_until = due, snooze_on = null, wallet_id = coalesce(w.id, wallet_id) where id = b.id;
  return jsonb_build_object('status', 'paid', 'title', b.title, 'logged', logged, 'wallet', w.name,
    'amount', b.amount, 'currency', b.currency, 'next_due', public.bill_next_due((select r from public.recurring_bills r where r.id = b.id)),
    'plan_free', public.plan_code_of(link.uid) = 'FREE');
end;
$$;
revoke all on function public.bot_bill_action(text, bigint, uuid, text, date) from public;
grant execute on function public.bot_bill_action(text, bigint, uuid, text, date) to anon, authenticated;

-- /nssf: the account's own contributing NSSF members (names and IDs) for the linked chat.
create or replace function public.bot_nssf_members(p_key text, p_chat_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  uid uuid;
begin
  perform public.require_bot(p_key);
  select l.user_id into uid from public.telegram_links l where l.chat_id = p_chat_id;
  if uid is null then
    return null;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('name', m.name, 'relationship', m.relationship, 'nssf_id', m.nssf_id) order by m.created_at)
    from public.nssf_members m where m.user_id = uid and m.is_active
  ), '[]'::jsonb);
end;
$$;
revoke all on function public.bot_nssf_members(text, bigint) from public;
grant execute on function public.bot_nssf_members(text, bigint) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- EV home charging: a usage log (kWh), never a wallet transaction — the cost
-- is in the electricity bill, so logging it as an expense would count it twice.
-- ---------------------------------------------------------------------------
create table if not exists public.ev_charge_logs (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  user_id      uuid references auth.users (id) on delete set null default auth.uid(),
  place        text not null default 'HOME' check (place in ('HOME')),
  kwh          numeric(8, 2) check (kwh is null or (kwh > 0 and kwh <= 500)),
  note         text check (note is null or char_length(note) <= 200),
  charged_at   timestamptz not null default now()
);
create index if not exists ev_charge_logs_ws_idx on public.ev_charge_logs (workspace_id, charged_at desc);
alter table public.ev_charge_logs enable row level security;
drop policy if exists ev_charge_logs_select on public.ev_charge_logs;
create policy ev_charge_logs_select on public.ev_charge_logs for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists ev_charge_logs_insert on public.ev_charge_logs;
create policy ev_charge_logs_insert on public.ev_charge_logs for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists ev_charge_logs_delete on public.ev_charge_logs;
create policy ev_charge_logs_delete on public.ev_charge_logs for delete to authenticated using (public.can_write_workspace(workspace_id));
grant select, insert, delete on public.ev_charge_logs to authenticated;

-- From the bot (paid plans, like chat logging): returns this month's total kWh.
create or replace function public.bot_log_ev_home(p_key text, p_chat_id bigint, p_kwh numeric, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  link record;
  month_start timestamptz := date_trunc('month', now() at time zone 'Asia/Phnom_Penh') at time zone 'Asia/Phnom_Penh';
begin
  perform public.require_bot(p_key);
  select * into link from public.bot_chat_link(p_chat_id);
  if link.uid is null or link.ws is null then
    return jsonb_build_object('status', 'not_linked');
  end if;
  if public.plan_code_of(link.uid) = 'FREE' then
    raise exception 'plan_required' using errcode = 'P0001';
  end if;
  if not link.enabled then
    raise exception 'commands_off' using errcode = 'P0001';
  end if;
  perform public.bot_act_as(link.uid);
  if not public.can_write_workspace(link.ws) then
    raise exception 'not_writable' using errcode = '42501';
  end if;
  insert into public.ev_charge_logs (workspace_id, user_id, kwh, note) values (link.ws, link.uid, p_kwh, left(p_note, 200));
  return jsonb_build_object('status', 'ok',
    'month_kwh', (select coalesce(sum(kwh), 0) from public.ev_charge_logs where workspace_id = link.ws and charged_at >= month_start),
    'month_count', (select count(*) from public.ev_charge_logs where workspace_id = link.ws and charged_at >= month_start));
end;
$$;
revoke all on function public.bot_log_ev_home(text, bigint, numeric, text) from public;
grant execute on function public.bot_log_ev_home(text, bigint, numeric, text) to anon, authenticated;

select public.apply_security_gate();


-- ===========================================================================
-- 20261114000000_channel_posts_fuel.sql
-- ===========================================================================

-- Community channel: remember the last market post so the next one replaces it
-- (deleteMessage), and audit fuel-price overrides (MoC rates entered by an admin).

-- Small server-side values the bot keeps between restarts (only listed names).
create or replace function public.bot_kv_get(p_key text, p_name text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  if p_name not in ('community_posts') then
    raise exception 'invalid name' using errcode = '22023';
  end if;
  return (select s.value from public.app_settings s where s.key = 'bot:' || p_name);
end;
$$;
revoke all on function public.bot_kv_get(text, text) from public;
grant execute on function public.bot_kv_get(text, text) to anon, authenticated;

create or replace function public.bot_kv_set(p_key text, p_name text, p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_bot(p_key);
  if p_name not in ('community_posts') or pg_column_size(p_value) > 2000 then
    raise exception 'invalid value' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at) values ('bot:' || p_name, p_value, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.bot_kv_set(text, text, jsonb) from public;
grant execute on function public.bot_kv_set(text, text, jsonb) to anon, authenticated;

-- Fuel overrides are audited like gold and NBC overrides.
do $$
declare
  f text;
  def text;
begin
  foreach f in array array['public.admin_log_action(text, text)', 'public.bot_admin_audit(text, bigint, text, text)'] loop
    def := pg_get_functiondef(f::regprocedure);
    if position('SET_FUEL_PRICES' in def) = 0 then
      def := replace(def, '''SET_RATE_OVERRIDE'', ''CLEAR_RATE_OVERRIDE'')',
                          '''SET_RATE_OVERRIDE'', ''CLEAR_RATE_OVERRIDE'', ''SET_FUEL_PRICES'')');
      if position('SET_FUEL_PRICES' in def) = 0 then
        raise exception '%: allowed actions not found', f;
      end if;
      execute def;
    end if;
  end loop;
end $$;


-- ===========================================================================
-- 20261115000000_bot_default_khmer.sql
-- ===========================================================================

-- The bot now defaults to Khmer: an English phone setting no longer picks
-- English. Chats that got English that way at link time move to Khmer once;
-- anyone can switch with /lang (buttons) or /en, /zh, /km.
update public.telegram_links set language = 'km' where language = 'en';


-- ===========================================================================
-- 20261116000000_debt_record_only_tranches.sql
-- ===========================================================================

-- Debts, part 2:
--   * Record-only repayments: a past repayment entered for the history only —
--     it lowers what is left, with its date, note and slip photo, but moves no
--     money (no wallet, no transaction), like a record-only borrowing.
--   * Slip photos on repayments.
--   * Borrowing tranches ("ខ្ចីបន្ថែម"): more money borrowed / lent on the same
--     debt later, with a date, note, slip and an optional wallet movement; the
--     debt total grows by it. Together they make the debt's timeline.

-- ---------------------------------------------------------------------------
-- Repayments: wallet and transaction become optional (record-only), plus a slip.
-- ---------------------------------------------------------------------------
alter table public.debt_repayments alter column wallet_id drop not null;
alter table public.debt_repayments alter column transaction_id drop not null;
alter table public.debt_repayments add column if not exists attachment_path text check (attachment_path is null or char_length(attachment_path) <= 200);
alter table public.debt_repayments drop constraint if exists debt_repayments_record_only_check;
alter table public.debt_repayments add constraint debt_repayments_record_only_check
  check ((wallet_id is null) = (transaction_id is null));

-- A wallet repayment must match its transaction; a record-only one has neither.
-- A slip must be the caller's own upload (the storage policy below shows it to
-- the workspace, so a foreign path would leak someone else's file).
create or replace function public.guard_debt_repayment()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.attachment_path is not null and new.attachment_path not like (select auth.uid())::text || '/%' then
    raise exception 'invalid attachment' using errcode = '22023';
  end if;
  if new.transaction_id is null and new.wallet_id is null then
    if new.amount_paid is null or new.amount_paid <= 0
       or new.amount_paid > (select d.total_amount - d.paid_amount from public.debts d where d.id = new.debt_id) then
      raise exception 'amount exceeds the remaining balance' using errcode = '22023';
    end if;
    return new;
  end if;
  if not exists (
    select 1 from public.transactions t
    where t.id = new.transaction_id
      and t.debt_id = new.debt_id
      and t.wallet_id = new.wallet_id
      and t.amount = new.amount_paid
  ) then
    raise exception 'repayment does not match its transaction' using errcode = '22023';
  end if;
  return new;
end;
$$;

-- Access: a member of the debt's workspace (writers to change); the wallet, when there is one, must be in it.
create or replace function public.debt_repayment_access(p_debt_id uuid, p_wallet_id uuid, p_write boolean)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.debts d
    join public.workspace_members m on m.workspace_id = d.workspace_id
    where d.id = p_debt_id
      and m.user_id = (select auth.uid())
      and (not p_write or m.role in ('OWNER', 'MEMBER'))
      and (p_wallet_id is null or exists (select 1 from public.wallets_accounts w where w.id = p_wallet_id and w.workspace_id = d.workspace_id))
  );
$$;

-- Record a repayment. With a wallet: as before (a transaction moves the money).
-- Without (p_wallet_id null): record-only. An optional slip photo path.
drop function if exists public.record_debt_repayment(uuid, uuid, numeric, numeric, timestamptz, text);
create or replace function public.record_debt_repayment(
  p_debt_id uuid,
  p_wallet_id uuid,
  p_amount numeric,
  p_exchange_rate numeric,
  p_payment_date timestamptz,
  p_note text,
  p_attachment text default null
)
returns public.debt_repayments
language plpgsql
set search_path = ''
as $$
declare
  d public.debts;
  w public.wallets_accounts;
  category_id uuid;
  tx_id uuid;
  result public.debt_repayments;
begin
  select * into d from public.debts where id = p_debt_id for update;
  if not found then
    raise exception 'debt not found' using errcode = 'P0002';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;
  if p_amount > d.total_amount - d.paid_amount then
    raise exception 'amount exceeds the remaining balance' using errcode = '22023';
  end if;
  if p_attachment is not null and p_attachment not like (select auth.uid())::text || '/%' then
    raise exception 'invalid attachment' using errcode = '22023';
  end if;

  if p_wallet_id is not null then
    select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = d.workspace_id;
    if not found then
      raise exception 'wallet not found in this workspace' using errcode = 'P0002';
    end if;
    if d.type = 'PAYABLE' then
      category_id := public.ensure_preset_category(d.workspace_id, 'debt_repayment', 'EXPENSE', 'hand-coins', '#64748b', 'សងបំណុល');
    else
      category_id := public.ensure_preset_category(d.workspace_id, 'debt_collection', 'INCOME', 'hand-coins', '#0ea5e9', 'ទទួលប្រាក់សងបំណុល');
    end if;
    insert into public.transactions (
      workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date, debt_id, receipt_url
    ) values (
      d.workspace_id, w.id, category_id, p_amount, d.currency,
      case when d.type = 'PAYABLE' then 'EXPENSE'::public.transaction_type else 'INCOME'::public.transaction_type end,
      case when w.currency = d.currency then null else p_exchange_rate end,
      coalesce(p_note, d.party_name), coalesce(p_payment_date, now()), d.id, p_attachment
    ) returning id into tx_id;
  end if;

  insert into public.debt_repayments (debt_id, wallet_id, amount_paid, payment_date, note, transaction_id, attachment_path)
  values (d.id, w.id, p_amount, coalesce(p_payment_date, now()), p_note, tx_id, p_attachment)
  returning * into result;
  return result;
end;
$$;
revoke all on function public.record_debt_repayment(uuid, uuid, numeric, numeric, timestamptz, text, text) from public, anon;
grant execute on function public.record_debt_repayment(uuid, uuid, numeric, numeric, timestamptz, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Borrowing tranches
-- ---------------------------------------------------------------------------
create table if not exists public.debt_tranches (
  id              uuid primary key default gen_random_uuid(),
  debt_id         uuid not null references public.debts (id) on delete cascade,
  amount          numeric(18, 2) not null check (amount > 0),
  tranche_date    timestamptz not null default now(),
  note            text check (note is null or char_length(note) <= 500),
  attachment_path text check (attachment_path is null or char_length(attachment_path) <= 200),
  wallet_id       uuid references public.wallets_accounts (id) on delete set null,
  transaction_id  uuid unique references public.transactions (id) on delete set null,
  created_by      uuid references auth.users (id) on delete set null default auth.uid(),
  created_at      timestamptz not null default now()
);
create index if not exists debt_tranches_debt_idx on public.debt_tranches (debt_id, tranche_date);
alter table public.debt_tranches enable row level security;
drop policy if exists debt_tranches_select on public.debt_tranches;
create policy debt_tranches_select on public.debt_tranches for select to authenticated using (public.debt_repayment_access(debt_id, null, false));
revoke insert, update, delete on public.debt_tranches from anon, authenticated;
grant select on public.debt_tranches to authenticated;

-- Add a tranche: the total grows by it; with a wallet the money moves (like the first disbursement).
create or replace function public.add_debt_tranche(
  p_debt_id uuid, p_amount numeric, p_date timestamptz, p_note text,
  p_wallet_id uuid default null, p_exchange_rate numeric default null, p_attachment text default null
)
returns public.debt_tranches
language plpgsql
security definer
set search_path = ''
as $$
declare
  d public.debts;
  w public.wallets_accounts;
  category_id uuid;
  tx_id uuid;
  result public.debt_tranches;
begin
  select * into d from public.debts where id = p_debt_id for update;
  if d.id is null or not public.debt_repayment_access(d.id, p_wallet_id, true) or not public.can_write_workspace(d.workspace_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if d.schedule_principal is not null then
    raise exception 'installment debts are changed by editing the schedule' using errcode = '22023';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 1e12 then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;
  if p_attachment is not null and p_attachment not like (select auth.uid())::text || '/%' then
    raise exception 'invalid attachment' using errcode = '22023';
  end if;

  update public.debts set total_amount = total_amount + p_amount where id = d.id;

  if p_wallet_id is not null then
    select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = d.workspace_id;
    if d.type = 'PAYABLE' then
      category_id := public.ensure_preset_category(d.workspace_id, 'loan_received', 'INCOME', 'landmark', '#6366f1', 'ប្រាក់ខ្ចីបានទទួល');
    else
      category_id := public.ensure_preset_category(d.workspace_id, 'loan_given', 'EXPENSE', 'hand-coins', '#f59e0b', 'ឱ្យគេខ្ចី');
    end if;
    insert into public.transactions (
      workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date, debt_id, receipt_url, created_by
    ) values (
      d.workspace_id, w.id, category_id, p_amount, d.currency,
      case when d.type = 'PAYABLE' then 'INCOME'::public.transaction_type else 'EXPENSE'::public.transaction_type end,
      case when w.currency = d.currency then null else p_exchange_rate end,
      coalesce(p_note, d.party_name), coalesce(p_date, now()), d.id, p_attachment, (select auth.uid())
    ) returning id into tx_id;
  end if;

  insert into public.debt_tranches (debt_id, amount, tranche_date, note, attachment_path, wallet_id, transaction_id)
  values (d.id, p_amount, coalesce(p_date, now()), left(nullif(btrim(coalesce(p_note, '')), ''), 500), p_attachment, w.id, tx_id)
  returning * into result;
  return result;
end;
$$;
revoke all on function public.add_debt_tranche(uuid, numeric, timestamptz, text, uuid, numeric, text) from public, anon;
grant execute on function public.add_debt_tranche(uuid, numeric, timestamptz, text, uuid, numeric, text) to authenticated;

-- Remove a tranche: the total shrinks (never below what was repaid) and its wallet movement is undone.
create or replace function public.delete_debt_tranche(p_tranche_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.debt_tranches;
  d public.debts;
begin
  select * into t from public.debt_tranches where id = p_tranche_id;
  if t.id is null then
    return;
  end if;
  select * into d from public.debts where id = t.debt_id for update;
  if not public.debt_repayment_access(d.id, null, true) or not public.can_write_workspace(d.workspace_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if d.total_amount - t.amount < d.paid_amount then
    raise exception 'amount exceeds the remaining balance' using errcode = '22023';
  end if;
  delete from public.debt_tranches where id = t.id;
  if t.transaction_id is not null then
    delete from public.transactions where id = t.transaction_id;
  end if;
  update public.debts set total_amount = total_amount - t.amount where id = d.id;
end;
$$;
revoke all on function public.delete_debt_tranche(uuid) from public, anon;
grant execute on function public.delete_debt_tranche(uuid) to authenticated;

-- Slip photos of repayments and tranches are visible to the debt's workspace members.
drop policy if exists receipts_select_debt_history on storage.objects;
create policy receipts_select_debt_history on storage.objects
  for select to authenticated
  using (
    bucket_id = 'receipts'
    and (
      exists (select 1 from public.debt_repayments r join public.debts d on d.id = r.debt_id
              where r.attachment_path = objects.name and public.is_workspace_member(d.workspace_id))
      or exists (select 1 from public.debt_tranches x join public.debts d on d.id = x.debt_id
                 where x.attachment_path = objects.name and public.is_workspace_member(d.workspace_id))
    )
  );

select public.apply_security_gate();
